insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ إِبْرَاهِيمَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ أَقْرَأُ عَلَى أَبِي الْقُرْآنَ فِي السِّكَّةِ، فَإِذَا قَرَأْتُ السَّجْدَةَ سَجَدَ، فَقُلْتُ: يَا أَبَتِ، أَتَسْجُدُ فِي الطَّرِيقِ؟ فَقَالَ: إِنِّي سَمِعْتُ أَبَا ذَرٍّ يَقُولُ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ مَسْجِدٍ وُضِعَ أَوَّلًا؟ قَالَ: "الْمَسْجِدُ الْحَرَامُ". قُلْتُ: ثُمَّ أَيُّ؟ قَالَ: "الْمَسْجِدُ الْأَقْصَى". قُلْتُ: وَكَمْ بَيْنَهُمَا؟ قَالَ: "أَرْبَعُونَ عَامًا، وَالْأَرْضُ لَكَ مَسْجِدٌ، فَحَيْثُمَا أَدْرَكْتَ الصَّلَاةَ فَصَلِّ". (م,ن,جه)', 'ഇബ്രാഹീം(റ): അദ്ദേഹം പറഞ്ഞു: വഴിയിൽ വെച്ച് ഞാനെന്റെ പിതാവിന് ഖുർആൻ പാരായണം കേൾപ്പിക്കുകയായിരുന്നു. സജദയുടെ ആയത്ത് ഓതിയപ്പോൾ അദ്ദേഹം സുജൂദ് ചെയ്തു. അപ്പോൾ ഞാൻ ചോദിച്ചു: പിതാവേ, താങ്കൾ വഴിയിൽ സുജൂദ് ചെയ്യുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: അബൂദർറ്(റ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: ഏതു പള്ളിയാണ് ആദ്യം നിർമ്മിക്കപ്പെട്ടത് എന്ന് ഞാൻ നബി(സ)യോട് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "മസ്ജിദുൽ ഹറാം." ഞാൻ ചോദിച്ചു: പിന്നെ ഏതാണ്? നബി(സ) പറഞ്ഞു: "മസ്ജിദുൽ അഖ്സാ." അവ രണ്ടിന്റെയും നിർമ്മാണത്തിനിടയിലുള്ള കാല ദൈർഘ്യം എത്രയെന്നു ചോദിച്ചപ്പോൾ നാൽപതു വർഷമാണെന്നും, ഭൂമി മുഴുവൻ പള്ളിയാണെന്നും നിനക്ക് എവിടെ വെച്ച് നിസ്കാരമായോ അപ്പോൾ (അവിടെ വെച്ച്) നീ നിസ്കരിക്കുക. (മു,ന,ജ)', 'إِبْرَاهِيمَ', 'ഇബ്രാഹീം(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 241, 241, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرَّ بِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ، فَقُلْتُ لَهُ: كَيْفَ سَمِعْتَ أَبَاكَ يَقُولُ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى؟ قَالَ: قَالَ أَبِي: دَخَلْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ بَعْضِ نِسَائِهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَيُّ الْمَسْجِدَيْنِ الَّذِي أُسِّسَ عَلَى التَّقْوَى؟ قَالَ: فَأَخَذَ كَفًّا مِنْ حَصًى فَضَرَبَ بِهِ الْأَرْضَ ثُمَّ قَالَ: "هُوَ هَذَا". لِمَسْجِدِ الْمَدِينَةِ. قَالَ: فَقُلْتُ: أَتَشْهَدُ لَسَمِعْتَ أَبَاكَ هَكَذَا يَذْكُرُهُ. (م)', 'അബുസലമതുബ്നു അബ്ദുറഹിമാൻ(റ): അബ്ദുറഹിമാനുബ്നു അബുസഈദിൽ ''ഖുദ്രി''(റ) എന്റെ അടുത്തു കൂടി നടന്നുപോകവെ ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: ഭക്തി മാർഗ്ഗത്തിൽ സ്ഥാപിക്കപ്പെട്ട പള്ളിയെപ്പറ്റി എന്താണ് താങ്കളുടെ പിതാവ് പറഞ്ഞതെന്ന് താങ്കൾ കേട്ടിരുന്നുവോ? അദ്ദേഹം പറഞ്ഞു: എന്റെ പിതാവ് പറഞ്ഞു: നബി(സ)തന്റെ ഭാര്യ വീട്ടിലായിരിക്കെ നബി(സ)യോട് ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, രണ്ടു പള്ളികളിൽ (മസ്ജിദുൽ അഖ്സ, മസ്ജിദുന്നബവി) ഏതാണ് ഭക്തി മാർഗ്ഗത്തിൽ സ്ഥാപിക്കപ്പെട്ടത്? അപ്പോൾ നബി(സ) കൈയിൽ കുറേ ചരൽകല്ലുകൾ വാരി തറയിൽ ഇട്ടുകൊണ്ട് (മദീനയിലെ പള്ളിയെ സൂചിപ്പിച്ചു കൊണ്ട്) പറഞ്ഞു: "നിങ്ങളുടെ ഈ പള്ളിയാണ്." അബുസലമ പറഞ്ഞു: അപ്പോൾ ഞാൻ പറഞ്ഞു: താങ്കളുടെ പിതാവ് ഇങ്ങനെ പറഞ്ഞുവെന്ന് താങ്കൾ സാക്ഷ്യം വഹിക്കുന്നുവോ? (മു)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ', 'അബുസലമതുബ്നു അബ്ദുറഹിമാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 241, 241, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: امْتَرَى رَجُلٌ مِنْ بَنِي خُدْرَةَ وَرَجُلٌ مِنْ بَنِي عَمْرِو بْنِ عَوْفٍ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى، فَقَالَ الْخُدْرِيُّ: هُوَ مَسْجِدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ الْآخَرُ: هُوَ مَسْجِدُ قُبَاءٍ. فَأَتَيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ، فَقَالَ: "هُوَ هَذَا – يَعْنِي مَسْجِدَهُ – وَفِي ذَلِكَ خَيْرٌ كَثِيرٌ". حَسَنٌ صَحِيحٌ. (ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഭക്തിമാർഗ്ഗത്തിൽ സ്ഥാപിക്കപ്പെട്ട പള്ളി ഏതാണ് എന്നതിനെപ്പറ്റി ഖുദ്രി ഗോത്രത്തിലെ ഒരാളും ബനൂ അംറുബ്നു ഔഫിലെ മറ്റൊരാളും തമ്മിൽ തർക്കമായി. ഖുദ്രി ഗോത്രക്കാരൻ പറഞ്ഞു: അത് റസൂലിന്റെ പള്ളിയാണ്, മറ്റേയാൾ പറഞ്ഞു: അതു ഖുബാഇലെ പള്ളിയാണ്. ഈ വിഷയത്തിൽ അവർ രണ്ടു പേരും നബി(സ)യെ സമീപിച്ചു ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഈ പള്ളിയാണ്. (നബിയുടെ പള്ളിയാണ് ഉദ്ദേശിച്ചത്.) ഇതിൽ ധാരാളം പുണ്യമുണ്ട്." (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 242, 242, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: تَمَارَى رَجُلَانِ فِي الْمَسْجِدِ الَّذِي أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ، فَقَالَ رَجُلٌ: هُوَ مَسْجِدُ قُبَاءٍ، وَقَالَ الْآخَرُ: هُوَ مَسْجِدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُوَ مَسْجِدِي هَذَا". (ت,ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ആദ്യ ദിവസത്തിലെ തഖ്വയുടെ മാർഗ്ഗത്തിൽ സ്ഥാപിതമായ പള്ളിയുടെ കാര്യത്തിൽ രണ്ടുപേർ തമ്മിൽ തർക്കിച്ചു. ഒരാൾ പറഞ്ഞു: അതു ഖുബാഇലെ പള്ളിയാണ്. മറ്റേയാൾ പറഞ്ഞു: അത് മസ്ജിദുന്നബവിയാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് എന്റെ പള്ളിയാണ്." (തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 242, 242, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ فَنَزَلَ أَعْلَى الْمَدِينَةِ فِي حَيٍّ يُقَالُ لَهُمْ بَنُو عَمْرِو بْنِ عَوْفٍ فَأَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِمْ أَرْبَعَ عَشْرَةَ لَيْلَةً ثُمَّ أَرْسَلَ إِلَى بَنِي النَّجَّارِ، فَجَاءُوا مُتَقَلِّدِي السُّيُوفِ كَأَنِّي أَنْظُرُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَاحِلَتِهِ وَأَبُو بَكْرٍ رِدْفُهُ وَمَلَأُ بَنِي النَّجَّارِ حَوْلَهُ، حَتَّى أَلْقَى بِفِنَاءِ أَبِي أَيُّوبَ، وَكَانَ يُحِبُّ أَنْ يُصَلِّيَ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ وَيُصَلِّي فِي مَرَابِضِ الْغَنَمِ، وَأَنَّهُ أَمَرَ بِبِنَاءِ الْمَسْجِدِ، فَأَرْسَلَ إِلَى مَلَإٍ مِنْ بَنِي النَّجَّارِ، فَقَالَ: "يَا بَنِي النَّجَّارِ: ثَامِنُونِي بِحَائِطِكُمْ هَذَا"، قَالُوا: لَا وَاللَّهِ لَا نَطْلُبُ ثَمَنَهُ إِلَّا إِلَى اللَّهِ، فَقَالَ أَنَسٌ: فَكَانَ فِيهِ مَا أَقُولُ لَكُمْ: قُبُورُ الْمُشْرِكِينَ وَفِيهِ خَرِبٌ وَفِيهِ نَخْلٌ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقُبُورِ الْمُشْرِكِينَ فَنُبِشَتْ، ثُمَّ بِالْخَرِبِ فَسُوِّيَتْ وَبِالنَّخْلِ فَقُطِعَ فَصَفُّوا النَّخْلَ قِبْلَةَ الْمَسْجِدِ، وَجَعَلُوا عِضَادَتَيْهِ الْحِجَارَةَ وَجَعَلُوا يَنْقُلُونَ الصَّخْرَ وَهُمْ يَرْتَجِزُونَ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَهُمْ وَهُوَ يَقُولُ: اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرُ الْآخِرَهْ فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَهْ. (ق)', 'അനസ്(റ): നബി(സ) മദീനയിലെത്തിയപ്പോൾ മദീനയിലെ ഉയർന്ന ഭാഗത്ത് താമസിച്ചിരുന്ന ബനൂ അംറുബ്നുഔഫ് എന്ന് പറയപ്പെട്ടിരുന്ന ഒരു ഗോത്രത്തിൽ ഇറങ്ങി. അവർക്കിടയിൽ പതിനാല് ദിവസം താമസിച്ചു. പിന്നീട് തിരുമേനി(സ) ബനൂനജ്ജാർ ഗോത്രത്തിലേക്ക് ആളെയയച്ചപ്പോൾ വാൾ ധരിച്ചവരായി (ആയുധ ധാരികളായി) അവർ എത്തി. നബി(സ), തന്റെ വാഹനത്തിൽ ഇരിക്കുന്നതായും നബി(സ)യുടെ തൊട്ടുപിന്നിൽ അബൂബക്കറും(റ) തിരുമേനിയുടെ ചുറ്റിലുമായി ബനൂനജ്ജാറിലെ ഒരു സംഘം നിലയുറപ്പിച്ചിരുന്നതായും ഞാൻ (എന്റെ കൺമുമ്പിൽ ഇപ്പോഴും) കാണുന്നതായി അനുഭവപ്പെടുന്നു. അങ്ങനെ നബി(സ) തന്റെ വാഹനം അബൂഅയ്യൂബിന്റെ മുറ്റത്ത് നിർത്തി. നിസ്ക്കാര സമയമാകുന്നത് എവിടെവെച്ചായാലും അവിടെ വെച്ച് നിസ്കരിക്കാനാണ് നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നത്. ആടുകൾ വിളയുന്നടങ്ങളിലും നബി(സ) നിസ്കരിക്കുമായിരുന്നു. പിന്നീട് പള്ളി നിർമ്മിക്കാൻ കൽപിച്ചു. തുടർന്ന് ബനൂനജ്ജാറിലെ നേതാക്കളെ വിളിച്ചു വരുത്തി പറഞ്ഞു: "അല്ലയോ ബനൂനജ്ജാറുകാരേ!, നിങ്ങളുടെ ഈ സ്ഥലത്തിന് വില പറയുക." അവർ പറഞ്ഞു: അല്ലാഹുവാണെ, ഞങ്ങൾ വില പറയുന്നില്ല. അല്ലാഹുവിൽ നിന്നല്ലാതെ ഞങ്ങൾ വില ആഗ്രഹിക്കുന്നില്ല. അനസ്(റ) പറഞ്ഞു: ഞാൻ ഈ പറയുന്നതൊക്കെ, അതായത്, മുശ്രിക്കുകളുടെ ഖബ്റുകളും, വീടുകളുടെ ഇടിഞ്ഞു പൊളിഞ്ഞ അവശിഷ്ടങ്ങളും, ഈത്തപ്പനകളും അതിലു(ആ പ്രദേശത്തു)ണ്ടായിരുന്നു. മുശ്രിക്കുകളുടെ ഖബർ കിളച്ചു മാറ്റാനും, അവശിഷ്ടങ്ങൾ നീക്കാനും ഈത്തപ്പന മുറിച്ചുമാറ്റി നിലം നിരപ്പാക്കാനും നബി(സ) കൽപിച്ചു.പള്ളിയുടെ ഖിബ്ലയായി ഈത്തപ്പന അണിയായി നിരത്തിവെച്ചു. വാതിലിന്റെ രണ്ടുവശം കല്ലുകളുമാക്കി. അവർ പാട്ടുപാടിക്കൊണ്ട് വലിയ പാറകൾ നീക്കിക്കൊണ്ടിരുന്നു. നബി(സ)യും പാട്ടുപാടി അവർക്കൊപ്പമുണ്ടായിരുന്നു; "അല്ലാഹുവേ! പരലോകത്തിലെ നന്മയല്ലാതെ മറ്റൊരു നന്മയുമില്ല തന്നെ. അതിനാൽ നീ അൻസാരികൾക്കും, മുഹാജിറുകൾക്കും പാപം പൊറുത്തു തരേണമേ." (ബു,മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 242, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أُمِرْتُ بِتَشْيِيدِ الْمَسَاجِدِ". قَالَ ابْنُ عَبَّاسٍ: لَتُزَخْرِفُنَّهَا كَمَا زَخْرَفَتِ الْيَهُودُ وَالنَّصَارَى. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "പള്ളികൾ (ആവശ്യത്തിലധികം) പടുത്തുയർത്താൻ ഞാൻ കൽപിക്കപ്പെട്ടിട്ടില്ല." ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ജൂതന്മാരും ക്രിസ്ത്യാനികളും മോടിപിടിപ്പിച്ച് അലങ്കരിക്കുന്നതു പോലെ നിങ്ങളും മോടി പിടിപ്പിക്കും. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى يَتَبَاهَى النَّاسُ فِي الْمَسَاجِدِ". (د)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ പള്ളികളുടെ കാര്യത്തിൽ പെരുമ കാണിക്കുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرَاكُمْ سَتُشَرِّفُونَ مَسَاجِدَكُمْ بَعْدِي كَمَا شَرَّفَتِ الْيَهُودُ كَنَائِسَهَا، وَكَمَا شَرَّفَتِ النَّصَارَى بِيَعَهَا. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജൂതന്മാരും ക്രിസ്ത്യാനികളും അവരുടെ ആരാധനാലയങ്ങളെ മോടിയാക്കിയതുപോലെ എനിക്കുശേഷം നിങ്ങൾ പള്ളികളെ (ആവശ്യത്തിലധികം) മോടിയാക്കുന്നതായി ഞാൻ കാണുന്നു." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا سَاءَ عَمَلُ قَوْمٍ قَطُّ إِلَّا زَخْرَفُوا مَسَاجِدَهُمْ". [ز:في إسناده كذاب، ومدلس عنعنه] (جه)', 'ഉമർ(റ): അല്ലാഹുവിന്റെ ദൂതൻ പറഞ്ഞു: "ഒരു ജനതയുടെ പ്രവർത്തനങ്ങൾ തീരെ വഷളാവുകയില്ല. അവർ അവരുടെ പള്ളികളെ അലങ്കരിച്ചിട്ടല്ലാതെ." (ഇതിന്റെ പരമ്പരയിൽ കളവ് പറയുന്നവനും ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുമുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:في إسناده كذاب، ومدلس عنعنه', null, 243, 243, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ الْمَسْجِدَ كَانَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَبْنِيًّا بِاللَّبِنِ وَالْجَرِيدِ، وَعُمُدُهُ مِنْ خَشَبِ النَّخْلِ، فَلَمْ يَزِدْ فِيهِ أَبُو بَكْرٍ شَيْئًا. وَزَادَ فِيهِ عُمَرُ وَبَنَاهُ عَلَى بِنَائِهِ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّبِنِ وَالْجَرِيدِ، وَأَعَادَ عُمُدَهُ خَشَبًا، وَغَيَّرَهُ عُثْمَانُ فَزَادَ فِيهِ زِيَادَةً كَثِيرَةً، وَبَنَى جِدَارَهُ بِالْحِجَارَةِ الْمَنْقُوشَةِ وَالْقَصَّةِ، وَجَعَلَ عُمُدَهُ مِنْ حِجَارَةٍ مَنْقُوشَةٍ وَسَقَّفَهُ بِالسَّاجِ. (خ,د)', 'അബുദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ)യുടെ കാലത്ത് പള്ളി ചുടുകട്ടയും ഈത്തപ്പനയോലയും കൊണ്ടായിരുന്നു നിർമ്മിച്ചിരുന്നത്. അതിന്റെ തൂണുകൾ ഈത്തപ്പനത്തടി കൊണ്ടായിരുന്നു. അബൂബക്കർ(റ) അതിൽ ഒരു വർദ്ധനവും (മാറ്റം) വരുത്തിയില്ല. നബി(സ)യുടെ കാലത്തു നിർമ്മിച്ചിരുന്ന ചുടുകട്ടയും, ഈത്തപ്പനത്തടിയും കൊണ്ടുള്ള പള്ളിയുടെ കെട്ടിടം ഉമർ(റ) തന്റെ ഭരണ കാലത്ത് അല്പം വലുതാക്കി. അതിന്റെ തൂണുകൾ മരത്തടികൾ ഉപയോഗിച്ച് പുനർ നിർമ്മിച്ചു. ഉസ്മാൻ(റ) അതിൽ വലിയ വ്യത്യാസം വരുത്തി. കൊത്തിയ കല്ലും കുമ്മായവും ഉപയോഗിച്ച് പള്ളിയുടെ ചുമരുകൾ നിർമ്മിച്ചു. കൊത്തിയെടുത്ത കല്ലുകൾ കൊണ്ട് തൂണുകൾ നിർമ്മിച്ചു. മേൽക്കൂര തേക്കു കൊണ്ടും നിർമ്മിച്ചു. (ബു,ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബുദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 244, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ مَسْجِدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ سَوَارِيهِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ جُذُوعِ النَّخْلِ، أَعْلَاهُ مُظَلَّلٌ بِجَرِيدِ النَّخْلِ، ثُمَّ إِنَّهَا نَخِرَتْ فِي خِلَافَةِ أَبِي بَكْرٍ فَبَنَاهَا بِجُذُوعِ النَّخْلِ، وَبِجَرِيدِ النَّخْلِ ثُمَّ إِنَّهَا نَخِرَتْ فِي خِلَافَةِ عُثْمَانَ فَبَنَاهَا بِالْآجُرِّ، فَلَمْ تَزَلْ ثَابِتَةً حَتَّى الْآنَ. (د)', 'ഇബ്നുഉമർ(റ): മസ്ജിദുന്നബവിയുടെ ചുമരുകൾ തിരുമേനിയുടെ കാലത്ത് ഈത്തപ്പനമരം കൊണ്ടുണ്ടാക്കിയതായിരുന്നു. അതിന്റെ മുകൾഭാഗം ഈത്തപ്പനയോല കൊണ്ട് മേഞ്ഞതായിരുന്നു. അബൂബക്കറി(റ)ന്റെ ഭരണ കാലത്ത് അവ ദ്രവിച്ചു പോയപ്പോൾ അദ്ദേഹം അത് ഈത്തപ്പന മരവും ഓലയും ഉപയോഗിച്ച് നിർമ്മിച്ചു. ഉസ്മാനി(റ)ന്റെ ഭരണ കാലത്ത് ദ്രവിച്ചപ്പോൾ അദ്ദേഹം അത് ചുടുകട്ട ഉപയോഗിച്ച് നിർമ്മിച്ചു. ഇപ്പോഴും അത് അങ്ങനെത്തന്നെ നിലനിൽക്കുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 244, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ مَوْضِعُ الْمَسْجِدِ حَائِطًا لِبَنِي النَّجَّارِ، فِيهِ حَرْثٌ وَنَخْلٌ وَقُبُورُ الْمُشْرِكِينَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَامِنُونِي بِهِ". فَقَالُوا: لَا نَبْتَغِي بِهِ ثَمَنًا إِلَّا عِنْدَ اللَّهِ، قَالَ: فَقَطَعَ النَّخْلَ، وَسَوَّى الْحَرْثَ، وَنَبَشَ قُبُورَ الْمُشْرِكِينَ. قَالَ: "فَاغْفِرْ". مَكَانَ "فَانْصُرْ". (د)', 'അനസുബ്നു മാലിക്(റ): പള്ളി നിൽക്കുന്ന സ്ഥലം ബനൂ നജ്ജാറിന്റെ ഉടമസ്ഥയിലുള്ള പുരയിടമായിരുന്നു. അതിൽ കൃഷിയും, ഈത്തപ്പനയും, മുശ്രിക്കുകളുടെ ഖബറിടങ്ങളുമുണ്ടായിരുന്നു. അവരോട് നബി(സ) പറഞ്ഞു: "അല്ലയോ ബനൂനജ്ജാറേ, നിങ്ങളുടെ ഈ സ്ഥലത്തിന് വില പറയൂ." അവർ പറഞ്ഞു: ഞങ്ങൾ അതിന് അല്ലാഹുവിൽ നിന്നല്ലാതെ വില ആഗ്രഹിക്കുന്നില്ല. തുടർന്ന് ഈത്തപ്പന മുറിച്ചുമാറ്റുകയും, മുശ്രിക്കുകളുടെ ഖബർ കിളച്ചു മാറ്റുകയും, നിലം നിരപ്പാക്കുകയും ചെയ്തു. ഹദീസ് തുടർന്നു പറഞ്ഞ അദ്ദേഹം: "നീ സഹായിക്കുക" എന്ന പദത്തിനു പകരം; "നീ പൊറുക്കുക" എന്ന പദമാണ് ഉപയോഗിച്ചത്. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 244, 244, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ مَوْضِعُ مَسْجِدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِبَنِي النَّجَّارِ، وَكَانَ فِيهِ نَخْلٌ وَمَقَابِرُ لِلْمُشْرِكِينَ، فَقَالَ لَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ثَامِنُونِي بِهِ". قَالُوا: لَا نَأْخُذُ لَهُ ثَمَنًا أَبَدًا، قَالَ: فَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبْنِيهِ وَهُمْ يُنَاوِلُونَهُ، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَلَا إِنَّ الْعَيْشَ عَيْشُ الْآخِرَهْ، فَاغْفِرْ لِلْأَنْصَارِ وَالْمُهَاجِرَهْ". قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ أَنْ يَبْنِيَ الْمَسْجِدَ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ. (ق,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ പള്ളി നിൽക്കുന്ന സ്ഥലം ബനൂനജ്ജാറിന്റേതായിരുന്നു. അതിൽ കൃഷിയും, ഈത്തപ്പനയും, മുശ്രിക്കുകളുടെ ഖബറിടങ്ങളുമുണ്ടായിരുന്നു. നബി(സ) അവരോട് പറഞ്ഞു: "നിങ്ങളുടെ ഈ സ്ഥലത്തിന് വില പറയൂ". അവർ പറഞ്ഞു: ഞങ്ങൾ ഒരിക്കലും അതിന്റെ വില വാങ്ങുകയില്ല. അദ്ദേഹം പറഞ്ഞു: അങ്ങനെ അവർ(സഹാബികൾ) അത് (ചുടുകട്ടകൾ) തിരുമേനിയുടെ അടുക്കലേക്ക് കൊണ്ടുവരികയും നബി(സ) (പള്ളി) പടുത്തുയർത്തുകയും ചെയ്തു. നബി(സ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: "അറിയുക, യഥാർത്ഥ ജീവിതം പരലോക ജീവിതം തന്നെയാണ്. അതിനാൽ അല്ലാഹുവേ! അൻസ്വാരികൾക്കും, മുഹാജിറുകൾക്കും നീ പൊറുത്തു കൊടുക്കേണമേ!" അനസ്(റ) പറഞ്ഞു: പള്ളി പണിയുന്നതിനു മുൻപ് നിസ്കാര സമയമാകുമ്പോൾ നബി(സ) എവിടെയായാലും അവിടെ നിസ്കരിക്കുമായിരുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 244, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يَجْعَلَ مَسْجِدَ الطَّائِفِ حَيْثُ كَانَ طَاغِيَتُهُمْ. (د,جه)', 'ഉസ്മാനുബിനു അബിൽ ആസ്(റ): അവരുടെ (അവിശ്വാസികളുടെ) ആരാധനാ മൂർത്തികൾ ഉണ്ടായിരുന്ന സ്ഥലത്തുതന്നെ ത്വാഇഫിലെ പള്ളി നിർമ്മിക്കണമെന്ന് നബി(സ) അദ്ദേഹത്തോട് (ഉസ്മാനുബ്നു അബിൽ ആസിനോട്) കൽപിച്ചു. (ദ,ജ)', 'عُثْمَانَ بْنِ أَبِي الْعَاصِ', 'ഉസ്മാനുബിനു അബിൽ ആസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 245, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ، وَسُئِلَ عَنِ الْحِيطَانِ تُلْقَى فِيهَا الْعَذِرَاتُ؟ فَقَالَ: "إِذَا سُقِيَتْ مِرَارًا فَصَلُّوا فِيهَا". يَرْفَعُهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. [ز: فيه مدلس عنعنه] (جه)', 'ഇബ്നുഉമർ(റ): അഴുക്ക് (മലം) നിക്ഷേപിക്കുന്ന കോമ്പൗണ്ടി(സ്ഥല)നെപ്പറ്റി അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവിടെ പലപ്രാവശ്യമായി ധാരാളം വെള്ളമൊഴിച്ചാൽ നിങ്ങൾക്കവിടെ വെച്ചു നിസ്കരിക്കാം. ഈ ഹദീസ് നബി(സ)യിലേക്ക് ബന്ധപ്പെടുത്തിയാണ് പറഞ്ഞത്. ഇതിന്റെ പരമ്പരയിൽ ഇതിനെ അൻഅനയാക്കി ഉദ്ധരിച്ച മുദല്ലിസുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فيه مدلس عنعنه', null, 245, 245, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عِتْبَانَ بْنَ مَالِكٍ وَهُوَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّنْ شَهِدَ بَدْرًا مِنَ الْأَنْصَارِ أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، قَدْ أَنْكَرْتُ بَصَرِي وَأَنَا أُصَلِّي لِقَوْمِي، فَإِذَا كَانَتِ الْأَمْطَارُ سَالَ الْوَادِي الَّذِي بَيْنِي وَبَيْنَهُمْ لَمْ أَسْتَطِعْ أَنْ آتِيَ مَسْجِدَهُمْ فَأُصَلِّيَ بِهِمْ، وَوَدِدْتُ يَا رَسُولَ اللَّهِ أَنَّكَ تَأْتِينِي فَتُصَلِّيَ فِي بَيْتِي، فَأَتَّخِذَهُ مُصَلًّى، قَالَ: فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَأَفْعَلُ إِنْ شَاءَ اللَّهُ". قَالَ عِتْبَانُ: فَغَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ حِينَ ارْتَفَعَ النَّهَارُ، فَاسْتَأْذَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَذِنْتُ لَهُ، فَلَمْ يَجْلِسْ حَتَّى دَخَلَ الْبَيْتَ، ثُمَّ قَالَ: "أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ". قَالَ: فَأَشَرْتُ لَهُ إِلَى نَاحِيَةٍ مِنَ الْبَيْتِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَبَّرَ فَقُمْنَا فَصَفَّنَا فَصَلَّى رَكْعَتَيْنِ، ثُمَّ سَلَّمَ، قَالَ: وَحَبَسْنَاهُ عَلَى خَزِيرَةٍ صَنَعْنَاهَا لَهُ، قَالَ: فَآبَ فِي الْبَيْتِ رِجَالٌ مِنْ أَهْلِ الدَّارِ ذَوُو عَدَدٍ فَاجْتَمَعُوا فَقَالَ قَائِلٌ مِنْهُمْ: أَيْنَ مَالِكُ بْنُ الدُّخَيْشِنِ أَوِ ابْنُ الدُّخْشُنِ؟ فَقَالَ بَعْضُهُمْ: ذَلِكَ مُنَافِقٌ لَا يُحِبُّ اللَّهَ وَرَسُولَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقُلْ ذَلِكَ، أَلَا تَرَاهُ قَدْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ يُرِيدُ بِذَلِكَ وَجْهَ اللَّهِ". قَالَ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَإِنَّا نَرَى وَجْهَهُ وَنَصِيحَتَهُ إِلَى الْمُنَافِقِينَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنَّ اللَّهَ قَدْ حَرَّمَ عَلَى النَّارِ مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ". (خ)', 'മഹ്മൂദുബ്നു റബിഉൽ അൻസാരി(റ): നബി(സ)യുടെ അനുചരനും, അൻസ്വാരികളിൽ നിന്ന് ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്തയാളുമായ ഇത്ബാനുബ്നു മാലിക്(റ) നബി(സ)യുടെ അടുക്കൽ വന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ കണ്ണിന്റെ കാഴ്ച നഷ്ടപ്പെട്ടു, ഞാൻ എന്റെ ആളുകൾക്ക് ഇമാമായി നിസ്കരിക്കാറുണ്ട്. മഴ പെയ്താൽ എനിക്കും അവർക്കുമിടയിലുള്ള താഴ്വരയിലൂടെ വെള്ളം നിറഞ്ഞു കവിഞ്ഞ് ഒഴുകുന്നതിനാൽ അവർക്ക് ഇമാമായി നിസ്കരിക്കാൻ എനിക്ക് അവരുടെ പള്ളിയിൽ പോകാൻ കഴിയുന്നില്ല. അതിനാൽ അവിടുന്ന് എന്റെ വീട്ടിൽ വന്ന് നിസ്കരിച്ചാൽ എനിക്ക് ആ സ്ഥലം മുസ്വല്ലയാക്കാൻ കഴിയുമല്ലോ എന്ന് അതിയായ ആഗ്രഹമുണ്ട്. (അദ്ദേഹം തുടർന്നു) നബി(സ) പ്രതിവചിച്ചു: "ഇൻശാ അല്ലാഹ്, അങ്ങനെ ചെയ്യാം." ഇത്ബാൻ പറഞ്ഞു: സൂര്യൻ ഉദിച്ചുയർന്നപ്പോൾ (പകൽ ഉയർന്നപ്പോൾ) നബി(സ)യും അബൂബക്കറും(റ) എന്റടുത്തെത്തി പ്രവേശനാനുമതി ചോദിക്കുകയും, ഞാൻ സമ്മതം നൽകുകയും ചെയ്തു. വീട്ടിൽ പ്രവേശിച്ച നബി ഇരിക്കാതെ തന്നെ ഇപ്രകാരം ചോദിച്ചു: "നിങ്ങളുടെ വീട്ടിൽ ഞാൻ എവിടെ നിസ്കരിക്കാനാണ് താങ്കൾ ഇഷ്ടപ്പെടുന്നത്?". വീട്ടിലെ ഒരുഭാഗത്തേക്ക് ഞാൻ തിരുമേനിക്ക് ചൂണ്ടിക്കാണിച്ചുകൊടുത്തു. നബി(സ) നിസ്കാരത്തിനായി നിന്ന് തക്ബീർ ചൊല്ലി, അവിടുന്ന് ഞങ്ങളെ വരിവരിയായി നിർത്തി. രണ്ടു റകഅത്ത് നിസ്കരിച്ച് സലാം വീട്ടി. ഇത്ബാൻ പറയന്നു: നബി(സ)ക്കുവേണ്ടി നിർമ്മിച്ച ഒരു ''ഖസീറ'' (ഒരു പ്രത്യേകതരം ഭക്ഷണം) കഴിക്കാൻ നബിയെ ഞങ്ങൾ തടഞ്ഞുനിർത്തി (അപേക്ഷിച്ചു). അപ്പോൾ വീട്ടിലുണ്ടായിരുന്ന കുറേ പുരുഷന്മാർ ഒന്നിച്ചുകൂടി. അവരിൽ ഒരാൾ ചോദിച്ചു: മാലികുബ്നു ദുഖൈശിൻ -അല്ലെങ്കിൽ ഇബ്നുദുഖ്ശൂൻ- എവിടെ? അവരിൽ ചിലർ പറഞ്ഞു: അവൻ കപട വിശ്വാസിയാണ്, അല്ലാഹുവിനേയും അവന്റെ റസൂലിനേയും അവൻ ഇഷ്ടപ്പെടുന്നില്ല. ഉടൻ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അങ്ങനെ പറയരുത്. അല്ലാഹുവിന്റെ തൃപ്തി മാത്രം കാംക്ഷിച്ചുകൊണ്ട് അയാൾ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്നു പറഞ്ഞത് നിങ്ങൾ കാണുന്നില്ലേ?" അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലും ആണ് കൂടുതൽ അറിയുന്നത്. അദ്ദേഹം തുടർന്നു: ഞങ്ങൾ അയാളുടെ മുഖവും കപട വിശ്വസികളോടുള്ള അയാളുടെ ഉപദേശവും കാണുന്നുണ്ട്. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ പ്രതിഫലം ആഗ്രഹിച്ചു കൊണ്ട് ആരാണോ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് പറയുന്നത് അവന് അല്ലാഹു നരകം ഹറാമാക്കിയിരിക്കുന്നു". (ബു)', 'مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ', 'മഹ്മൂദുബ്നു റബിഉൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 245, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبِنَاءِ الْمَسَاجِدِ فِي الدُّورِ، وَأَنْ تُنَظَّفَ وَتُطَيَّبَ. (د,ت,جه)', 'ആഇശ(റ): വീടുകളിൽ പള്ളികൾ നിർമ്മിക്കാനും, അവ വൃത്തിയാക്കി വെക്കാനും സുഗന്ധം പൂശാനും നബി(സ) കൽപിച്ചിരിക്കുന്നു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 246, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَتَبَ إِلَى ابْنِهِ: أَمَّا بَعْدُ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْمُرُنَا بِالْمَسَاجِدِ أَنْ نَصْنَعَهَا فِي دِيَارِنَا، وَنُصْلِحَ صَنْعَتَهَا وَنُطَهِّرَهَا. (د)', 'സമുറ(റ): അദ്ദേഹം തന്റെ മകന് എഴുതി: അല്ലാഹുവിന്റെ റസൂൽ(സ) നമ്മുടെ വീടുകളിൽ പള്ളികൾ ഉണ്ടാക്കാനും, അവ നല്ലനിലയിൽ നിർമ്മിക്കാനും, വൃത്തിയായി സൂക്ഷിക്കാനും നമ്മോട് കൽപിച്ചിരിക്കുന്നു. (ദ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 246, 246, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ، وَكَانَ قَدْ عَقَلَ مَجَّةً مَجَّهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ دَلْوٍ فِي بِئْرٍ لَهُمْ، عَنْ عِتْبَانَ بْنِ مَالِكٍ السَّالِمِيِّ – وَكَانَ إِمَامَ قَوْمِهِ بَنِي سَالِمٍ، وَكَانَ شَهِدَ بَدْرًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَ: جِئْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنِّي قَدْ أَنْكَرْتُ مِنْ بَصَرِي، وَإِنَّ السَّيْلَ يَأْتِي فَيَحُولُ بَيْنِي وَبَيْنَ مَسْجِدِ قَوْمِي، وَيَشُقُّ عَلَيَّ اجْتِيَازُهُ، فَإِنْ رَأَيْتَ أَنْ تَأْتِيَنِي فَتُصَلِّيَ فِي بَيْتِي مَكَانًا أَتَّخِذُهُ مُصَلًّى، فَافْعَلْ. قَالَ: "أَفْعَلُ" فَغَدَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ بَعْدَ مَا اشْتَدَّ النَّهَارُ، وَاسْتَأْذَنَ فَأَذِنْتُ لَهُ، وَلَمْ يَجْلِسْ حَتَّى قَالَ: "أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ لَكَ مِنْ بَيْتِكَ؟" فَأَشَرْتُ لَهُ إِلَى الْمَكَانِ الَّذِي أُحِبُّ أَنْ أُصَلِّيَ فِيهِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَصَفَفْنَا خَلْفَهُ، فَصَلَّى بِنَا رَكْعَتَيْنِ، ثُمَّ احْتَبَسْتُهُ عَلَى خَزِيرَةٍ تُصْنَعُ لَهُمْ. (ق,ن,جه)', 'മഹ്മൂദുബ്നു റബീഇൽ അൻസ്വാരി(റ): അവരുടെ കിണറ്റിൽ നിന്നു കോരിയ ഒരു ബക്കറ്റ് വെള്ളത്തിൽ നിന്നല്പം പ്രവാചകൻ(സ) വായിലാക്കി അദ്ദേഹത്തിനുമേൽ തെറിപ്പിച്ച ഒരനുഭവം ഓർക്കുന്നുണ്ട്. ഇത്ബാനുബ്നു മാലികിസ്സാലിമിൽ നിന്ന് നിവേദനം: അദ്ദേഹം തന്റെ ജനതയായ ''ബനൂസാലിമി''ന്റെ ഇമാമായിരുന്നു. അദ്ദേഹം റസൂലി(സ)നോടൊപ്പം ബദർ യൂദ്ധത്തിൽ പങ്കെടുത്തിട്ടുണ്ട്. ഞാൻ പ്രവാചക(സ)നെ സമീപിച്ചു പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ കണ്ണിന്റെ കാഴ്ച നഷ്ടപ്പെട്ടിരിക്കുന്നു. എന്റെയും എന്റെ ജനതയുടെ പള്ളിയുടെയും ഇടയിൽ വെള്ളപ്പൊക്കം തടസ്സമായിരിക്കുന്നു. അത് മുറിച്ച് കടന്ന് (പള്ളിയിൽ) പോകൽ എനിക്ക് പ്രയാസമാണ്. അങ്ങ് എന്റെ വീട്ടിൽ വന്ന് ഒരു സ്ഥലത്ത് നിസ്കരിച്ചാൽ അത് ഞാൻ മുസ്വല്ലയായി നിശ്ചയിച്ചു കൊള്ളാം. (വിരോധമില്ലെങ്കിൽ) അവിടുന്ന് അത് ചെയ്താലും, അപ്പോൾ പ്രവാചകൻ(സ) പറഞ്ഞു: "ശരി അങ്ങനെ ചെയ്യാം." പിറ്റേദിവസം പകൽ ചൂട് കഠിനമായ സമയം പ്രവാചക(സ)നും അബൂബക്കറും(റ) വീട്ടിലെത്തി പ്രവേശനാനുമതി തേടി. ഞാൻ അനുമതി നല്കി. ഇരിക്കും മുമ്പ് തന്നെ നബി(സ) ഇങ്ങനെ ചോദിച്ചു: "താങ്കളുടെ വീട്ടിൽ എവിടെ നിസ്കരിക്കാനാണ് താങ്കൾ ഇഷ്ടപ്പെടുന്നത്?". അപ്പോൾ നിസ്കരിക്കാൻ ഇഷ്ടപ്പെടുന്ന ഒരു സ്ഥലം ഞാൻ ചൂണ്ടിക്കാണിച്ചു. അപ്പോൾ പ്രവാചകൻ(സ) നിസ്കരിക്കാൻ ഒരുങ്ങി. പ്രവാചക(സ)ന്നു പിന്നിലായി ഞങ്ങൾ അണി നിരന്നു. ഞങ്ങളുമായി തിരുമേനി രണ്ടു റക്അത്ത് നിസ്കരിച്ചു. അവർക്കു വേണ്ടി ഉണ്ടാക്കിയിരുന്ന ''ഖസീറ'' (ആഹാര സാധനം) കഴിക്കാൻ ഞാൻ തിരുമേനിയെ നിർബന്ധിച്ചു. (ബു,മു,ന,ജ)', 'مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ', 'മഹ്മൂദുബ്നു റബീഇൽ അൻസ്വാരി(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 246, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْأَنْصَارِ أَرْسَلَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ: تَعَالَ فَخُطَّ لِي مَسْجِدًا فِي دَارِي أُصَلِّي فِيهِ. وَذَلِكَ بَعْدَ مَا عَمِيَ، فَجَاءَ فَفَعَلَ. (جه)', 'അബൂഹൂറൈറ(റ): അൻസാരികളിലൊരാൾ നബി(സ)യുടെ അടുത്തേക്ക് ഒരാളെ അയച്ചുകൊണ്ട് ഇപ്രകാരം അപേക്ഷിച്ചു: താങ്കൾ എന്റെ വീട്ടിൽ വന്ന് എനിക്ക് നിസ്കരിക്കാൻ ഒരു പള്ളി (മുസ്വല്ല) നിർണ്ണയിച്ചു തരിക. അയാൾക്ക് അന്ധത പിടിപെട്ട ശേഷമായിരുന്നു ഇത്. അങ്ങനെ നബി(സ) അയാളുടെ വീട്ടിലെത്തി അപ്രകാരം ചെയ്തു കൊടുത്തു. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹൂറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: صَنَعَ بَعْضُ عُمُومَتِي لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، فَقَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي أُحِبُّ أَنْ تَأْكُلَ فِي بَيْتِي وَتُصَلِّيَ فِيهِ. قَالَ: فَأَتَاهُ، وَفِي الْبَيْتِ فَحْلٌ مِنْ هَذِهِ الْفُحُولِ، فَأَمَرَ بِنَاحِيَةٍ مِنْهُ فَكُنِسَ وَرُشَّ، فَصَلَّى وَصَلَّيْنَا مَعَهُ. (جه)', 'അനസുബ്നുമാലിക്(റ): എന്റെ ഒരു പിതൃവ്യൻ നബി(സ)ക്കായി ഒരിക്കൽ ഭക്ഷണം തയ്യാറാക്കി വെച്ച് നബിയോട് പറഞ്ഞു: അവിടുന്ന് എന്റെ വീട്ടിൽ വന്ന് ആഹാരം കഴിക്കുകയും വീട്ടിൽ വെച്ച് നിസ്കരിക്കുകയും ചെയ്യുവാൻ ഞാൻ ഇഷ്ടപ്പെടുന്നു. പിതൃവ്യൻ പറഞ്ഞു: തിരുമേനി(സ) അവിടെ എത്തി. വീട്ടിൽ ഈത്തപ്പനയോല കൊണ്ട് നിർമ്മിച്ച പായ ഉണ്ടായിരുന്നു. നബി(സ) അതിലെ ഒരു ഭാഗം കാണിച്ചു കൊടുത്തു അവിടെ വെള്ളം തളിച്ച് അടിച്ചു (വൃത്തിയാക്കി). തുടർന്ന്, നബി(സ) നിസ്കരിച്ചു. അദ്ദേഹത്തോടൊപ്പം ഞങ്ങളും നിസ്കരിച്ചു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 247, 247, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْزِلُ بِذِي الْحُلَيْفَةِ حِينَ يَعْتَمِرُ وَفِي حَجَّتِهِ حِينَ حَجَّ تَحْتَ سَمُرَةٍ فِي مَوْضِعِ الْمَسْجِدِ الَّذِي بِذِي الْحُلَيْفَةِ، وَكَانَ إِذَا رَجَعَ مِنْ غَزْوٍ، كَانَ فِي تِلْكَ الطَّرِيقِ، أَوْ حَجٍّ أَوْ عُمْرَةٍ هَبَطَ مِنْ بَطْنِ وَادٍ فَإِذَا ظَهَرَ مِنْ بَطْنِ وَادٍ أَنَاخَ بِالْبَطْحَاءِ الَّتِي عَلَى شَفِيرِ الْوَادِي الشَّرْقِيَّةِ فَعَرَّسَ ثَمَّ حَتَّى يُصْبِحَ لَيْسَ عِنْدَ الْمَسْجِدِ الَّذِي بِحِجَارَةٍ وَلَا عَلَى الْأَكَمَةِ الَّتِي عَلَيْهَا الْمَسْجِدُ، كَانَ ثَمَّ خَلِيجٌ يُصَلِّي عَبْدُاللَّهِ عِنْدَهُ فِي بَطْنِهِ كُثُبٌ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَمَّ يُصَلِّي فَدَحَا السَّيْلُ فِيهِ بِالْبَطْحَاءِ حَتَّى دَفَنَ ذَلِكَ الْمَكَانَ الَّذِي كَانَ عَبْدُاللَّهِ يُصَلِّي فِيهِ. (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഉംറക്കും ഹജ്ജിനും വേണ്ടി പോകുമ്പോൾ ദുൽ ഹുലൈഫായിലെ പള്ളിക്കു സമീപത്തുള്ള ''സമുറത്തി''¹ന്റെ ചുവട്ടിൽ ഇറങ്ങിയിരുന്നു. അപ്രകാരം തന്നെ, യുദ്ധാനന്തരം തിരിച്ചുപോന്നു. അല്ലെങ്കിൽ ഹജ്ജോ ഉംറയോ കഴിഞ്ഞു മടങ്ങി ആ വഴിക്കുവന്നു. എങ്കിൽ ''അഖീഖ്'' താഴ്വരയുടെ താഴ്ഭാഗത്ത് നബി(സ) വന്നിറങ്ങി. താഴ്വരുയുടെ താഴ്ഭാഗത്തുനിന്ന് മേൽപ്പോട്ടു കയറുകയാണെങ്കിൽ, ആ താഴ്വരയുടെ കിഴക്കേ അറ്റത്തുള്ള വിശാലമായ ചരൽ പ്രദേശത്ത് ഒട്ടകത്തെ നിർത്തി വാഹനത്തിൽ നിന്നും ഇറങ്ങും. രാത്രിയുടെ അന്ത്യദശയിൽ പ്രഭാതം വരെ വിശ്രമിക്കും. കൽക്കൂട്ടത്തിന്മേൽ (ഇപ്പോൾ) സ്ഥിതിചെയ്യുന്ന പള്ളിക്കു സമീപത്തല്ല പ്രവാചകൻ(സ) ഇറങ്ങിയിരുന്നത്. (ഇപ്പോൾ) പള്ളി സ്ഥിതിചെയ്യുന്ന ആ കുന്നിൽമേലുമല്ല. അവിടെയുള്ള ചോലയ്ക്കു സമീപത്തു വെച്ച് ഇബ്നുഉമർ(റ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. ആ ചോലയ്ക്കു സമീപത്തുള്ള മണൽ കൂമ്പാരങ്ങളിൽ വെച്ച് പ്രവാചകൻ(സ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. മഴവെള്ളം കുത്തിയൊഴുകിയപ്പോൾ ഇബ്നുഉമർ(റ) നിസ്കരിച്ചിരുന്ന ആസ്ഥലത്തെ ചരൽക്കല്ലുകൾ മൂടിക്കളഞ്ഞു. (ബു)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', '¹. ഒരു മരത്തിന്റെ പേര്.', null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'حَدَّثَ عَبْدُ اللَّهِ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى حَيْثُ الْمَسْجِدُ الصَّغِيرُ الَّذِي دُونَ الْمَسْجِدِ الَّذِي بِشَرَفِ الرَّوْحَاءِ، وَقَدْ كَانَ عَبْدُاللَّهِ يَعْلَمُ الْمَكَانَ الَّذِي كَانَ صَلَّى فِيهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ثَمَّ عَنْ يَمِينِكَ حِينَ تَقُومُ فِي الْمَسْجِدِ تُصَلِّي وَذَلِكَ الْمَسْجِدُ عَلَى حَافَةِ الطَّرِيقِ الْيُمْنَى وَأَنْتَ ذَاهِبٌ إِلَى مَكَّةَ بَيْنَهُ وَبَيْنَ الْمَسْجِدِ الْأَكْبَرِ رَمْيَةٌ بِحَجَرٍ أَوْ نَحْوُ ذَلِكَ. (خ)', 'ഇബ്നുഉമർ(റ) പറയുന്നു: ''റൗഹാഅ്''ലെ കുന്നിന്മേൽ നിലകൊള്ളുന്ന പള്ളിക്കു സമീപത്തുള്ള ആ ചെറിയ പള്ളി നിൽക്കുന്ന സ്ഥലത്ത് പ്രവാചകൻ(സ) നിസ്കരിക്കാറുണ്ടായിരുന്നു.'' - പ്രവാചകൻ(സ) നിസ്കരിക്കാറുണ്ടായിരുന്ന സ്ഥലത്തെക്കുറിച്ച് ഇബ്നുഉമറിന് അറിയാമായിരുന്നു- അദ്ദേഹം പറയുന്നു: നീ പള്ളിയിൽ നിന്ന് നമസ്കരിക്കുമ്പോൾ ആ സ്ഥലം നിന്റെ വലതു വശത്തായിരിക്കും. നീ മക്കയിലേക്ക് പോകുമ്പോൾ ആ പള്ളി വഴിയുടെ വലത്തെ ഓരത്ത് നിലകൊള്ളുന്നതായി കാണാം. ഒരു കല്ലെടുത്തെറിഞ്ഞാൽ എത്താവുന്ന ദൂരം മാത്രമേ അതിനും വലിയ പള്ളിക്കും ഇടയിലുള്ളൂ. അല്ലെങ്കിൽ അതിനു സമാനമായ ദൂരം. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 248, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'وَكَانَ عَبْدُ اللَّهِ يُصَلِّي إِلَى الْعِرْقِ الَّذِي عِنْدَ مُنْصَرَفِ الرَّوْحَاءِ، وَذَلِكَ الْعِرْقُ انْتِهَاءُ طَرَفِهِ عَلَى حَافَةِ الطَّرِيقِ دُونَ الْمَسْجِدِ الَّذِي بَيْنَهُ وَبَيْنَ الْمُنْصَرَفِ وَأَنْتَ ذَاهِبٌ إِلَى مَكَّةَ وَقَدِ ابْتُنِيَ ثَمَّ مَسْجِدٌ فَلَمْ يَكُنْ عَبْدُاللَّهِ بْنُ عُمَرَ يُصَلِّي فِي ذَلِكَ الْمَسْجِدِ كَانَ يَتْرُكُهُ عَنْ يَسَارِهِ وَوَرَاءَهُ وَيُصَلِّي أَمَامَهُ إِلَى الْعِرْقِ نَفْسِهِ، وَكَانَ عَبْدُاللَّهِ يَرُوحُ مِنْ الرَّوْحَاءِ فَلَا يُصَلِّي الظُّهْرَ حَتَّى يَأْتِيَ ذَلِكَ الْمَكَانَ فَيُصَلِّيَ فِيهِ الظُّهْرَ، وَإِذَا أَقْبَلَ مِنْ مَكَّةَ فَإِنْ مَرَّ بِهِ قَبْلَ الصُّبْحِ بِسَاعَةٍ أَوْ مِنْ آخِرِ السَّحَرِ عَرَّسَ حَتَّى يُصَلِّيَ بِهَا الصُّبْحَ. (خ)', 'ഇബ്നുഉമർ(റ) ''റൗഹാഇ''ന്റെ അതിർത്തിയിലുള്ള കുന്നിന്റെ നേരെ തിരിഞ്ഞു നിസ്കരിക്കാറുണ്ടായിരുന്നു. ആ കുന്ന് ചെന്നവസാനിക്കുന്നത് ഒരു വഴിവക്കിലാണ്. ''റൗഹാഇ''ന്റെ അതിർത്തിക്കും ആ കുന്നിനുമിടക്ക് നിലകൊള്ളുന്ന പള്ളിക്കരികിലൂടെയുള്ള വഴിയുടെ ഓരത്താണ് ആ കുന്ന് ചെന്നവസാനിക്കുന്നത്. നീ മക്കയിലേക്കു പോകുമ്പോഴാണ് അത്തരത്തിൽ അത് കിടക്കുന്നതായി കാണുക. അവിടെ ഒരു പള്ളി പണിതുയർത്തിയിട്ടുണ്ട്. എന്നാൽ ഇബ്നുഉമർ ആ പള്ളിയിൽ വെച്ച് നിസ്കരിക്കാറുണ്ടായിരുന്നില്ല. ആ പള്ളിയെ ഇടത്തും പിന്നിലുമാക്കിയിട്ട് അതിന്റെ മുമ്പിൽ നിന്നിട്ട് ആ കുന്നിന്റെ നേരെ തിരിഞ്ഞു നിന്നു കൊണ്ടാണദ്ദേഹം നിസ്കരിക്കുക. ഇബ്നുഉമർ(റ) ''റൗഹാഇ''ൽ നിന്നും രാവിലെ പോകുകയാണെങ്കിൽ ആ സ്ഥലത്തെത്തുന്നത് വരെ ദുഹ്ർ നിസ്കരിക്കാറില്ല. എത്തിയാൽ അവിടെ വെച്ച് ദുഹ്ർ നിസ്കരിക്കും. മക്കയിൽ നിന്നും വരുമ്പോൾ പ്രഭാതത്തിന് ഒരു നാഴിക മുമ്പോ അല്ലെങ്കിൽ രാവിന്റെ അന്ത്യഘട്ടത്തിലോ ആണ് ആ വഴിക്കു പോകുന്നതെങ്കിൽ അവിടെ അദ്ദേഹം ഇറങ്ങി വിശ്രമിക്കും. എന്നിട്ട് അവിടെ വെച്ച് സുബ്ഹ് നിസ്കരിക്കും. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 248, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'حَدَّثَ عَبْدُ اللَّهِ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَنْزِلُ تَحْتَ سَرْحَةٍ ضَخْمَةٍ دُونَ الرُّوَيْثَةِ عَنْ يَمِينِ الطَّرِيقِ وَوِجَاهَ الطَّرِيقِ فِي مَكَانٍ بَطْحٍ سَهْلٍ حَتَّى يُفْضِيَ مِنْ أَكَمَةٍ دُوَيْنَ بَرِيدِ الرُّوَيْثَةِ بِمِيلَيْنِ وَقَدِ انْكَسَرَ أَعْلَاهَا فَانْثَنَى فِي جَوْفِهَا وَهِيَ قَائِمَةٌ عَلَى سَاقٍ وَفِي سَاقِهَا كُثُبٌ كَثِيرَةٌ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറഞ്ഞു: നബി(സ) ഒരു വലിയ മരത്തിന്റെ ചുവട്ടിൽ ഇറങ്ങാറുണ്ടായിരുന്നു. ''റുവൈനത്തി''ന്റെ അടുത്താണ് ആ സ്ഥലം വഴിയുടെ വലത്തെ ഭാഗത്തും മുൻപിലുമായി വിശാലമായിക്കിടക്കുന്ന ഒരു മൺ പ്രദേശമാണത്. ''റുവൈനത്തി''ന്റെ രണ്ടു മൈൽ അടുത്തുള്ള കുന്ന് നബി(സ) കടന്നു പോകുന്നതിന് മുമ്പിലുള്ള സ്ഥലമാണത്. ആമരത്തിന്റെ തല പൊട്ടിയിട്ട് ഉള്ളിലേക്കു ചുമുണ്ട് നിൽക്കുകയാണ്. തായ്ത്തടിയിന്മേൽ മാത്രമാണ് ആ മരം നിലകൊള്ളുക. അതിന്റെ താഴ്ഭാഗത്താകട്ടെ അനവധി മണൽക്കൂനകളുണ്ട്. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'حَدَّثَ عَبْدُ اللَّهِ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي طَرَفِ تَلْعَةٍ مِنْ وَرَاءِ الْعَرْجِ وَأَنْتَ ذَاهِبٌ إِلَى هَضْبَةٍ عِنْدَ ذَلِكَ الْمَسْجِدِ قَبْرَانِ أَوْ ثَلَاثَةٌ عَلَى الْقُبُورِ رَضَمٌ مِنْ حِجَارَةٍ عَنْ يَمِينِ الطَّرِيقِ عِنْدَ سَلَمَاتِ الطَّرِيقِ بَيْنَ أُولَئِكَ السَّلَمَاتِ كَانَ عَبْدُاللَّهِ يَرُوحُ مِنَ الْعَرْجِ بَعْدَ أَنْ تَمِيلَ الشَّمْسُ بِالْهَاجِرَةِ فَيُصَلِّي الظُّهْرَ فِي ذَلِكَ الْمَسْجِدِ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറഞ്ഞു: നബി(സ) കുന്നിന്റെ ഓരത്തു നിന്നുകൊണ്ട് നിസ്കരിച്ചിട്ടുണ്ട്. നീ ഹള്ബായിലേക്കു പോകുമ്പോൾ അതു ''അർജി''ന്റെ അപ്പുറത്തായിരിക്കുമുണ്ടാവുക. പള്ളിക്കു സമീപത്ത് രണ്ടോ മൂന്നോ ഖസ്റുകളുണ്ട്. അവയിന്മേൽ വലിയ കല്ലുകൾ വെച്ചിട്ടുമുണ്ട്. അവ വഴിയുടെ വലതു വശത്തുള്ള വഴിയിലെ കല്ലുകൾക്കടുത്താണ്. ആ കല്ലുകൾക്കിടയിലൂടെ ഉച്ചസമയത്ത് സൂര്യൻ ആകാശമദ്ധ്യത്തിൽ നിന്നും നീങ്ങിയശേഷം ഇബ്നുഉമർ പോകും. എന്നിട്ട് ദുഹ്ർ ആ വള്ളിയിൽ വെച്ചു നിസ്കരിക്കും. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 249, 249, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'قَالَ عَبْدُ اللَّهِ: وَنَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ سَرَحَاتٍ عَنْ يَسَارِ الطَّرِيقِ فِي مَسِيلٍ دُونَ هَرْشَى ذَلِكَ الْمَسِيلُ لَاصِقٌ بِكُرَاعِ هَرْشَى بَيْنَهُ وَبَيْنَ الطَّرِيقِ قَرِيبٌ مِنْ غَلْوَةٍ، وَكَانَ عَبْدُاللَّهِ يُصَلِّي إِلَى سَرْحَةٍ هِيَ أَقْرَبُ السَّرَحَاتِ إِلَى الطَّرِيقِ وَهِيَ أَطْوَلُهُنَّ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറഞ്ഞു: റസൂൽ(സ) ''ഹർശ''ക്കടുത്തുള്ള വെള്ളച്ചാലിൽ വഴിയുടെ ഇടതു ഭാഗത്തുള്ള വൃക്ഷങ്ങൾക്കു സമീപത്തായി ഇറങ്ങാറുണ്ടായിരുന്നു. ആ വെള്ളച്ചാൽ ''ഹർശ''യുടെ ഓരത്തോട് ചോർന്നാണുള്ളത്. ഏതാണ്ട് ഒരമ്പയ്താൽ ഏത്തുന്ന ദൂരമേ വെള്ളച്ചാലിനും വഴിക്കുമിടയിലുള്ളൂ. അതു പോലെത്തന്നെ വഴിയിലേക്കു കൂടുതൽ അടുത്തു നിൽക്കുന്ന ഒരു മരത്തിലേക്കു തിരിഞ്ഞുകൊണ്ട് ഇബ്നുഉമർ(റ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. അവിടെയുള്ള ഏറ്റവും നീളമുള്ള മരം അതായിരുന്നു.', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], '{}'::text[], null, null, 249, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'وَيَقُولُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْزِلُ فِي الْمَسِيلِ الَّذِي فِي أَدْنَى مَرِّ الظَّهْرَانِ قِبَلَ الْمَدِينَةِ حِينَ يَهْبِطُ مِنَ الصَّفْرَاوَاتِ يَنْزِلُ فِي بَطْنِ ذَلِكَ الْمَسِيلِ عَنْ يَسَارِ الطَّرِيقِ وَأَنْتَ ذَاهِبٌ إِلَى مَكَّةَ لَيْسَ بَيْنَ مَنْزِلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ الطَّرِيقِ إِلَّا رَمْيَةٌ بِحَجَرٍ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറഞ്ഞു: ''മർറുള്ളഹ്റാനി''ന്റെ താഴ്ഭാഗത്തുള്ള വെള്ളച്ചാലിൽ തിരുമേനി(സ) ഇറങ്ങാറുണ്ടായിരുന്നു. നീ ''സഫറാവാത്തിൽ'' നിന്നും ഇറങ്ങി വരുമ്പോൾ മദീനയുടെ ഭാഗത്ത് ആസ്ഥലത്തെ നിനക്കു കാണാം. വെള്ളപ്പാച്ചിലിന്റെ കേന്ദ്രത്തിൽ നബി(സ) ഇറങ്ങാറുണ്ടായിരുന്നു. വഴിയുടെ ഇടതുഭാഗത്ത് നീ മക്കയിലേക്കു പോകുമ്പോൾ തിരുമേനി(സ)യുടെ താവളത്തിനും വഴിക്കുമിടയിൽ കല്ലെറിഞ്ഞാലെത്തുന്ന ദൂരം മാത്രമേ ഉണ്ടായിരുന്നുള്ളൂ. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْزِلُ بِذِي طُوًى وَيَبِيتُ حَتَّى يُصْبِحَ، ثُمَّ يُصَلِّي الصُّبْحَ حِينَ يَقْدَمُ مَكَّةَ وَمُصَلَّى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ عَلَى أَكَمَةٍ غَلِيظَةٍ لَيْسَ فِي الْمَسْجِدِ الَّذِي بُنِيَ ثَمَّ، وَلَكِنْ أَسْفَلَ مِنْ ذَلِكَ عَلَى أَكَمَةٍ غَلِيظَةٍ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറഞ്ഞു: തിരുമേനി(സ) മക്കയിലേക്കു വരുമ്പോൾ ''ദീതുവാ''യിൽ രാത്രി ഇറങ്ങി താമസിക്കും. എന്നിട്ട് സുബ്ഹ് നിസ്കരിക്കും. തിരുമേനി(സ) സുബ്ഹ് നിസ്കരിച്ചത് കല്ലുകളാൽ നിറക്കപ്പെട്ട ഒരു കുന്നിന്മേലാണ്. അതല്ലാതെ അവിടെ പണിതുയർത്തപ്പെട്ട ആ പള്ളിയിലല്ല. പള്ളിയുടെ താഴെയായി കല്ലുകൾ നിറഞ്ഞ ആ കുന്നിന്മേൽ. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'وَكَانَ عَبْدُ اللَّهِ يُحَدِّثُ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتَقْبَلَ فُرْضَتَيِ الْجَبَلِ الَّذِي بَيْنَهُ وَبَيْنَ الْجَبَلِ الطَّوِيلِ نَحْوَ الْكَعْبَةِ، فَجَعَلَ الْمَسْجِدَ الَّذِي بُنِيَ ثَمَّ يَسَارَ الْمَسْجِدِ بِطَرَفِ الْأَكَمَةِ وَمُصَلَّى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَسْفَلَ مِنْهُ عَلَى الْأَكَمَةِ السَّوْدَاءِ تَدَعُ مِنَ الْأَكَمَةِ عَشَرَةَ أَذْرُعٍ أَوْ نَحْوَهَا، ثُمَّ تُصَلِّي مُسْتَقْبِلَ الْفُرْضَتَيْنِ مِنَ الْجَبَلِ الَّذِي بَيْنَكَ وَبَيْنَ الْكَعْبَةِ. (خ)', 'ഇബ്നുഉമർ(റ) നാഫിഇനോട് പറയുന്നു: നബി(സ)ക്കും വളരെ ഉയർന്നുനിൽക്കുന്ന പർവ്വതത്തിനിടയിൽ നിലകെള്ളുന്ന പർവ്വതങ്ങളുടെ രണ്ടു ശിഖരങ്ങളുടെ നേരെ കഅ്ബക്കഭിമുഖമായി നിന്നുകൊണ്ട് നബിതിരുമേനി(സ) നിസ്കരിച്ചിട്ടുണ്ട്. എന്നിട്ട് ഇബ്നുഉമർ(റ) നിസ്കരിച്ചപ്പോൾ, അവിടെ പണിതുയർത്തപ്പെട്ട പള്ളി, കുന്നിന്റെ അറ്റത്തുള്ള പള്ളിയുടെ ഇടതുഭാഗത്താക്കിക്കൊണ്ട് നിന്നു. നബി(സ) നിസ്കരിച്ചതാവട്ടെ, അതിനു താഴെയായിട്ടുമാണ്, ആ കറുത്ത കുന്നിന്മേലും, കഅ്ബക്കും നിനക്കുമിടയിൽ സ്ഥിതിചെയ്യുന്ന മലയുടെ രണ്ട് ശിഖരങ്ങളുടെ നേരെ തിരിഞ്ഞു നിന്നു നിസ്കരിക്കുമ്പോൾ പത്തു മുഴമോ അല്ലെങ്കിൽ ഏതാണ്ട് അത്ര അകലമോ കുന്നിൽനിന്നും വിട്ടിട്ട് നിൽക്കുന്ന പക്ഷം അതു തന്നെയാണ് നബി(സ) നിസ്കരിച്ച സ്ഥലം. (ബു)', null, 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 250, 250, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ مَحْمُودِ بْنِ لَبِيدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عُثْمَانَ بْنَ عَفَّانَ أَرَادَ بِنَاءَ الْمَسْجِدِ، فَكَرِهَ النَّاسُ ذَلِكَ، فَأَحَبُّوا أَنْ يَدَعَهُ عَلَى هَيْئَتِهِ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ بَنَى مَسْجِدًا لِلَّهِ، بَنَى اللَّهُ لَهُ فِي الْجَنَّةِ مِثْلَهُ". (م)', 'മഹ്മൂദുബ്നു ലബീദ്(റ): ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) നബി(സ)യുടെ പള്ളി (പുനർ) നിർമ്മിക്കാനുദ്ദേശിച്ചപ്പോൾ ജനങ്ങൾ അക്കാര്യം വെറുത്തു. അതിന്റെ പഴയ രൂപത്തിൽ നില കൊള്ളുന്നതായിരുന്നു അവർക്കിഷ്ടം. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "ഒരാൾ അല്ലാഹുവിനു വേണ്ടി ഒരു പള്ളി നിർമ്മിച്ചാൽ അതിന് സമാനമായ ഒരു പള്ളി അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (മു)', 'مَحْمُودِ بْنِ لَبِيدٍ', 'മഹ്മൂദുബ്നു ലബീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَمْرِو بْنِ عَبَسَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ بَنَى مَسْجِدًا يُذْكَرُ اللَّهُ فِيهِ، بَنَى اللَّهُ عَزَّ وَجَلَّ لَهُ بَيْتًا فِي الْجَنَّةِ". (ن)', 'അംറുബ്നു അബസ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു സ്മരിക്കപ്പെടുന്ന ഒരു പള്ളി നിർമ്മിക്കുന്നവന് അല്ലാഹു സ്വർഗ്ഗത്തിൽ ഒരു ഭവനം നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (ന)', 'عَمْرِو بْنِ عَبَسَةَ', 'അംറുബ്നു അബസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ عِنْدَ قَوْلِ النَّاسِ فِيهِ، حِينَ بَنَى مَسْجِدَ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّكُمْ أَكْثَرْتُمْ، وَإِنِّي سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ بَنَى مَسْجِدًا، يَبْتَغِي بِهِ وَجْهَ اللَّهِ، بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ". (خ)', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ): അദ്ദേഹം മസ്ജിദുന്നബവി (പുനർ) നിർമ്മിച്ചപ്പോൾ ജനങ്ങൾ അദ്ദേഹത്തെക്കുറിച്ച് വിമർശിച്ചു പറഞ്ഞപ്പോൾ അദ്ദേഹം (ജനങ്ങളോട്) പറഞ്ഞു: നിങ്ങൾ (എന്നെക്കുറിച്ചുള്ള വിമർശനം) അധികരിപ്പിച്ചിരിക്കുന്നു, നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ചു കൊണ്ട് ഒരാൾ പള്ളി നിർമ്മിച്ചാൽ അതിന് സമാനമായ ഒരു പള്ളി അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (ബു)', 'عُثْمَانَ بْنِ عَفَّانَ', 'ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ بَنَى لِلَّهِ مَسْجِدًا – صَغِيرًا كَانَ، أَوْ كَبِيرًا – بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ". (ت)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിനു വേണ്ടി ഒരു പള്ളി നിർമ്മിച്ചാൽ -അത് ചെറുതായാലും വലുതായാലും ശരി-അല്ലാഹു അവന് സ്വർഗ്ഗത്തിൽ ഒരു വീട് നിർമ്മിച്ചു കൊടുക്കുന്നതാണ്." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْأَرْضُ كُلُّهَا مَسْجِدٌ، إِلَّا الْمَقْبَرَةَ وَالْحَمَّامَ. (د,ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ഭൂമി മുഴുവൻ പള്ളിയാണ്, ഖബ്റും, കുളിപ്പുരയും ഒഴികെ." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 251, 251, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "صَلُّوا فِي مَرَابِضِ الْغَنَمِ، وَلَا تُصَلُّوا فِي أَعْطَانِ الْإِبِلِ، فَإِنَّهَا خُلِقَتْ مِنَ الشَّيَاطِينِ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫലുൽ മുസനി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ആടുകൾ വിശ്രമിക്കുന്ന സ്ഥലങ്ങളിൽ നിസ്കരിച്ചുകൊള്ളുക, ഒട്ടകങ്ങൾ വിശ്രമിക്കുന്ന സ്ഥലങ്ങളിൽ നിസ്കരിക്കരുത്. കാരണം, അവ ചെകുത്താനിൽ നിന്ന് സൃഷ്ടിക്കപ്പെട്ടതാണ്." (ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫലുൽ മുസനി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 251, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ لَمْ تَجِدُوا إِلَّا مَرَابِضَ الْغَنَمِ، وَأَعْطَانَ الْإِبِلِ: فَصَلُّوا فِي مَرَابِضِ الْغَنَمِ، وَلَا تُصَلُّوا فِي أَعْطَانِ الْإِبِلِ. (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒട്ടകങ്ങളുടെ ആലയും, ആടുകൾ വിശ്രമിക്കുന്ന സ്ഥലങ്ങളിൽ ഒഴികെ മറ്റൊന്നും ലഭിച്ചില്ലെങ്കിൽ നിങ്ങൾ ആടുകളുടെ വിശ്രമസ്ഥങ്ങളിൽ നിസ്കരിക്കുക. ഒട്ടകങ്ങളുടെ വിശ്രമസ്ഥങ്ങളിൽ നിസ്കരിക്കരുത്." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ سَبْرَةَ بْنِ مَعْبَدٍ الْجُهَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُصَلَّى فِي أَعْطَانِ الْإِبِلِ، وَيُصَلَّى فِي مُرَاحِ الْغَنَمِ". (جه)', 'സബ്റ(റ): നബി(സ) പറഞ്ഞു: "ഒട്ടകത്തിന്റെ വിശ്രമസ്ഥലത്ത് നിസ്കരിക്കാൻ പാടില്ല. ആടുകളുടെ വിശ്രമസ്ഥലത്ത് നിസ്കരിക്കാവുന്നതാണ്." (ജ)', 'سَبْرَةَ بْنِ مَعْبَدٍ الْجُهَنِيِّ', 'സബ്റ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصَلَّى فِي سَبْعِ مَوَاطِنَ: فِي الْمَزْبَلَةِ، وَالْمَجْزَرَةِ، وَالْمَقْبَرَةِ، وَقَارِعَةِ الطَّرِيقِ، وَالْحَمَّامِ، وَمَعَاطِنِ الْإِبِلِ، وَفَوْقَ الْكَعْبَةِ. (ت,جه)', 'ഇബ്നുഉമർ(റ): ഏഴ് സ്ഥലങ്ങളിൽ വെച്ചുള്ള നിസ്കാരം നബി(സ) നിരോധിച്ചിരിക്കുന്നു: മാലിന്യക്കൂമ്പാരങ്ങളിലും, അറവുശാലയിലും, ശ്മശാനങ്ങളിലും, വഴിമദ്ധ്യേയും, കുളിപ്പുരയിലും, ഒട്ടകങ്ങളുടെ വിശ്രമസ്ഥങ്ങളിലും, കഅ്ബയുടെ മീതേയും. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي صَالِحٍ الْغِفَارِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ مَرَّ بِبَابِلَ وَهُوَ يَسِيرُ، فَجَاءَهُ الْمُؤَذِّنُ يُؤْذِنُ بِصَلَاةِ الْعَصْرِ، فَلَمَّا بَرَزَ – وَفِي رِوَايَةٍ: فَلَمَّا خَرَجَ – مِنْهَا أَمَرَ الْمُؤَذِّنَ فَأَقَامَ الصَّلَاةَ، فَلَمَّا فَرَغَ قَالَ: إِنَّ حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَانِي أَنْ أُصَلِّيَ فِي الْمَقْبَرَةِ، وَنَهَانِي أَنْ أُصَلِّيَ فِي أَرْضِ بَابِلَ، فَإِنَّهَا مَلْعُونَةٌ. (د)', 'അബൂസ്വാലിഹുൽ ഗിഫാരി(റ): അലി(റ) ബാബിലോണിയയിലൂടെ സഞ്ചരിക്കുമ്പോൾ അദ്ദേഹത്തിനടുത്ത് അസ്വർ നിസ്കാര സമയം അറിയിക്കുവാൻ മുഅദ്ദിൻ (ബാങ്കു വിളിക്കാരൻ) വന്നു. അദ്ദേഹം വെളിപ്പെട്ടപ്പോൾ -മറ്റൊരു റിപ്പോർട്ടിൽ: അദ്ദേഹം പുറപ്പെട്ടപ്പോൾ- മുഅദ്ദിനോട് ബാങ്ക് വിളിക്കാൻ കൽപിക്കുകയും നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്തു. (നിസ്കാരത്തിൽ നിന്ന്) വിരമിച്ചപ്പോൾ അലി(റ) പറഞ്ഞു: എന്റെ സ്നേഹിതൻ (നബി(സ)) ശ്മശാനത്തിൽ നിസ്കരിക്കുന്നത് നിരോധിച്ചു. ബാബിലോണിയൻ പ്രദേശത്ത് നിസ്കരിക്കുന്നതിനെയും എന്നോട് വിലക്കി. കാരണം ആ പ്രദേശം ശാപബാധിതമാണ്. (ദ)', 'أَبِي صَالِحٍ الْغِفَارِيِّ', 'അബൂസ്വാലിഹുൽ ഗിഫാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=40), 1, 'وَفِي رِوَايَةٍ: فَلَمَّا خَرَجَ – مِنْهَا أَمَرَ الْمُؤَذِّنَ فَأَقَامَ الصَّلَاةَ، فَلَمَّا فَرَغَ قَالَ: إِنَّ حَبِيبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَانِي أَنْ أُصَلِّيَ فِي الْمَقْبَرَةِ، وَنَهَانِي أَنْ أُصَلِّيَ فِي أَرْضِ بَابِلَ، فَإِنَّهَا مَلْعُونَةٌ. (د)', 'മറ്റൊരു നിവേദനിൽ: അദ്ദേഹം പുറപ്പെട്ടപ്പോൾ- മുഅദ്ദിനോട് ബാങ്ക് വിളിക്കാൻ കൽപിക്കുകയും നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്തു. (നിസ്കാരത്തിൽ നിന്ന്) വിരമിച്ചപ്പോൾ അലി(റ) പറഞ്ഞു: എന്റെ സ്നേഹിതൻ (നബി(സ)) ശ്മശാനത്തിൽ നിസ്കരിക്കുന്നത് നിരോധിച്ചു. ബാബിലോണിയൻ പ്രദേശത്ത് നിസ്കരിക്കുന്നതിനെയും എന്നോട് വിലക്കി. കാരണം ആ പ്രദേശം ശാപബാധിതമാണ്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ مَيْمُونَةَ – زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَنْ صَلَّى فِي مَسْجِدِ رَسُولِ اللَّهِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الصَّلَاةُ فِيهِ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ، إِلَّا مَسْجِدَ الْكَعْبَةِ. (ن)', 'പ്രവാചക ഭാര്യ മൈമൂന(റ): അവർ പറയുന്നു: ആരെങ്കിലും നബി(സ)യുടെ പള്ളിയിൽ നിസ്കരിച്ചാൽ (അതിന് എത്ര പുണ്യമുണ്ട് എന്നതിനെ ക്കുറിച്ച്) നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "അവിടെ വെച്ചുള്ള ഒരു നിസ്കാരം ഇതര പള്ളികളിൽ വെച്ചുള്ള ആയിരം നിസ്കാരങ്ങളേക്കാൾ പുണ്യമാണ്. കഅ്ബ ഒഴികെ." (ന)', 'مَيْمُونَةَ – زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ –', 'പ്രവാചക ഭാര്യ മൈമൂന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 252, 252, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ:أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةٌ فِي مَسْجِدِي هَذَا، أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ، إِلَّا الْمَسْجِدَ الْحَرَامَ". (ق,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ ഈ പള്ളിയിൽ വെച്ചുള്ള ഒരു നിസ്കാരം ഇതര പള്ളികളിൽ വെച്ചുള്ള ആയിരം നിസ്കാരത്തേക്കാൾ ഏറ്റവും ശ്രേഷ്ഠമാണ്. മസ്ജിദുൽ ഹറാം ഒഴികെ."(ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَاةٌ فِي مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنَ الْمَسَاجِدِ، إِلَّا الْمَسْجِدَ الْحَرَامَ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آخِرُ الْأَنْبِيَاءِ ، وَمَسْجِدُهُ آخِرُ الْمَسَاجِدِ. وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنِّي آخِرُ الْأَنْبِيَاءِ، وَإِنَّهُ آخِرُ الْمَسَاجِدِ. (ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ പള്ളിയിൽ വെച്ചുള്ള ഒരു നിസ്കാരം മസ്ജിദുൽ ഹറാം ഒഴികെയുള്ള ഇതര പള്ളികളിൽ വെച്ചുള്ള ആയിരം നിസ്കാരത്തെക്കാൾ ശ്രേഷ്ഠമാണ്. കാരണം, അല്ലാഹുവിന്റെ ദൂതൻ(സ) അവസാനത്തെ നബിയും, അവിടുത്തെ പള്ളി അവസാനം വരെ ശേഷിക്കുന്ന പള്ളിയുമാകുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: "ഞാൻ അവസാനത്തെ പ്രവാചകനാണ്, തീർച്ചയായും അത് അവസാന പള്ളിയുമാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=43), 1, 'وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِنِّي آخِرُ الْأَنْبِيَاءِ، وَإِنَّهُ آخِرُ الْمَسَاجِدِ. (ن)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) പറഞ്ഞു: "ഞാൻ അവസാനത്തെ പ്രവാചകനാണ്, തീർച്ചയായും അത് അവസാന പള്ളിയുമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا بَيْنَ بَيْتِي وَمِنْبَرِي، رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ. وَمِنْبَرِي عَلَى حَوْضِي". (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "എന്റെ വീടിനും മിമ്പറിനും ഇടയിലുള്ള സ്ഥലം സ്വർഗ്ഗീയ പൂന്തോപ്പിൽ നിന്നുള്ള ഒരു പൂന്തോപ്പാണ്. എന്റെ മിമ്പർ എന്റ ഹൗളിന്മേലാണ് നിലകൊള്ളുന്നത്." (ബു,മു,തു,ന)', 'عَبْدِ اللَّهِ بْنِ زَيْدٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ قَوَائِمَ مِنْبَرِي هَذَا رَوَاتِبُ فِي الْجَنَّةِ". (ن)', 'ഉമ്മുസലമ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം, എന്റെ ഈ മിമ്പറിന്റെ തൂണുകൾ സ്വർഗ്ഗത്തിനുനേരെ നിൽക്കുന്നവയാണ്." (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: إِنَّ امْرَأَةً اشْتَكَتْ شَكْوَى، فَقَالَتْ: إِنْ شَفَانِي اللَّهُ لَأَخْرُجَنَّ فَلَأُصَلِّيَنَّ فِي بَيْتِ الْمَقْدِسِ، فَبَرَأَتْ، ثُمَّ تَجَهَّزَتْ تُرِيدُ الْخُرُوجَ، فَجَاءَتْ مَيْمُونَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُسَلِّمُ عَلَيْهَا، فَأَخْبَرَتْهَا ذَلِكَ، فَقَالَتِ: اجْلِسِي فَكُلِي مَا صَنَعْتِ، وَصَلِّي فِي مَسْجِدِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "صَلَاةٌ فِيهِ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنَ الْمَسَاجِدِ، إِلَّا مَسْجِدَ الْكَعْبَةِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു സ്ത്രീ ആവലാതിപ്പെട്ടു. അവൾ പറഞ്ഞു: എനിക്ക് അല്ലാഹു രോഗശമനം നൽകിയാൽ തീർച്ചയായും ഞാൻ ബൈത്തുൽ മുഖദ്ദസിലേക്ക് പോയി അവിടെ വെച്ച് നിസ്കരിക്കുന്നതാണ്. അങ്ങനെ അവർക്ക് രോഗശമനം ലഭിക്കുകയും അങ്ങോട്ട് പുറപ്പെടാൻ തയ്യാറെടുപ്പ് നടത്തുകയും ചെയ്തു. അപ്പോൾ നബി(സ)യുടെ ഭാര്യ മൈമൂന(റ) സലാം പറഞ്ഞുകൊണ്ട് അവരുടെ അടുത്തെത്തുകയും അവരോട് ഇവൾ ആ വിവരം ധരിപ്പിക്കുകയും ചെയ്തു. തുടർന്ന് മൈമൂന(റ) പറഞ്ഞു: നീ ഇരിക്കൂ, എന്നിട്ട് നിനക്കു വേണ്ടതൊക്കെ നീ തിന്നൂ!. റസൂലിന്റെ പള്ളിയിൽ നീ നിസ്കരിക്കൂ. അവിടുന്ന് പറയുന്നതായി ഞാൻ കേട്ടു: "ഇവിടെ (മസ്ജിദുന്നബവി) വെച്ചുള്ള ഒരു നിസ്കാരം ഇതര പള്ളികളിൽ വെച്ചുള്ള ആയിരം നിസ്കാരത്തേക്കാൾ പുണ്യമാണ്. മസ്ജിദുൽ ഹറാം ഒഴികെ!" (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 253, 253, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ سَهْلِ بْنِ حُنَيْفٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ خَرَجَ حَتَّى يَأْتِيَ هَذَا الْمَسْجِدَ – مَسْجِدَ قُبَاءٍ – فَصَلَّى فِيهِ، كَانَ لَهُ عَدْلُ عُمْرَةٍ". (ن)', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വീട്ടിൽ നിന്നു പുറപ്പെട്ട് ഈ പള്ളിയിൽ ''ഖുബാഇലെ പള്ളി'' വരികയും, അവിടെ നിന്ന് നിസ്കരിക്കുകയും ചെയ്താൽ അതവന് ഉംറക്കു തുല്യമാണ്." (ന)', 'سَهْلِ بْنِ حُنَيْفٍ', 'സഹ്ലുബ്നു ഹുനൈഫ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتِي مَسْجِدَ قُبَاءٍ رَاكِبًا، أَوْمَاشِيًا، فَيُصَلِّي فِيهِ رَكْعَتَيْنِ. (م,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ''ഖുബാ'' പള്ളിയിലേക്ക് നടന്നും, വാഹനപ്പുറത്തും വരികയും, തുടർന്ന് അവിടെ നിന്ന് രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أُسَيْدِ بْنِ ظُهَيْرٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ:– وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ– عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةٌ فِي مَسْجِدِ قُبَاءٍ كَعُمْرَةٍ". (ت,جه)', 'ഉസൈദുബ്നു ദുഹൈറുൽ അൻസ്വാരി(റ): നബി(സ) പറഞ്ഞു: "ഖുബാ പള്ളിയിൽ വെച്ചുള്ള നിസ്കാരം ഉംറ നിർവ്വഹിച്ചതു പോലെയാണ്." (തു,ജ)', 'أُسَيْدِ بْنِ ظُهَيْرٍ الْأَنْصَارِيِّ', 'ഉസൈദുബ്നു ദുഹൈറുൽ അൻസ്വാരി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ كَانَ لَا يُصَلِّي مِنَ الضُّحَى إِلَّا فِي يَوْمَيْنِ يَوْمَ يَقْدَمُ بِمَكَّةَ فَإِنَّهُ كَانَ يَقْدَمُهَا ضُحًى فَيَطُوفُ بِالْبَيْتِ ثُمَّ يُصَلِّي رَكْعَتَيْنِ خَلْفَ الْمَقَامِ وَيَوْمَ يَأْتِي مَسْجِدَ قُبَاءٍ فَإِنَّهُ كَانَ يَأْتِيهِ كُلَّ سَبْتٍ، فَإِذَا دَخَلَ الْمَسْجِدَ كَرِهَ أَنْ يَخْرُجَ مِنْهُ حَتَّى يُصَلِّيَ فِيهِ، قَالَ وَكَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَزُورُهُ رَاكِبًا وَمَاشِيًا، قَالَ وَكَانَ يَقُولُ إِنَّمَا أَصْنَعُ كَمَا رَأَيْتُ أَصْحَابِي يَصْنَعُونَ، وَلَا أَمْنَعُ أَحَدًا أَنْ يُصَلِّيَ فِي أَيِّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ، غَيْرَ أَنْ لَا تَتَحَرَّوْا طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا. (خ)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം രണ്ടു ദിവസങ്ങളിൽ മാത്രമേ ളുഹാ നിസ്കാരം നിർവ്വഹിക്കാറുള്ളൂ. (ഒന്ന്) മക്കയിൽ പ്രവേശിക്കുന്ന ദിവസം അതായത് ''ദുഹാ'' സമയത്താണ് അദ്ദേഹം പ്രവേശിക്കാറുണ്ടായിരുന്നത്. എന്നിട്ട് അദ്ദേഹം (കഅ്ബയെ) ത്വവാഫ് ചെയ്യും. ശേഷം മഖാമു ഇബ്രാഹീമിന്റെ പിന്നിൽ നിന്നു രണ്ടു റക്അത്ത് നിസ്കാരം നിർവ്വഹിക്കും. (മറ്റൊന്ന്) മസ്ജിദുഖുബാഇൽ വരുന്ന ദിവസം, അവിടേക്ക് അദ്ദേഹം എല്ലാശനിയാഴ്ചയും വരാറുണ്ടായിരുന്നു. അദ്ദേഹം ഖുബാ പള്ളിയിൽ പ്രവേശിച്ചാൽ അതിൽ വെച്ച് നിസ്കരിക്കാതെ പുറത്തു കടക്കാൻ ഇഷ്ടപ്പെട്ടിരുന്നില്ല. നബി(സ) വാഹനത്തിൽ സഞ്ചരിച്ചുകൊണ്ടും, നടന്നുപോയും ഖുബാപള്ളി സന്ദർശിക്കാറുണ്ടെന്ന് ഇബ്നുഉമർ(റ) പറയുമായിരുന്നു. (നബി(സ)യുടെ കാലത്ത് ജീവിച്ചിരുന്ന) എന്റെ സ്നേഹിതന്മാർ എപ്രകാരമാണ് പ്രവർത്തിച്ചിരുന്നത് എന്ന് ഞാൻ കണ്ടതിന്റെ അടിസ്ഥാനത്തിൽ മാത്രമാണ് (ഇപ്രകാരം) ചെയ്യുന്നത്. രാത്രിയിലോ പകലിലോ ഉള്ള ഏതു സമയത്തും നിസ്കരിക്കുന്ന ഒരുത്തനെയും ഞാൻ തടയുകയില്ല. സൂര്യൻ ഉദിച്ചുയരുന്ന സമയത്തും അസ്തമിക്കുന്ന സമയത്തും നിസ്കരിക്കാൻ ഉദ്ദേശിച്ചൊരുങ്ങിയവനെ ഒഴികെ (അവനെ ഞാൻ തടയും) എന്ന് ഇബ്നുഉമർ(റ) പറയാറുണ്ടായിരുന്നു. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 254, 254, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَّ سُلَيْمَانَ بْنَ دَاوُدَ عليهما السلام لَمَّا بَنَى بَيْتَ الْمَقْدِسِ، سَأَلَ اللَّهَ عَزَّ وَجَلَّ خِلَالًا ثَلَاثَةً: سَأَلَ اللَّهَ عَزَّ وَجَلَّ حُكْمًا يُصَادِفُ حُكْمَهُ، فَأُوتِيَهُ. وَسَأَلَ اللَّهَ عَزَّ وَجَلَّ مُلْكًا، لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِهِ فَأُوتِيَهُ، وَسَأَلَ اللَّهَ عَزَّ وَجَلَّ حِينَ فَرَغَ مِنْ بِنَاءِ الْمَسْجِدِ: أَنْ لَا يَأْتِيَهُ أَحَدٌ لَا يَنْهَزُهُ إِلَّا الصَّلَاةُ فِيهِ أَنْ يُخْرِجَهُ مِنْ خَطِيئَتِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "സുലൈമാൻ(അ) ബൈത്തുൽ മുഖദ്ദിസ് (മസ്ജിദുൽ അഖ്സാ) നിർമ്മിച്ചപ്പോൾ അല്ലാഹുവിനോട് മൂന്നു കാര്യങ്ങൾ തേടി: അല്ലാഹുവിന്റെ വിധിയോട് കിടപിടിക്കുന്ന വിധി ചോദിച്ചു. അപ്പോൾ അല്ലാഹു നല്കി. തനിക്കുശേഷം ആർക്കും ലഭിക്കാത്ത അധികാരം ചോദിച്ചപ്പോൾ അതും നല്കി. പള്ളിയുടെ നിർമ്മാണത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ അദ്ദേഹം "നിസ്കരിക്കാൻ വേണ്ടി ഈ പള്ളിയെ സമീപിക്കുന്നവനെ ജന്മദിവസത്തെപ്പോലെ എല്ലാ തെറ്റുകളിൽ നിന്നും മുക്തമാക്കേണമേ." എന്ന് പ്രാർത്ഥിച്ചു. (ന, ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ هُوَ وَأُسَامَةُ بْنُ زَيْدٍ وَبِلَالٌ وَعُثْمَانُ بْنُ طَلْحَةَ فَأَغْلَقُوا عَلَيْهِمْ، فَلَمَّا فَتَحَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنْتُ أَوَّلَ مَنْ وَلَجَ، فَلَقِيتُ بِلَالًا فَسَأَلْتُهُ: هَلْ صَلَّى فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ صَلَّى بَيْنَ الْعَمُودَيْنِ الْيَمَانِيَيْنِ.وَفِي رِوَايَةٍ: قَالَ :بَيْنَ الْأُسْطُوَانَتَيْنِ (خ,م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ)യും, ഉസാമത്തുബ്നു സൈദും, ബിലാലും, ഉസ്മാനുബ്നു ത്വൽഹയും കഅ്ബയിൽ പ്രവേശിച്ചു. എന്നിട്ട് വാതിലടച്ചു. അങ്ങനെ നബി(സ) കഅ്ബ തുറന്നപ്പോൾ ആദ്യമായി അതിൽ പ്രവേശിച്ചത് ഞാനായിരുന്നു. അപ്പോൾ ഞാൻ ബിലാലിനെ കണ്ടുമുട്ടി. ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: നബി(സ) കഅ്ബയിൽ നിസ്കരിച്ചിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതെ, രണ്ട് യമാനി തൂണുകൾക്കിടയിൽ വെച്ച് നിസ്കരിച്ചു. (ബു,മു,ദ,ന)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','م','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ: قَالَ :بَيْنَ الْأُسْطُوَانَتَيْنِ (خ,م,د,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عن ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا حديث دخول النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْكَعْبَةَ قال: فَسَأَلْتُ بِلَالًا حِينَ خَرَجَ مَا صَنَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: جَعَلَ عَمُودًا عَنْ يَسَارِهِ وَعَمُودًا عَنْ يَمِينِهِ وَثَلَاثَةَ أَعْمِدَةٍ وَرَاءَهُ، وَكَانَ الْبَيْتُ يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ، وَفِي رِوَايَةٍ عَمُودَيْنِ عَنْ يَمِينِهِ. (خ)', 'തിരുമേനി(സ) കഅ്ബയിൽ പ്രവേശിച്ച സംഭവം വിവരിക്കുന്ന ഇബ്നുഉമറി(റ)ന്റെ ഹദീസ്. അദ്ദേഹം പറയുന്നു: "കഅ്ബയിൽ നിന്ന് തിരുമേനി(സ) പുറത്തുവന്നപ്പോൾ, തിരുമേനി(സ) എന്തു ചെയ്തു''വെന്ന് ബിലാലിനോട് ഞാൻ ചോദിച്ചു. ബിലാൽ പറഞ്ഞു: "ചില തൂണുകളെ വലതുഭാഗത്തും, ചില തൂണുകളെ ഇടതുഭാഗത്തും ചില തൂണുകളെ പിൻഭാഗത്തും ആക്കിക്കൊണ്ട് തിരുമേനി(സ) നിസ്കരിച്ചു. അന്ന് അഅ്ബക്ക് ആറു തൂണുകളാണുണ്ടായിരുന്നത്'' ഒരു റിപ്പോർട്ടിൽ, ''രണ്ടു തൂണുകളെ വലതുഭാഗത്താക്കിക്കൊണ്ട് നിസ്കരിച്ചു''. (ബു)', 'ابْنِ عُمَرَ', 'തിരുമേനി(സ) കഅ്ബയിൽ പ്രവേശിച്ച സംഭവം വിവരിക്കുന്ന ഇബ്നുഉമറി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 255, 255, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=53), 1, 'وَفِي رِوَايَةٍ عَمُودَيْنِ عَنْ يَمِينِهِ. (خ)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أبي سَعِيدِ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُشَدُّ الرِّحَالُ إِلَّا إِلَى ثَلَاثَةِ مَسَاجِدَ: مَسْجِدِ الْحَرَامِ، وَمَسْجِدي هَذَا، وَمَسْجِدِ الْأَقْصَى". حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "മൂന്ന് പള്ളികളിലേക്കൊഴികെ ആരാധന ലക്ഷ്യം വെച്ച് യാത്ര പുറപ്പെടരുത്: മസ്‌ജിദുൽ ഹറാം, എന്റെ ഈ പള്ളി (മസ്‌ജിദുന്നബവി) മസ്‌ജിദുൽ അഖ്‌സ എന്നീ പള്ളികൾ." (ഹദീസ് ഹസനും സഹീഹുമാണ്) (മു,ബു,തു,ന)', 'أبي سَعِيدِ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['ق','ت','ن']::text[], array['മു','ബു','തു','ന']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "أَحَبُّ الْبِلَادِ إِلَى اللهِ مَسَاجِدُهَا، وَأَبْغَضُ الْبِلَادِ إِلَى اللهِ أَسْوَاقُهَا. (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നാടുകളിൽ നിന്ന് അല്ലാഹുവിന് പ്രിയങ്കരമായത് അവിടെയുള്ള പള്ളികളും ഏറ്റവും വിദ്വേഷമായത് അവിടെയുള്ള മാർക്കറ്റുകളുമാണ്." (മു)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أبي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "إذا رَأَيْتُمُ الرَّجُلَ يَعْتَادُ الْمَسَاجِدَ فَاشْهَدُوا لَهُ بِالْإِيمَانِ. قَالَ اللَّهُ تَعَالَى:{إِنَّمَا يَعْمُرُ مَسَاجِدَ اللهِ مَنْ آمَنَ بِاللهِ} الْآيَةَ". (ت,جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ പതിവായി പള്ളിയിൽ വരുന്നുണ്ടെങ്കിൽ അവന് ഈമാൻ (വിശ്വാസം) ഉണ്ടെന്ന് നിങ്ങൾ സാക്ഷ്യം വഹിക്കുക. അല്ലാഹു പറഞ്ഞു: അല്ലാഹുവിൽ വിശ്വസിക്കുന്നവൻ മാത്രമാണ് പള്ളികളെ സജീവമാക്കുന്നത്." (തു,ജ)', 'أبي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فُضِّلْتُ عَلَى الْأَنْبِيَاءِ بِسِتٍّ: أُعْطِيتُ جَوَامِعَ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَجُعِلَتْ لِيَ الْأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُرْسِلْتُ إِلَى الْخَلْقِ، كَافَّةً وَخُتِمَ بِيَ النَّبِيُّونَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മറ്റു പ്രവാചകന്മാരെക്കാൾ ഞാൻ ആറ് കാര്യങ്ങളിൽ ശ്രേഷ്ഠമാക്കപ്പെട്ടു: എനിക്ക് സമ്പൂർണ്ണ സംസാരം നൽകപ്പെട്ടു, ഭയം കൊണ്ട് ഞാൻ സഹായിക്കപ്പെട്ടു, എനിക്ക് ഗനീമത്ത് സ്വത്തുകൾ അനുവദിക്കപ്പെട്ടു, എനിക്ക് ഭൂമി ശുദ്ധവും പള്ളിയുമാക്കപ്പെട്ടു, ഞാൻ മുഴുവൻ സൃഷ്ടികൾക്കും ദൂതനായി നിയോഗിക്കപ്പെട്ടു, പ്രവാചക ശൃംഖല എന്നെക്കൊണ്ട് അവസാനിച്ചു. (മു)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 256, 256, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أبي سَعِيدٍ الْخُدْرِي رَضِيَ اللَّهُ عَنْهُ: يُحَدِّثُ يَوْمًا حَتَّى أَتَى ذِكْرُ بِنَاءِ الْمَسْجِدِ، فَقَالَ:كُنَّا نَحْمِلُ لَبِنَةً لَبِنَةً وَعَمَّارٌ لَبِنَتَيْنِ لَبِنَتَيْنِ، فَرَآهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَنْفُضُ التُّرَابَ عَنْهُ. وَيَقُولُ: "وَيْحَ عَمَّارٍ، تَقْتُلُهُ الْفِئَةُ الْبَاغِيَةُ، يَدْعُوهُمْ إِلَى الْجَنَّةِ، وَيَدْعُونَهُ إِلَى النَّارِ". قَالَ: يَقُولُ عَمَّارٌ أَعُوذُ بِاللهِ مِنَ الْفِتَنِ. (خ)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): ഒരു ദിവസം അദ്ദേഹം പള്ളി നിർമ്മാണത്തെക്കുറിച്ച് ചിലകാര്യങ്ങൾ സംസാരിക്കുകയായിരുന്നു. അങ്ങനെ അദ്ദേഹം പള്ളി നിർമാമാണത്തെക്കുറിച്ച് സംസാരിക്കാൻ തുടങ്ങി. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ ഓരോ ഇഷ്ടികകൾ ചുമക്കുമ്പോൾ അമ്മാർ(റ) ഈരണ്ട് വീതം ഇഷ്ടികകൾ ചുമക്കുമായിരുന്നു. നബി(സ) അദ്ദേഹത്തെ കണ്ടപ്പോൾ അവിടുന്ന് അദ്ദേഹത്തിന്റെ ചുമലിൽ നിന്ന് മണ്ണ് തട്ടിക്കളയുകയും ഇങ്ങനെ പറയുകയും ചെയ്തു: "അമ്മാറിന്റെ കഷ്ടം!, അക്രമി സംഘം അവനെ കൊന്നുകളയും. അവൻ അവരെ സ്വർഗ്ഗത്തിലേക്കും, അവർ അവനെ നരകത്തിലേക്കും നയിക്കുന്നു." അബൂസഈദ്(റ) പറയുന്നു: അമ്മാർ(റ) പറഞ്ഞു: അല്ലാഹുവിനോട് ഞാൻ നാശങ്ങളിൽ നിന്നും മോചനം പ്രാപിക്കുന്നു. (ബു)', 'أبي سَعِيدٍ الْخُدْرِي', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 256, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَوَضَّأَ أَحَدُكُمْ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ أَتَى الْمَسْجِدَ – لَا يَنْهَزُهُ إِلَّا الصَّلَاةُ، لَا يُرِيدُ إِلَّا الصَّلَاةَ – لَمْ يَخْطُ خَطْوَةً إِلَّا رَفَعَهُ اللهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً، حَتَّى يَدْخُلَ الْمَسْجِدَ. فَإِذَا دَخَلَ الْمَسْجِدَ، كَانَ فِي صَلَاةٍ، مَا كَانَتِ الصَّلَاةُ تَحْبِسُهُ". (ق,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നന്നായി അംഗശുദ്ധി വരുത്തുകയും തുടർന്ന് പള്ളിയിലെത്തുകയും ചെയ്തു. -നിസ്കാരമല്ലാതെ മറ്റൊന്നും അവൻ ഉദ്ദേശിച്ചിട്ടില്ല, നിസ്കാരമല്ലാതെ മറ്റൊന്നും അവനെ വീട്ടിൽ നിന്നും പുറപ്പെടുവിച്ചിട്ടില്ല.- എങ്കിൽ അവന്റെ ഓരോ കാലടിക്കും, അല്ലാഹു ആ കാലടിയുടെ പേരിൽ അവനെ ഒരുപടി ഉയർത്തുന്നതും (അതിന്റെ പേരിൽ) അവന്റെ ഒരു പാപം മായ്ച്ചു കളയുന്നതുമാണ്. അപ്രകാരം അവൻ പള്ളിയിൽ പ്രവേശിച്ചാൽ നിസ്കാരം പ്രതീക്ഷിക്കുമ്പോഴെല്ലാം അവൻ നിസ്കരിക്കുന്നവനെപ്പോലെയാണ്."(ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةُ الْجَمِيعِ تَزِيدُ عَلَى صَلَاتِهِ فِي بَيْتِهِ، وَصَلَاتِهِ فِي سُوقِهِ خَمْسًا وَعِشْرِينَ دَرَجَةً، فَإِنَّ أَحَدَكُمْ إِذَا تَوَضَّأَ فَأَحْسَنَ، وَأَتَى الْمَسْجِدَ، لَا يُرِيدُ إِلَّا الصَّلَاةَ، لَمْ يَخْطُ خَطْوَةً إِلَّا رَفَعَهُ اللهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ خَطِيئَةً حَتَّى يَدْخُلَ الْمَسْجِدَ، وَإِذَا دَخَلَ الْمَسْجِدَ كَانَ فِي صَلَاةٍ، مَا كَانَتْ تَحْبِسُهُ وَتُصَلِّي، يَعْنِي عَلَيْهِ الْمَلَائِكَةُ مَا دَامَ فِي مَجْلِسِهِ الَّذِي يُصَلِّي فِيهِ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ، مَا لَمْ يُحْدِثْ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ജമാഅത്ത് നിസ്കാരത്തിന് വീട്ടിൽ വെച്ചുള്ള നിസ്കാരത്തേക്കാളും അങ്ങാടിയിൽ വെച്ചുള്ള നിസ്കാരത്തെക്കാളും ഇരുപത്തിയഞ്ച് ഇരട്ടി പ്രതിഫലമുണ്ട്. നിങ്ങളിലൊരാൾ നന്നായി വുദൂ ചെയ്യുകയും, നിസ്കാരം മാത്രം ഉദ്ദേശിച്ച് പള്ളിയിൽ വരികയും ചെയ്താൽ, പള്ളിയിൽ പ്രവേശിക്കുന്നതു വരെയുള്ള ഓരോ ചവിട്ടടിക്കും അല്ലാഹു അവന്റെ പദവി ഉയർത്തുകയും, തെറ്റുകൾ ഇല്ലാതാക്കുകയും ചെയ്യും. പള്ളിയിൽ പ്രവേശിച്ചാൽ, നിസ്കാരത്തിനു വേണ്ടി കാത്തിരിക്കുന്ന സമയത്തെല്ലാം അവൻ നിസ്കാരത്തിലുള്ളതു പോലെയാണ്. അവൻ നിസ്കരിച്ച സ്ഥലത്തായിരിക്കുമ്പോഴെല്ലാം അശുദ്ധനാകും വരെ മലക്കുകൾ അവന്നു വേണ്ടി പ്രാർത്ഥിക്കും: അല്ലാഹുവെ, നീ അവന് പൊറുക്കുകയും കരുണ ചെയ്യുകയും ചെയ്യേണമേ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَوْنَ، وَأْتُوهَا تَمْشُونَ، وَعَلَيْكُمُ السَّكِينَةُ، فَمَا أَدْرَكْتُمْ فَصَلُّوا، وَمَا فَاتَكُمْ فَأَتِمُّوا". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തിലേക്ക് വിളിക്കപ്പെട്ടാൽ നിങ്ങൾ ധൃതിപ്പെട്ട് വരരുത്. നിങ്ങൾ ശാന്തരായി നടന്നു വരിക, നിസ്കാരം (ജമാഅത്ത്) ലഭിച്ചാൽ നിസ്കരിക്കുക, നഷ്ടപ്പെട്ട റക്അത്തുകൾ പൂർത്തിയാക്കുക." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 257, 257, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أبي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَيْنَمَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَمِعَ جَلَبَةً، فَقَالَ: "مَا شَأْنُكُمْ". قَالُوا: اسْتَعْجَلْنَا إِلَى الصَّلَاةِ، قَالَ: "فَلَا تَفْعَلُوا، إِذَا أَتَيْتُمُ الصَّلَاةَ فَعَلَيْكُمُ السَّكِينَةُ، فَمَا أَدْرَكْتُمْ فَصَلُّوا، وَمَا سَبَقَكُمْ فَأَتِمُّوا". (ق)', 'അബൂഖതാദ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു ശബ്ദം കേട്ടു. നബി(സ) ചോദിച്ചു: "എന്താണ് നിങ്ങളുടെ പ്രശ്നം?" അവർ പറഞ്ഞു: ഞങ്ങൾ നിസ്കാരത്തിലേക്ക് ധൃതികൂട്ടി, നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അങ്ങനെ ചെയ്യരുത്, നിസ്കാരത്തിലേക്ക് വരുമ്പോൾ ശാന്തരാവുക. നിങ്ങൾക്ക് കിട്ടിയത് (ജമാഅത്തായി) നിങ്ങൾ നിസ്കരിക്കുക. നഷ്ടപ്പെട്ടത് (റക്അത്തുകൾ) പൂർത്തിയാക്കുക." (ബു,മു)', 'أبي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أبي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللَّهُ بِهِ الْخَطَايَا وَيَزِيدُ بِهِ فِي الْحَسَنَاتِ؟". قَالُوا: بَلَى يَا رَسُولَ اللهِ، قَالَ: "إِسْبَاغُ الْوُضُوءِ عِنْدَ الْمَكَارِهِ، وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ، وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ". (م,ت,ن,جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) ഇപ്രകാരം പറയുന്നതായി അദ്ദേഹം കേട്ടു: "നന്മകൾ വർദ്ധിപ്പിക്കുകയും, ദോഷങ്ങൾ പൊറുക്കുകയും ചെയ്യുന്ന കാര്യങ്ങളെപ്പറ്റി ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചുതരട്ടെയോ?" അനുചരർ പറഞ്ഞു: അതെ പ്രവാചകരെ, നബി(സ) പറഞ്ഞു: "പ്രയാസകരമായ സന്ദർഭങ്ങളിലും വുദുവിൽ കയറ്റി കഴുകുക, പള്ളികളിലേക്കുള്ള (നിങ്ങളുടെ) ചവിട്ടടികൾ വർദ്ധിക്കുക, ഒരു നിസ്കാര ശേഷം മറ്റൊരു നിസ്കാരം പ്രതീക്ഷിക്കുക." (മു,തു,ന,ജ)', 'أبي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَنْ سَرَّهُ أَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ غَدًا مُسْلِمًا فَلْيُحَافِظْ عَلَى هَؤُلَاءِ الصَّلَوَاتِ الْخَمْسِ حَيْثُ يُنَادَى بِهِنَّ، فَإِنَّهُنَّ مِنْ سُنَنِ الْهُدَى، وَإِنَّ اللَّهَ شَرَعَ لِنَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُنَنَ الْهُدَى، وَلَعَمْرِي لَوْ أَنَّ كُلَّكُمْ صَلَّى فِي بَيْتِهِ لَتَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ، وَلَوْ تَرَكْتُمْ سُنَّةَ نَبِيِّكُمْ لَضَلَلْتُمْ، وَلَقَدْ رَأَيْتُنَا وَمَا يَتَخَلَّفُ عَنْهَا إِلَّا مُنَافِقٌ مَعْلُومُ النِّفَاقِ، وَلَقَدْ رَأَيْتُ الرَّجُلَ يُهَادَى بَيْنَ الرَّجُلَيْنِ حَتَّى يَدْخُلَ فِي الصَّفِّ. وَمَا مِنْ رَجُلٍ يَتَطَهَّرُ فَيُحْسِنُ الطُّهُورَ، فَيَعْمِدُ إِلَى الْمَسْجِدِ فَيُصَلِّي فِيهِ: فَمَا يَخْطُو خَطْوَةً إِلَّا رَفَعَ اللَّهُ لَهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً. (م,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): വല്ലവനും താൻ മുസ്‌ലിമായി കൊണ്ട് നാളെ (അന്ത്യനാളിൽ) അല്ലാഹുവിനെ കണ്ടുമുട്ടുവാൻ ഇഷ്ടപ്പെടുന്നുവെങ്കിൽ അവൻ ഈ അഞ്ച് നിസ്കാരങ്ങൾ അവയുടെ കൃത്യസമയത്ത് തന്നെ നിർവ്വഹിക്കട്ടെ. കാരണം, അവ സന്മാർഗ്ഗത്തിലേക്കുള്ള പാതകളാണ്. നിശ്ചയം, അല്ലാഹു നിങ്ങളുടെ നബിക്ക് സന്മാർഗ്ഗത്തിന്റെ വഴികൾ കാണിച്ചു കൊടുത്തിരിക്കുന്നു. തീർച്ചയായും നിങ്ങളെല്ലാവരും വീട്ടിൽ വെച്ച് നിസ്കരിച്ചാൽ നിങ്ങൾ നബിചര്യ ഉപേക്ഷിച്ചവരാകും. നബിചര്യ ഉപേക്ഷിച്ചാൽ നിങ്ങൾ വഴികേടിലാകും. ഞങ്ങളുടെ കൂട്ടത്തിൽ അതിൽ നിന്ന് പിന്തിയിരുന്നതായി ഞാൻ കണ്ടത് പ്രകടമായ കപടവിശ്വാസികളെ മാത്രമായിരുന്നു. ചില വ്യക്തികൾ മറ്റു രണ്ടു പേരുടെ സഹായത്താൽ (പള്ളിയിലേക്ക്) വരികയും നമസ്കാരത്തിന്റെ സഫ്ഫിൽ നിർത്തപ്പെടുകയും ചെയ്യാറുള്ളതായി ഞാൻ കണ്ടിട്ടുണ്ട്. ശരിയായി അംഗശുദ്ധി വരുത്തി പള്ളിയിൽ വന്ന് നിസ്കരിക്കുന്ന ഒരുത്തനും, അവന്റെ ഓരോ ചവിട്ടിക്കും (പകരമായി) അല്ലാഹു അവന്റെ പാപങ്ങൾ പൊറുക്കുകയും അവന്റെ സ്ഥാനം അധികരിപ്പിക്കുകയും ചെയ്യാതിരിക്കില്ല. (മു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 258, 258, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أبي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ خَرَجَ مِنْ بَيْتِهِ إِلَى الصَّلَاةِ فَقَالَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِحَقِّ السَّائِلِينَ عَلَيْكَ، وَأَسْأَلُكَ بِحَقِّ مَمْشَايَ هَذَا، فَإِنِّي لَمْ أَخْرُجْ أَشَرًا وَلَا بَطَرًا وَلَا رِيَاءً وَلَا سُمْعَةً، وَخَرَجْتُ اتِّقَاءَ سُخْطِكَ، وَابْتِغَاءَ مَرْضَاتِكَ، فَأَسْأَلُكَ أَنْ تُعِيذَنِي مِنَ النَّارِ، وَأَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. أَقْبَلَ اللَّهُ عَلَيْهِ بِوَجْهِهِ وَاسْتَغْفَرَ لَهُ سَبْعُونَ أَلْفَ مَلَكٍ". (جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ വീട്ടിൽ നിന്ന് നിസ്കാരത്തിനായി പുറപ്പെട്ട്; "അല്ലാഹുവേ, നിന്നോട് തേടുന്നവരുടെ സത്യസന്ധത കൊണ്ടും, എന്റെ ഈ നടത്തത്തിന്റെ സത്യസന്ധത കൊണ്ടും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. ഞാൻ അഹങ്കാരിയും, ആത്മാഭിമാനിയുമായി പ്രസിദ്ധിക്കും, ലോകമാന്യതക്കും വേണ്ടി പുറപ്പെട്ടതല്ല. നിന്റെ തൃപ്തി കാംക്ഷിച്ചും, നിന്റെ കോപത്തിൽ നിന്ന് സുരക്ഷിതനാവാനും വേണ്ടി പുറപ്പെട്ടതാണ്. എനിക്ക് പാപമോചനവും, നരകമോചനവും നൽകാൻ ഞാൻ നിന്നോട് തേടുന്നു. നീയല്ലാതെ പാപങ്ങൾ പൊറുക്കുന്നവനില്ല." എന്ന് പ്രാർത്ഥിച്ചാൽ അല്ലാഹു അവനോടടുക്കുകയും, എഴുപതിനായിരം മലക്കുകൾ അവനു വേണ്ടി പാപമോചനത്തിനും തേടുകയും ചെയ്യുന്നതാണ്." (ജ)', 'أبي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 258, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمَشَّاءُونَ إِلَى الْمَسَاجِدِ فِي الظُّلَمِ أُولَئِكَ الْخَوَّاضُونَ فِي رَحْمَةِ اللهِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇരുളിൽ പള്ളികളിലേക്ക് നടക്കുന്നവൻ അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിൽ ലയിച്ചവരാണ്." (ജ)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيُبَشِّرِ الْمَشَّاءُونَ فِي الظُّلَمِ إِلَى الْمَسَاجِدِ بِنُورٍ تَامٍّ يَوْمَ الْقِيَامَةِ". (جه)', 'സഹ്‌ലുബ്നു സഅ്ദുസ്സാഇദി(റ): നബി(സ) പറഞ്ഞു: "ഇരുളിൽ പള്ളികളിലേക്ക് നടക്കുന്നവർ അന്ത്യനാളിൽ സമ്പൂർണ്ണ പ്രകാശം കൊണ്ട് സന്തോഷവാന്മാരായിരിക്കട്ടെ." (ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്‌ലുബ്നു സഅ്ദുസ്സാഇദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَشِّرِ الْمَشَّائِينَ فِي الظُّلَمِ إِلَى الْمَسَاجِدِ بِالنُّورِ التَّامِّ يَوْمَ الْقِيَامَةِ". (د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "ഇരുളിൽ പള്ളികളിലേക്ക് പുറപ്പെടുന്നവരെ അന്ത്യനാളിലെ സമ്പൂർണ്ണ പ്രകാശം കൊണ്ട് സന്തോഷ വാർത്ത അറിയിക്കുക." (ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْأَبْعَدُ فَالْأَبْعَدُ مِنَ الْمَسْجِدِ أَعْظَمُ أَجْرًا". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പള്ളിയിൽ നിന്ന് ഏറ്റവുമധികം വിദൂരത്തുള്ള (വനായിരിക്കെ) പള്ളിയിൽ വരുന്നവനാണ് ഏറ്റവും മഹത്തായ പ്രതിഫലം. പിന്നെ അതിൽ കുറഞ്ഞ ദൂരത്തുള്ളവനും" (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَرَادَتْ بَنُو سَلِمَةَ أَنْ يَتَحَوَّلُوا مِنْ دِيَارِهِمْ إِلَى قُرْبِ الْمَسْجِدِ، فَكَرِهَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعْرُوا الْمَدِينَةَ، فَقَالَ: "يَا بَنِي سَلِمَةَ، أَلَا تَحْتَسِبُونَ آثَارَكُمْ". فَأَقَامُوا. (خ,جه)', 'അനസ്(റ): സലമ ഗോത്രക്കാർ അവരുടെ വീടുകൾ പള്ളിയുടെ അടുത്തേക്കു മാറ്റാൻ തീരുമാനിച്ചു. അപ്പോൾ അവർ മദീനയെ വിജനമാക്കുന്നത് നബി(സ) ഇഷ്ടപ്പെട്ടില്ല. നബി(സ) ചോദിച്ചു: "ബനൂ സലമക്കാരെ, നിങ്ങളുടെ കാൽപാടുകൾക്ക് പ്രതിഫലം ലഭിക്കാൻ നിങ്ങൾ ആഗ്രഹിക്കുന്നില്ലയോ?" അങ്ങനെ അവർ അവിടെത്തന്നെ താമസമുറപ്പിച്ചു. (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 259, 259, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:كَانَتِ الْأَنْصَارُ بَعِيدَةً مَنَازِلُهُمْ مِنَ الْمَسْجِدِ، فَأَرَادُوا أَنْ يَقْتَرِبُوا، فَنَزَلَتْ: {وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ} قَالَ: فَثَبَتُوا. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അൻസ്വാരികളുടെ വീടുകൾ പള്ളിയിൽ നിന്നും അകന്നായിരുന്നു, അവർ പള്ളിയുടെ അടുത്തേക്ക് താമസം മാറ്റാനുദ്ദേശിച്ചു. അപ്പോൾ ഈ ഖുർആൻ സൂക്തം അവതരിച്ചു: "അവർ മുൻകൂട്ടി ചെയ്തതും അവരുടെ കാൽപാടുകളും നാം എഴുതി വെക്കും." അപ്പോഴവർ അവിടെത്തന്നെ സ്ഥിരതാമസമാക്കി. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ مِنَ الْأَنْصَارِ بَيْتُهُ أَقْصَى بَيْتٍ فِي الْمَدِينَةِ، فَكَانَ لَا تُخْطِئُهُ الصَّلَاةُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَتَوَجَّعْتُ لَهُ، فَقُلْتُ لَهُ: يَا فُلَانُ، لَوْ أَنَّكَ اشْتَرَيْتَ حِمَارًا يَقِيكَ مِنَ الرَّمْضَاءِ، وَيَقِيكَ مِنْ هَوَامِّ الْأَرْضِ، قَالَ: أَمَ وَاللَّهِ مَا أُحِبُّ أَنَّ بَيْتِي مُطَنَّبٌ بِبَيْتِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَحَمَلْتُ بِهِ حَمْلًا حَتَّى أَتَيْتُ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرْتُهُ، قَالَ: فَدَعَاهُ، فَقَالَ لَهُ مِثْلَ ذَلِكَ، وَذَكَرَ لَهُ أَنَّهُ يَرْجُو فِي أَثَرِهِ الْأَجْرَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لَكَ مَا احْتَسَبْتَ". (م,د,جه)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ): അൻസ്വാരികളിൽ ഒരാളുടെ ഭവനം മദീനയിൽ നിന്നും വളരെ അകലെയായിരുന്നു. എന്നിട്ടും നബി(സ)യോടൊപ്പമുള്ള ഒരു നിസ്കാരം പോലും അദ്ദേഹത്തിന് നഷ്ടപ്പെട്ടിരുന്നില്ല. ഞാൻ അദ്ദേഹത്തോട് (ദു:ഖിതനായി) ആവലാതി പറഞ്ഞു. ഹേ മനുഷ്യാ, താങ്കൾ ഒരു കഴുതയെ വാങ്ങിയാൽ മണൽ തരികളുടെ ചൂടിൽ നിന്നും താങ്കളുടെ കാൽപാദത്തെ രക്ഷിക്കുകയും ഭൂമിയിലെ ഉപദ്രവകാരിയായ ജീവികളിൽ (ഇഴജന്തുക്കൾ) നിന്നും താങ്കളെ സംരക്ഷിക്കുകയും ചെയ്യും. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ ഭവനം റസൂലി(സ)ന്റെ ഭവനവുമായി വളരെ അടുത്താകുന്നതിനെ ഞാൻ ഇഷ്ടപ്പെടുന്നില്ല. അദ്ദേഹം വീണ്ടും പറയുന്നു: അദ്ദേഹത്തിന്റെ വാക്ക് വലിയ ഭാരമായി എനിക്ക് തോന്നുകയും മോശമായി അനുഭവപ്പെടുകയും ഞാൻ റസൂലി(സ)ന്റെ അടുത്ത് അദ്ദേഹത്തേയും കൂടെ കൂട്ടി കൊണ്ട് ചെന്ന് വിവരം തിരുമേനിയെ അറിയിക്കുകയും ചെയ്തു. നബി(സ) അയാളെ വിളിച്ച് ചോദിച്ചപ്പോൾ നബി(സ)യോടദ്ദേഹം അപ്രകാരം തന്നെ പറഞ്ഞു. ഓരോ നടത്തത്തിലും കൂലി പ്രതീക്ഷിക്കുന്നുവെന്നുകൂടി അയാൾ പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിനക്ക് നീ പ്രതീക്ഷിച്ചതുണ്ട്." (മു,ദ,ജ)', 'أُبَيِّ بْنِ كَعْبٍ', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَطَهَّرَ فِي بَيْتِهِ ثُمَّ مَشَى إِلَى بَيْتٍ مِنْ بُيُوتِ اللهِ، لِيَقْضِيَ فَرِيضَةً مِنْ فَرَائِضِ اللهِ، كَانَتْ خُطْوَاتُهُ إِحْدَاهُمَا تَحُطُّ خَطِيئَةً، وَالْأُخْرَى تَرْفَعُ دَرَجَةً". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ വീട്ടിൽ വെച്ച് ശുദ്ധിവരുത്തുകയും (വുദു ചെയ്യുകയും) അല്ലാഹുവിന്റെ പള്ളിയിലേക്ക് അവൻ നിർബന്ധമാക്കിയ ഒരു കടമ നിർവ്വഹിക്കാൻ വേണ്ടി സഞ്ചരിക്കുകയും ചെയ്താൽ അവന്റെ ചവിട്ടടികളിൽ ഒന്ന് അവന്റെ പാപം മായ്ച്ചു കളയുന്നതും മറ്റേത് അവന്റെ പദവി ഉയർത്തുന്നതുമാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حِينَ يَخْرُجُ الرَّجُلُ مِنْ بَيْتِهِ إِلَى مَسْجِدِهِ: فَرِجْلٌ تُكْتَبُ حَسَنَةً، وَرِجْلٌ تَمْحُو سَيِّئَةً". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ വീട്ടിൽ നിന്നും പള്ളിയിലേക്കു പുറപ്പെടുമ്പോൾ ഒരു കാൽവെപ്പ് നന്മയായി എഴുതപ്പെടുകയും, മറ്റൊരു കാൽവെപ്പ് തെറ്റിനെ മായ്ച്ചു കളയുകയും ചെയ്യുന്നു." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 260, 260, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمَلَائِكَةَ تُصَلِّي عَلَى أَحَدِكُمْ، مَا دَامَ فِي مُصَلَّاهُ الَّذِي صَلَّى فِيهِ، مَا لَمْ يُحْدِثْ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരം നിർവ്വഹിച്ച സ്ഥലത്ത് അശുദ്ധനാവാതെ ഇരിക്കുന്ന സമയത്തെല്ലാം നിങ്ങളിലോരോരുത്തർക്കും വേണ്ടി മലക്കുകൾ പ്രാർത്ഥിക്കും: അല്ലാഹുവേ, നീ അവന് പൊറുത്തു കൊടുക്കുകയും കരുണ ചെയ്യുകയും ചെയ്യേണമേ." (ബു,മു,ദ,തു,ന,ജ)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 261, 261, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا تَوَطَّنَ رَجُلٌ مُسْلِمٌ الْمَسَاجِدَ لِلصَّلَاةِ وَالذِّكْرِ إِلَّا تَبَشْبَشَ اللَّهُ لَهُ، كَمَا يَتَبَشْبَشُ أَهْلُ الْغَائِبِ بِغَائِبِهِمْ إِذَا قَدِمَ عَلَيْهِمْ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മുസ്‌ലിമായ ഒരു വ്യക്തി പള്ളികളെ നിസ്കാരത്തിനും, അല്ലാഹുവിനെ സ്മരിക്കാനും വേണ്ടി സ്വന്തം ദേശത്തെപ്പോലെ ² സ്വീകരിച്ചാൽ അല്ലാഹു അവനു വേണ്ടി സന്തോഷിക്കുന്നതാണ്. വീട്ടിൽ നിന്നും പോയ വ്യക്തി തിരിച്ചു വരുമ്പോൾ വീട്ടുകാർ സന്തോഷിക്കുന്നതുപോലെ." (ജ)', 'أبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '². ഒരാൾ നിസ്കരിക്കുവാനും അല്ലാഹുവിനെ സ്മരിക്കുവാനും വേണ്ടി നിരന്തരം പള്ളിയുമായി ബന്ധപ്പെടുകയും പള്ളിയെ പരിപാലിക്കുവാനും സംരക്ഷിക്കുവാനും സന്നദ്ധത കാണിക്കുകയും, അതിനെ സ്നേഹിക്കുകയും ആദരിക്കുകയും ചെയ്താൽ, ആ വ്യക്തി ഓരോ പ്രാവശ്യം പള്ളിയിലേക്ക് വരുമ്പോഴും, വീടു വിട്ടുപോയവൻ അവിടേക്ക് തിരിച്ചു വരുമ്പോൾ വീട്ടുകാർ സന്തോഷിക്കാറുള്ളതു പോലെ അല്ലാഹു സന്തോഷിക്കും എന്ന് വിവക്ഷ.', null, array['جه']::text[], array['ജ']::text[], null, null, 261, 261, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: صَلَّيْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَغْرِبَ، فَرَجَعَ مَنْ رَجَعَ وَعَقَّبَ مَنْ عَقَّبَ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسْرِعًا قَدْ حَفَزَهُ النَّفَسُ، وَقَدْ حَسَرَ عَنْ رُكْبَتَيْهِ، فَقَالَ: "أَبْشِرُوا، هَذَا رَبُّكُمْ قَدْ فَتَحَ بَابًا مِنْ أَبْوَابِ السَّمَاءِ، يُبَاهِي بِكُمُ الْمَلَائِكَةَ. يَقُولُ:انْظُرُوا إِلَى عِبَادِي، قَدْ قَضَوْا فَرِيضَةً وَهُمْ يَنْتَظِرُونَ أُخْرَى". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ)യോടൊപ്പം ഞങ്ങൾ മഗ്‌രിബ് നിസ്കരിച്ചു. ചിലർ മടങ്ങി, മറ്റു ചിലർ അവിടെത്തന്നെ നിന്നു. നബി(സ) വളരെ ധൃതിപ്പെട്ട് കിതച്ചുകൊണ്ട്, തന്റെ മുട്ടിൻകാലുകൾ വെളിവാക്കിയ നിലയിൽ വന്നു. പിന്നെ പറഞ്ഞു: "നിങ്ങൾ സന്തോഷിക്കുക, നിങ്ങളെക്കുറിച്ച് മലക്കുകളോട് മഹത്വം പറഞ്ഞുകൊണ്ട് അല്ലാഹു ഒരു ആകാശ കവാടം തുറന്നിട്ടുണ്ട്. അവൻ പറയുന്നു: എന്റെ അടിമകളെ നിങ്ങൾ നോക്കൂ! അവർ ഒരു നിർബന്ധ നിസ്കാരം കഴിഞ്ഞ് മറ്റൊന്ന് പ്രതീക്ഷിച്ചിരിക്കുകയാണ്." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 261, 261, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا دَامَ يَنْتَظِرُهَا، وَلَا تَزَالُ الْمَلَائِكَةُ تُصَلِّي عَلَى أَحَدِكُمْ مَا دَامَ فِي الْمَسْجِدِ: اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ارْحَمْهُ، مَا لَمْ يُحْدِثْ". فَقَالَ رَجُلٌ مِنْ حَضْرَمَوْتَ: وَمَا الْحَدَثُ يَا أَبَا هُرَيْرَةَ؟ قَالَ: فُسَاءٌ أَوْ ضُرَاطٌ. حَدِيثٌ حَسَنٌ صَحِيحٌ. (م,د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിസ്കാരത്തെ പ്രതീക്ഷിച്ചിരിക്കുന്ന സമയത്തെല്ലാം നിങ്ങളിലോരോരുത്തരും നിസ്കാരത്തിൽ തന്നെയാണ്. നിങ്ങളോരുത്തരും പള്ളിയിലായിരിക്കുമ്പോൾ മലക്കുകൾ ഇപ്രകാരം പ്രാർത്ഥിച്ചു കൊണ്ടിരിക്കുന്നു: അല്ലാഹുവേ, അവന് നീ പൊറുത്തു കൊടുക്കുകയും കരുണ ചെയ്യുകയും ചെയ്യേണേമേ. അശുദ്ധിയുണ്ടാകുന്നതുവരെ." അപ്പോൾ ഹളർമൗത്തിലെ ഒരാൾ ചോദിച്ചു: അബൂഹുറൈറാ എന്താണ് അശുദ്ധി? അദ്ദേഹം പറഞ്ഞു: കീഴ്‌വായു. (മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 261, 261, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ سَهْلٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ فِي الْمَسْجِدِ يَنْتَظِرُ الصَّلَاةَ فَهُوَ فِي الصَّلَاةِ". (ن)', 'സഹ്‌ലുസ്സാഇദി(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പള്ളിയിൽ നിസ്കാരം പ്രതീക്ഷിച്ചിരിക്കുന്ന വ്യക്തി നിസ്കാരത്തിൽ തന്നെയാണ്." (ന)', 'سَهْلٍ السَّاعِدِيِّ', 'സഹ്‌ലുസ്സാഇദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَتَى الْمَسْجِدَ لِشَيْءٍ فَهُوَ حَظُّهُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ എന്തിനെങ്കിലും പള്ളിയിലെത്തിയാൽ അത് അവന്റെ ഭാഗ്യമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا كَانَتِ الصَّلَاةُ تَحْبِسُهُ، لَا يَمْنَعُهُ أَنْ يَنْقَلِبَ إِلَى أَهْلِهِ إِلَّا الصَّلَاةُ". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും വീട്ടിലേക്ക് പോകുന്നതിൽ നിന്ന് നിസ്കാരം തടസ്സം ചെയ്യുമ്പോഴെല്ലാം അവൻ നിസ്കാരത്തിൽ തന്നെയാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "جُعِلَتْ لِيَ الْأَرْضُ مَسْجِدًا وَطَهُورًا، أَيْنَمَا أَدْرَكَ رَجُلٌ مِنْ أُمَّتِي الصَّلَاةَ صَلَّى". (ن)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ഭൂമി എനിക്ക് പരിശുദ്ധവും പള്ളിയുമാക്കപ്പെട്ടിരിക്കുന്നു. എന്റെ സമുദായത്തിൽപ്പെട്ട ആർക്കെങ്കിലും എവിടെയെങ്കിലും വെച്ച് നിസ്കാര സമയമെത്തിയാൽ അവൻ (അവിടെ വെച്ച്) നിസ്കരിക്കട്ടെ." (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي الشَّعْثَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ:كُنَّا قُعُودًا فِي الْمَسْجِدِ مَعَ أَبِي هُرَيْرَةَ، فَأَذَّنَ الْمُؤَذِّنُ، فَقَامَ رَجُلٌ مِنَ الْمَسْجِدِ يَمْشِي، فَأَتْبَعَهُ أَبُو هُرَيْرَةَ بَصَرَهُ حَتَّى خَرَجَ مِنَ الْمَسْجِدِ، فَقَالَ أَبُو هُرَيْرَةَ: أَمَّا هَذَا فَقَدْ عَصَى أَبَا الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബുശ്ശഅ്സാഅ്(റ): ഞങ്ങൾ അബൂഹുറൈറയോടൊപ്പം പള്ളിയിൽ ഇരിക്കുമ്പോൾ ബാങ്ക് വിളിക്കുന്നവൻ ബാങ്ക് വിളിച്ചു. അപ്പോൾ ഒരാൾ പള്ളിയിൽ നിന്ന് നടന്നുപോയി. അദ്ദേഹം പള്ളിയിൽ നിന്ന് പുറപ്പെടുന്നതുവരെ അബൂഹുറൈറ അയാളെ കണ്ണെടുക്കാതെ നോക്കിക്കൊണ്ടു പറഞ്ഞു: ഇദ്ദേഹം അബുൽ ഖാസിമിനെ (റസൂലിനെ) ധിക്കരിച്ചിരിക്കുന്നു. (മു)', 'أَبِي الشَّعْثَاءِ', 'അബുശ്ശഅ്സാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 262, 262, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ فَاطِمَةَ – بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْمَسْجِدَ يَقُولُ: "بِسْمِ اللهِ وَالسَّلَامُ عَلَى رَسُولِ اللهِ. اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي، وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ. وَإِذَا خَرَجَ قَالَ: بِسْمِ اللهِ وَالسَّلَامُ عَلَى رَسُولِ اللهِ. اللَّهُمَّ اغْفِرْ لِي ذُنُوبِي، وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ". (ت,جه)', 'ഫാത്വിമ(റ): നബി(സ) പള്ളിയിൽ പ്രവേശിക്കുമ്പോൾ; "അല്ലാഹുവിന്റെ നാമത്തിൽ; സർവ്വ രക്ഷയും അല്ലാഹുവിന്റെ ദൂതന്റെ മേൽ വർഷിക്കട്ടെ, എന്റെ പാപങ്ങൾ പൊറുത്തു തരികയും നിന്റെ അനുഗ്രഹത്തിന്റെ വാതായനങ്ങൾ എനിക്ക് തുറന്നു തരികയും ചെയ്യേണമേ." എന്നും, പുറത്തു വരുമ്പോൾ; "അല്ലാഹുവിന്റെ നാമത്തിൽ; സർവ്വ രക്ഷയും അല്ലാഹുവിന്റെ ദൂതന്റെമേൽ വർഷിക്കട്ടെ, എന്റെ പാപങ്ങൾ പൊറുത്തു തരികയും, നിന്റെ മഹത്വത്തിന്റെ കവാടങ്ങൾ എനിക്ക് തുറന്നുതരികയും ചെയ്യേണമേ." എന്നും പറയാറുണ്ടായിരുന്നു. (തു,ജ)', 'فَاطِمَةَ – بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ –', 'ഫാത്വിമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 262, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي حُمَيْدٍ أَوْ: – أَبِي أُسَيْدٍ – الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ، فَلْيُسَلِّمْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ لِيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، فَإِذَا خَرَجَ فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ". (م,د,ت,ن,جه)', 'അബൂഹുമൈദുസ്സാഇദി അല്ലെങ്കിൽ അബൂഉസൈദുൽ അൻസ്വാരി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പ്രവേശിച്ചാൽ നബി(സ)യുടെ മേൽ സലാം ചൊല്ലട്ടെ. തുടർന്ന് അവൻ; അല്ലാഹുവേ, നിന്റെ അനുഗ്രഹ കവാടങ്ങൾ എനിക്ക് തുറന്നു തരേണമേ. എന്നും, അവിടെ നിന്ന് പുറപ്പെട്ടാൽ; അല്ലാഹുവെ, നിന്റെ ഔദാര്യത്തിൽ നിന്നും ഞാൻ നിന്നോട് തേടുന്നു എന്നും പറയട്ടെ." (മു,ദ,തു,ന,ജ)', 'أَبِي حُمَيْدٍ أَوْ', 'അബൂഹുമൈദുസ്സാഇദി അല്ലെങ്കിൽ അബൂഉസൈദുൽ അൻസ്വാരി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 263, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ إِذَا دَخَلَ الْمَسْجِدَ قَالَ: "أَعُوذُ بِاللهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചാൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "മഹോന്നതനായ അല്ലാഹുവിനെ കൊണ്ടും, അവന്റെ പവിത്രമായ തിരുമുഖം കൊണ്ടും, അവന്റെ അനാദിയായ ആധിപത്യം കൊണ്ടും ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് ഞാൻ കാവൽ തേടുന്നു." (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 263, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ، فَلْيُسَلِّمْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلْيَقُلِ: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ، وَإِذَا خَرَجَ فَلْيُسَلِّمْ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلْيَقُلِ: اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പ്രവേശിച്ചാൽ നബി(സ)യുടെമേൽ സലാം പറയട്ടെ, ശേഷം ''അല്ലാഹുവേ, നിന്റെ അനുഗ്രഹ വാതായനങ്ങൾ എനിക്ക് തുറന്നുതരേണമേ എന്നു പ്രാർത്ഥിക്കുകയും ചെയ്യട്ടെ. അവിടെ നിന്നും പുറപ്പെട്ടാൽ; നബി(സ)യുടെ മേൽ സലാം പറയുകയും, ശേഷം; അല്ലാഹുവേ, ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് നീ എന്നെ രക്ഷിക്കേണമേ'' എന്നു പ്രാർത്ഥിക്കുകയും ചെയ്യട്ടെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 263, 263, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ بَيْنَ ظَهْرَانِيِ النَّاسِ، قَالَ: فَجَلَسْتُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مَنَعَكَ أَنْ تَرْكَعَ رَكْعَتَيْنِ قَبْلَ أَنْ تَجْلِسَ". قَالَ: فَقُلْتُ: يَا رَسُولَ اللهِ، رَأَيْتُكَ جَالِسًا وَالنَّاسُ جُلُوسٌ، قَالَ: "فَإِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلَا يَجْلِسْ حَتَّى يَرْكَعَ رَكْعَتَيْنِ". (ق,ت)', 'അബൂഖതാദ(റ): നബി(സ) ജനമദ്ധ്യത്തിൽ ഇരിക്കുമ്പോൾ ഞാൻ പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "ഇരിക്കുന്നതിനു മുമ്പ് രണ്ടു റക്അത്ത് നിസ്കരിക്കുന്നതിൽ നിന്നും നിന്നെ തടഞ്ഞതെന്താണ്?" അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങും ജനങ്ങളും ഇരിക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പ്രവേശിച്ചാൽ അവൻ രണ്ടു റക്അത്ത് നിസ്കരിക്കുന്നതിനു മുമ്പ് ഇരിക്കരുത്." (ബു,മു,തു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 263, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا جَاءَ أَحَدُكُمُ الْمَسْجِدَ فَلْيُصَلِّ سَجْدَتَيْنِ مِنْ قَبْلِ أَنْ يَجْلِسَ". وَفِي رِوَايَةٍ: "ثُمَّ لِيَقْعُدْ بَعْدُ إِنْ شَاءَ أَوْ لِيَذْهَبْ لِحَاجَتِهِ". (ق,ت,ن,جه)', 'അബൂഖതാദ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പ്രവേശിച്ചാൽ അവൻ ഇരിക്കുന്നതിനു മുമ്പ് രണ്ടു റക്അത്ത് നിസ്കരിക്കട്ടെ." മറ്റൊരു റിപ്പോർട്ടിൽ: "അതിനു ശേഷം അവൻ ഇരിക്കുകയോ, അവന്റെ ആവശ്യം നിർവ്വഹിക്കാൻ പോവുകയോ ചെയ്യാം." (ബു,മു,തു,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=89), 1, 'وَفِي رِوَايَةٍ: "ثُمَّ لِيَقْعُدْ بَعْدُ إِنْ شَاءَ أَوْ لِيَذْهَبْ لِحَاجَتِهِ". (ق,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "അതിനു ശേഷം അവൻ ഇരിക്കുകയോ, അവന്റെ ആവശ്യം നിർവ്വഹിക്കാൻ പോവുകയോ ചെയ്യാം." (ബു,മു,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خِصَالٌ لَا تَنْبَغِي فِي الْمَسْجِدِ: لَا يُتَّخَذُ طَرِيقًا، وَلَا يُشْهَرُ فِيهِ سِلَاحٌ، وَلَا يُنْبَضُ فِيهِ بِقَوْسٍ، وَلَا يُنْشَرُ فِيهِ نَبْلٌ، وَلَا يُمَرُّ فِيهِ بِلَحْمٍ نِيءٍ، وَلَا يُضْرَبُ فِيهِ حَدٌّ، وَلَا يُقْتَصُّ فِيهِ مِنْ أَحَدٍ، وَلَا يُتَّخَذُ سُوقًا". (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ചില കാര്യങ്ങൾ പള്ളിയിൽ അനുയോജ്യമല്ല. പള്ളിയെ വഴിയാക്കരുത്, വാൾ ഉറയിൽ നിന്നും (പള്ളിയിൽ വെച്ച്) ഊരരുത്, പള്ളിയിൽ ആയുധം ഉയർത്തരുത്, പള്ളിയിൽ വെച്ച് അമ്പെയ്യരുത്, കുന്തം അവിടെ വെച്ച് വെളിപ്പെടുത്തരുത്, പാകം ചെയ്യാത്ത മാംസവുമായി അതിലൂടെ പോവരുത്, അവിടെ വെച്ച് ശിക്ഷാ വിധികൾ നടപ്പിലാക്കരുത്, ആരോടും പ്രതികാരം ചെയ്യരുത്, അതിനെ (പള്ളിയെ) ചന്തയാക്കരുത്." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبَيْعِ وَالِابْتِيَاعِ، وَعَنْ تَنَاشُدِ الْأَشْعَارِ، فِي الْمَسَاجِدِ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പള്ളിയിൽ ക്രയവിക്രയം നടത്തുന്നതിനെയും, ഗാനമാലപിക്കുന്നതിനെയും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "جَنِّبُوا مَسَاجِدَكُمْ صِبْيَانَكُمْ، وَمَجَانِينَكُمْ، وَشِرَاءَكُمْ، وَبَيْعَكُمْ، وَخُصُومَاتِكُمْ، وَرَفْعَ أَصْوَاتِكُمْ، وَإِقَامَةَ حُدُودِكُمْ، وَسَلَّ سُيُوفِكُمْ. وَاتَّخِذُوا عَلَى أَبْوَابِهَا الْمَطَاهِرَ، وَجَمِّرُوهَا فِي الْجُمَعِ". (جه)', 'വാസിലത്തുബ്നുൽ അസ്ഖഅ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലെ കുട്ടികളെയും, ഭ്രാന്തന്മാരെയും, നാശകാരികളെയും, നിങ്ങളുടെ ക്രയവിക്രയങ്ങളെയും, തർക്ക വിതർക്കങ്ങളെയും, ശബ്ദമുയർത്തലിനെയും, ശിക്ഷാ വിധികൾ നടപ്പിലാക്കുന്നതിനെയും, വാളുകൾ ഊരുന്നതിനെയും നിങ്ങൾ പള്ളികളിൽ നിന്നും വിദൂരത്താക്കുക. അവയുടെ കവാടങ്ങൾക്കരികിൽ ശുദ്ധി വരുത്തുവാനുള്ള സ്ഥാനങ്ങൾ ഉണ്ടാക്കുകയും ആളുകൾ ഒരുമിച്ചു കൂടുന്ന വേളകളിൽ അവയെ സുഗന്ധ പൂരിതമാക്കുകയും ചെയ്യുക" (ജ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ', 'വാസിലത്തുബ്നുൽ അസ്ഖഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 264, 264, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ طَلْقِ بْنِ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا وَفْدًا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَايَعْنَاهُ وَصَلَّيْنَا مَعَهُ، وَأَخْبَرْنَاهُ أَنَّ بِأَرْضِنَا بِيعَةً لَنَا، فَاسْتَوْهَبْنَاهُ مِنْ فَضْلِ طَهُورِهِ فَدَعَا بِمَاءٍ، فَتَوَضَّأَ وَتَمَضْمَضَ، ثُمَّ صَبَّهُ فِي إِدَاوَةٍ، وَأَمَرَنَا فَقَالَ: "اخْرُجُوا، فَإِذَا أَتَيْتُمْ أَرْضَكُمْ فَاكْسِرُوا بِيعَتَكُمْ، وَانْضَحُوا مَكَانَهَا بِهَذَا الْمَاءِ، وَاتَّخِذُوهَا مَسْجِدًا". قُلْنَا: إِنَّ الْبَلَدَ بَعِيدٌ، وَالْحَرَّ شَدِيدٌ، وَالْمَاءَ يَنْشُفُ. فَقَالَ: "مُدُّوهُ مِنَ الْمَاءِ، فَإِنَّهُ لَا يَزِيدُهُ إِلَّا طِيبًا". فَخَرَجْنَا حَتَّى قَدِمْنَا بَلَدَنَا، فَكَسَرْنَا بِيعَتَنَا، ثُمَّ نَضَحْنَا مَكَانَهَا، وَاتَّخَذْنَاهَا مَسْجِدًا، فَنَادَيْنَا فِيهِ بِالْأَذَانِ، قَالَ: وَالرَّاهِبُ رَجُلٌ مِنْ طَيِّئٍ، فَلَمَّا سَمِعَ الْأَذَانَ قَالَ: دَعْوَةُ حَقٍّ. ثُمَّ اسْتَقْبَلَ تَلْعَةً مِنْ تِلَاعِنَا، فَلَمْ نَرَهُ بَعْدُ. (ن)', 'ത്വൽഖുബ്നു അലിയ്യ്(റ): ഞങ്ങൾ (നിവേദക) സംഘമായി നബി(സ)യുടെ അടുത്തേക്ക് പോവുകയും, (ഇസ്‌ലാം കൊണ്ട്) നബി(സ)യോട് ബൈഅത്ത് ചെയ്യുകയും, അവിടുത്തോടൊപ്പം നിസ്കരിക്കുകയും ചെയ്തു. പിന്നീട് നമ്മുടെ നാട്ടിലുള്ള (ക്രിസ്ത്യൻ) പള്ളികളെക്കുറിച്ച് ഞങ്ങൾ അറിയിക്കുകയും, പ്രവാചകൻ(സ) വുദു ചെയ്തതിന്റെ മിച്ചമുള്ള വെള്ളം ദാനം തരുവാൻ ഞങ്ങൾ ആവശ്യപ്പെടുകയും ചെയ്തു. തുടർന്ന് പ്രവാചകൻ(സ) വെള്ളം ആവശ്യപ്പെടുകയും, വുദു ചെയ്യുകയും, വായ കഴുകുകയും ഒരു തോൽപ്പാത്രത്തിൽ വെള്ളമൊഴിക്കുകയും ചെയ്ത ശേഷം ഞങ്ങളോട് കൽപിച്ചുകൊണ്ട് ഇങ്ങനെ പറഞ്ഞു: "നിങ്ങൾ പുറപ്പെടുക, നിങ്ങളുടെ നാട്ടിൽ ചെന്നാൽ നിങ്ങളുടെ ചർച്ച് പൊളിച്ച്, അതിന്റെ സ്ഥാനത്ത് ഈ വെള്ളമൊഴിച്ച് അവിടെ പള്ളി പണിയുക." ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങളുടെ സ്ഥലം വളരെ ദൂരെയുള്ളതും, ചൂട് കഠിനവുമാവുകയും, വെള്ളം വറ്റുകയും ചെയ്യുന്നതുമായ ഒരു പ്രദേശമാണ്. അപ്പോൾ പ്രവാചകൻ പറഞ്ഞു: "നിങ്ങൾ അതിനെ വെള്ളം കൊണ്ട് നീട്ടുക, അത് അതിന് ഗുണം മാത്രമേ വർദ്ധിപ്പിക്കുകയുള്ളൂ." അങ്ങനെ ഞങ്ങൾ പുറപ്പെടുകയും, നാട്ടിലെത്തുകയും, ഞങ്ങളുടെ ചർച്ച് പൊളിച്ച് അവിടെ വെള്ളം തളിക്കുകയും തത്സ്ഥാനത്ത് പള്ളി പണിയുകയും അവിടെ വെച്ച് ബാങ്ക് വിളിക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അവിടുത്തെ പുരോഹിതൻ ''ത്വയ്യ്'' വംശത്തിൽ പെട്ട ഒരാളായിരുന്നു. അയാൾ ബാങ്കുവിളി കേട്ടപ്പോൾ ''സത്യത്തിന്റെ വിളി'' എന്നുപറഞ്ഞ് ഞങ്ങളുടെ പ്രദേശത്തെ ഒരു ഉയർന്ന സ്ഥലത്തേക്ക് തിരിഞ്ഞു പോവുകയും ചെയ്തു. പിന്നീട് ഞങ്ങൾ അദ്ദേഹത്തെ കണ്ടിട്ടില്ല. (ന)', 'طَلْقِ بْنِ عَلِيٍّ', 'ത്വൽഖുബ്നു അലിയ്യ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 264, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَبْدِ اللهِ ابْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ تَنَاشُدِ الْأَشْعَارِ فِي الْمَسْجِدِ، وَعَنِ الْبَيْعِ وَالِاشْتِرَاءِ فِيهِ، وَأَنْ يَتَحَلَّقَ النَّاسُ يَوْمَ الْجُمُعَةِ قَبْلَ الصَّلَاةِ. (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പള്ളിയിൽ ഗാനാലാപനം നടത്തുന്നതിനെയും, ക്രയവിക്രയം ചെയ്യുന്നതിനെയും, വെള്ളിയാഴ്ച ദിവസം ജുമുഅക്ക് മുമ്പ് പള്ളിയിൽ വട്ടമിട്ട് ഇരിക്കുന്നതിനെയും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (തു)', 'عَبْدِ اللهِ ابْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَمِعَ رَجُلًا يَنْشُدُ ضَالَّةً فِي الْمَسْجِدِ فَلْيَقُلْ: لَا رَدَّهَا اللَّهُ عَلَيْكَ، فَإِنَّ الْمَسَاجِدَ لَمْ تُبْنَ لِهَذَا". (م,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു; "പള്ളിയിൽ നഷ്ടപ്പെട്ട സാധനം അന്വേഷിക്കുന്നവനെക്കുറിച്ച് ഒരാൾ കേട്ടാൽ അവൻ ഇങ്ങനെ പറയട്ടെ: നിന്റെ സാധനം അല്ലാഹു മടക്കിത്തരാതിരിക്കട്ടെ. കാരണം, പള്ളികൾ നിർമ്മിക്കപ്പെട്ടത് ഇതിനു വേണ്ടിയല്ല." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَجُلٌ: مَنْ دَعَا إِلَى الْجَمَلِ الْأَحْمَرِ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا وَجَدْتَهُ، إِنَّمَا بُنِيَتِ الْمَسَاجِدُ لِمَا بُنِيَتْ لَهُ". (م,جه)', 'ബുറൈദ(റ): നബി(സ) നിസ്കരിച്ചു കഴിഞ്ഞപ്പോൾ ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: ആരാണ് എന്റെ ചുവന്ന ഒട്ടകം കണ്ടത്? നബി(സ) പറഞ്ഞു: "നീ അതിനെ കാണാതിരിക്കട്ടെ, പള്ളികൾ നിർമ്മിക്കപ്പെട്ടത് എന്തിനു വേണ്ടിയാണോ അതിനുള്ളത് മാത്രമാണ്." (മു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 265, 265, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ:جَاءَ رَجُلٌ يَنْشُدُ ضَالَّةً فِي الْمَسْجِدِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا وَجَدْتَ". (ن)', 'ജാബിർ(റ): പള്ളിയിൽ വെച്ച് നഷ്ടപ്പെട്ട ഒരു സാധനം അന്വേഷിക്കുന്ന വ്യക്തിയോട് നബി(സ) പറഞ്ഞു: "അത് നിനക്ക് കിട്ടാതിരിക്കട്ടെ." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا أُنْزِلَتِ الْآيَاتُ مِنْ سُورَةِ الْبَقَرَةِ فِي الرِّبَا، خَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَسْجِدِ، فَقَرَأَهُنَّ عَلَى النَّاسِ، ثُمَّ حَرَّمَ تِجَارَةَ الْخَمْرِ. (خ)', 'ആഇശ(റ): സൂറത്തുൽബഖറയിലെ പലിശയുടെ സൂക്തം അവതരിച്ചപ്പോൾ നബി(സ) പള്ളിയിലേക്ക് പോവുകയും അത് ജനങ്ങൾക്ക് ഓതിക്കേൾപ്പിക്കുകയും, തുടർന്ന് കള്ള് വില്പന നിഷിദ്ധമാക്കുകയും ചെയ്തു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَرَّ عُمَرُ بِحَسَّانَ بْنِ ثَابِتٍ وَهُوَ يُنْشِدُ فِي الْمَسْجِدِ، فَلَحَظَ إِلَيْهِ، فَقَالَ: قَدْ أَنْشَدْتُ وَفِيهِ مَنْ هُوَ خَيْرٌ مِنْكَ. ثُمَّ الْتَفَتَ إِلَى أَبِي هُرَيْرَةَ فَقَالَ: أَسَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَجِبْ عَنِّي، اللَّهُمَّ أَيِّدْهُ بِرُوحِ الْقُدُسِ". قَالَ: اللَّهُمَّ نَعَمْ. (ن)', 'സഈദുബ്നു മുസ്വയ്യബ്(റ): ഹസ്സാനുബ്നു സാബിത്(റ) പള്ളിയിൽ ഗാനമാലപിക്കുമ്പോൾ ഉമർ(റ) അദ്ദേഹത്തിനടുത്തുകൂടെ നടന്നുപോയി. അപ്പോൾ ഉമർ(റ) അദ്ദേഹത്തെ (ഗൗരവത്തോടെ) വീക്ഷിച്ചു. ഹസ്സാൻ(റ) പറഞ്ഞു: നിങ്ങളേക്കാൾ ഉത്തമൻ പള്ളിയിലുണ്ടായിരിക്കെ ഞാൻ ഗാനമാലപിച്ചിട്ടുണ്ട്. തുടർന്ന് അബൂഹുറൈറ(റ)ക്കു നേരെ തിരിഞ്ഞ് ചോദിച്ചു: "എനിക്കുവേണ്ടി നീ ഉത്തരം നൽകൂ. അല്ലാഹുവേ, ജിബ്‌രീലിന്റെ തുണ ഇദ്ദേഹത്തിന് നീ നൽകേണമേ." എന്ന് നബി(സ) പറയുന്നത് നീ കേട്ടിട്ടില്ലേ? അബൂഹുറൈറ(റ) പറഞ്ഞു: അതെ. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നു മുസ്വയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ وَعَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَا: لَمَّا نُزِلَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَفِقَ يَطْرَحُ خَمِيصَةً لَهُ عَلَى وَجْهِهِ، فَإِذَا اغْتَمَّ كَشَفَهَا عَنْ وَجْهِهِ، فَقَالَ وَهُوَ كَذَلِكَ: "لَعْنَةُ اللهِ عَلَى الْيَهُودِ وَالنَّصَارَى، اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ". يُحَذِّرُ مِثْلَ مَا صَنَعُوا. (ق)', 'ആഇശ(റ), അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) മരണാസന്നനായപ്പോൾ വരകളുള്ള ഒരു വസ്ത്രം മുഖത്തിട്ടു കൊണ്ടേയിരുന്നു. അസ്വസ്ഥതയുണ്ടാകുമ്പോൾ മുഖത്തു നിന്ന് അത് നീക്കിയിരുന്നു. ആ അവസ്ഥയിൽ അവിടുന്ന് പറഞ്ഞു: "ജൂതന്മാർക്കും ക്രിസ്ത്യാനികൾക്കും അല്ലാഹുവിന്റെ നാശം ഉണ്ടാകട്ടെ, അവർ പ്രവാചകന്മാരുടെ ഖബറിടങ്ങൾ പള്ളികളാക്കിയിരിക്കുന്നു." അവരുടെ ചെയ്തികൾ പോലുള്ളതിൽ നിന്നും പ്രവാചകൻ തന്റെ സമൂഹത്തിന് താക്കീത് നൽകുകയായിരുന്നു. (ബു,മു)', 'عَائِشَةَ وَعَبْدِ اللهِ بْنِ عَبَّاسٍ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 266, 266, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اجْعَلُوا فِي بُيُوتِكُمْ مِنْ صَلَاتِكُمْ، وَلَا تَتَّخِذُوهَا قُبُورًا". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ വീടുകളിൽ വെച്ച് ചില നിസ്കാരങ്ങൾ നിർവ്വഹിക്കുക. അവയെ നിങ്ങൾ ശ്മശാനങ്ങളാക്കരുത്." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ أُمَّ حَبِيبَةَ وَأُمَّ سَلَمَةَ – ذَكَرَتَا كَنِيسَةً رَأَيْنَهَا بِالْحَبَشَةِ – فِيهَا تَصَاوِيرُ – لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أُولَئِكَ إِذَا كَانَ فِيهِمُ الرَّجُلُ الصَّالِحُ فَمَاتَ بَنَوْا عَلَى قَبْرِهِ مَسْجِدًا، وَصَوَّرُوا فِيهِ تِلْكَ الصُّوَرَ، أُولَئِكَ شِرَارُ الْخَلْقِ عِنْدَ اللهِ يَوْمَ الْقِيَامَةِ". (م)', 'ആഇശ(റ): ഉമ്മുഹബീബയും, ഉമ്മുസലമ(റ)യും ഹബ്ശയിൽ (അബ്സീനിയ) വെച്ച് കണ്ട ഒരു ചർച്ചിനെക്കുറിച്ച് പറയുകയായിരുന്നു. ആ ചർച്ചിൽ ധാരാളം ചിത്രങ്ങ(ബിംബങ്ങൾ)ളുണ്ടായിരുന്നു. ആ വിവരം അവർ നബി(സ)യോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം, അക്കൂട്ടർ, അവരിൽ ഒരു നല്ല വ്യക്തി ഉണ്ടാവുകയും അദ്ദേഹം മരണപ്പെടുകയും ചെയ്താൽ അദ്ദേഹത്തിന്റെ ഖബറിന്മേൽ പള്ളി നിർമ്മിക്കുകയും അവിടെ അവരുടെ രൂപങ്ങൾ ഉണ്ടാക്കിവെക്കുകയും ചെയ്യുമായിരുന്നു. അന്ത്യ നാളിൽ അല്ലാഹുവിന്റടുക്കൽ സൃഷ്ടികളിൽ വെച്ചേറ്റവും നീചരാണവർ." (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَائِرَاتِ الْقُبُورِ، وَالْمُتَّخِذِينَ عَلَيْهَا الْمَسَاجِدَ وَالسُّرُجَ. حَسَنٌ. (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഖബർ സന്ദർശിക്കുന്ന സ്ത്രീകളെയും, അതിന്മേൽ വിളക്കുകളും പള്ളികളും നിർമ്മിക്കുന്നവരെയും നബി(സ) ശപിച്ചിരിക്കുന്നു. ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْأَرْضُ كُلُّهَا مَسْجِدٌ إِلَّا الْمَقْبَرَةَ وَالْحَمَّامَ". (د,ت,جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പറഞ്ഞു: "ഭൂമിയിൽ ശവകുടീരങ്ങളും കുളിമുറിയും ഒഴികെയുള്ളതെല്ലാം പള്ളിയാണ്." (ദ,തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا نَنَامُ فِي الْمَسْجِدِ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ،وَنَحْنُ شَبَابٌ. (خ,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് ഞങ്ങളുടെ യൗവ്വനദശയിൽ ഞങ്ങൾ പള്ളിയിൽ ഉറങ്ങാറുണ്ടായിരുന്നു. (ബു,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ت','ن','جه']::text[], array['ബു','തു','ന','ജ']::text[], null, null, 267, 267, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ قَيْسِ بْنِ طِخْفَةَ – وَكَانَ مِنْ أَصْحَابِ الصُّفَّةِ – رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْطَلِقُوا". فَانْطَلَقْنَا إِلَى بَيْتِ عَائِشَةَ، وَأَكَلْنَا وَشَرِبْنَا، فَقَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنْ شِئْتُمْ نِمْتُمْ هَا هُنَا، وَإِنْ شِئْتُمُ انْطَلَقْتُمْ إِلَى الْمَسْجِدِ". قَالَ: فَقُلْنَا: بَلْ نَنْطَلِقُ إِلَى الْمَسْجِدِ. (د,جه)', 'അസ്ഹാബുസ്സുഫ്ഫയിൽപ്പെട്ട ഖൈസുബ്നു ത്വിഖ്ഫ(റ): നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "പോകൂ." അപ്പോൾ ഞങ്ങൾ ആഇശ(റ)യുടെ വീട്ടിലേക്ക് പോയി ആഹാരം കഴിക്കുകയും, വെള്ളം കുടിക്കുകയും ചെയ്തു. തുടർന്ന് നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ ഇവിടെ ഉറങ്ങുക, അല്ലെങ്കിൽ പള്ളിയിലേക്ക് പോവുക." റിപ്പോർട്ടർ പറയുന്നു: അപ്പോൾ ഞങ്ങൾ പ്രതിവചിച്ചു: ഇല്ല, ഞങ്ങൾ പള്ളിയിലേക്ക് പോവുകയാണ്. (ദ,ജ)', 'قَيْسِ بْنِ طِخْفَةَ – وَكَانَ مِنْ أَصْحَابِ الصُّفَّةِ –', 'അസ്ഹാബുസ്സുഫ്ഫയിൽപ്പെട്ട ഖൈസുബ്നു ത്വിഖ്ഫ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 267, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْتَ فَاطِمَةَ، فَلَمْ يَجِدْ عَلِيًّا فِي الْبَيْتِ فَقَالَ: "أَيْنَ ابْنُ عَمِّكِ؟" قَالَتْ:كَانَ بَيْنِي وَبَيْنَهُ شَيْءٌ، فَغَاضَبَنِي، فَخَرَجَ فَلَمْ يَقِلْ عِنْدِي، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِإِنْسَانٍ: "انْظُرْ أَيْنَ هُوَ" فَجَاءَ فَقَالَ: يَا رَسُولَ اللهِ، هُوَ فِي الْمَسْجِدِ رَاقِدٌ.فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ مُضْطَجِعٌ، قَدْ سَقَطَ رِدَاؤُهُ عَنْ شِقِّهِ، وَأَصَابَهُ تُرَابٌ. فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَمْسَحُهُ عَنْهُ، وَيَقُولُ: "قُمْ أَبَا تُرَابٍ، قُمْ أَبَا تُرَابٍ". (خ)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): നബി(സ) ഫാത്വിമ(റ)യുടെ വീട്ടിൽ ചെന്നപ്പോൾ അലി(റ)യെ അവിടെ കണ്ടില്ല. അപ്പോൾ നബി ചോദിച്ചു: "നിന്റെ പിതൃവ്യപുത്രനെവിടെ?" ഫാത്വിമ(റ) പറഞ്ഞു: ഞങ്ങളുടെ ഇടയിൽ ചെറിയ പ്രശ്നമുണ്ടായി. എന്നോടദ്ദേഹം ദേഷ്യപ്പെടുകയും എന്റെ അടുത്ത് ഉറങ്ങാതെ പുറത്തേക്കു പോവുകയും ചെയ്തു. നബി(സ) ഒരാളോട് പറഞ്ഞു: "അവൻ എവിടെയാണെന്ന് നീ നോക്കൂ." അയാൾ തിരിച്ചുവന്ന് നബി(സ)യോട് പറഞ്ഞു: പ്രവാചകരേ, അദ്ദേഹം പള്ളിയിൽ കിടന്നുറങ്ങുന്നുണ്ട്. നബി(സ) അദ്ദേഹത്തിന്റെ (അലി(റ)യുടെ) അടുത്ത് വന്നു. അലി(റ)യുടെ ശരീരത്തിൽ നിന്ന് തട്ടം നിലത്തുവീണ് ദേഹത്ത് മണ്ണു പുരണ്ട് കിടക്കുകയായിരുന്നു. നബി(സ) അദ്ദേഹത്തിന്റെ ശരീരത്തിൽ നിന്ന് മണ്ണ് തട്ടിക്കളഞ്ഞ് പറഞ്ഞു: "അബൂതുറാബ്! എഴുന്നേൽക്കൂ, അബൂതുറാബ്! എഴുന്നേൽക്കൂ." (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدِ بْنِ عَاصِمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسْتَلْقِيًا فِي الْمَسْجِدِ، وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസിം(റ): നബി(സ) ഒരു കാൽ മറ്റേകാലിൽ വെച്ചുകൊണ്ട് പള്ളിയിൽ മലർന്ന് കിടക്കുന്നത് അദ്ദേഹം കണ്ടു. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ زَيْدِ بْنِ عَاصِمٍ', 'അബ്ദുല്ലാഹിബ്നു സൈദുബ്നു ആസിം(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ عَبْدِ اللهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسْتَلْقِيًا فِي الْمَسْجِدِ، وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى. (خ)', 'അബ്ദുള്ളാഹിബ്നുസൈദ്(റ) പറയുന്നു: ഒരു കാൽ മറ്റേ കാലിന്മേൽ വെച്ചുകൊണ്ട് തിരുമേനി പള്ളിയിൽ മലർന്നുകിടക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു)', 'عَبْدِ اللهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ', 'അബ്ദുള്ളാഹിബ്നുസൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اسْتَأْذَنَتِ امْرَأَةُ أَحَدِكُمْ إِلَى الْمَسْجِدِ فَلَا يَمْنَعْهَا". (ق,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരുടെയെങ്കിലും ഭാര്യ പള്ളിയിൽ പോവാൻ അനുവാദം ചോദിച്ചാൽ നിങ്ങൾ അവളെ തടയരുത്." (ബു,മു,ന)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتَأْذَنَكُمْ نِسَاؤُكُمْ بِاللَّيْلِ إِلَى الْمَسْجِدِ فَأْذَنُوا لَهُنَّ". (خ)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി പള്ളിയിൽ പോവാൻ നിങ്ങളുടെ സ്ത്രീകൾ അനുവാദം ചോദിച്ചാൽ അവർക്ക് നിങ്ങൾ അനുവാദം നൽകുക." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 268, 268, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ زَيْنَبَ الثَّقَفِيَّةِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَهِدَتْ إِحْدَاكُنَّ الْمَسْجِدَ فَلَا تَمَسَّ طِيبًا". (م)', 'സൈനബുസ്സഖഫിയ്യ(റ): നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങളിലൊരു സ്ത്രീ പള്ളിയിൽ വരികയാണെങ്കിൽ അവൾ സുഗന്ധം പുശരുത്." (മു)', 'زَيْنَبَ الثَّقَفِيَّةِ', 'സൈനബുസ്സഖഫിയ്യ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عَمْرَةَ [بِنْتِ عَبْدِ الرَّحْمَنِ] رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا سَمِعَتْ عَائِشَةَ– زَوْجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ– تَقُولُ: لَوْ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى مَا أَحْدَثَ النِّسَاءُ لَمَنَعَهُنَّ الْمَسْجِدَ كَمَا مُنِعَتْ نِسَاءُ بَنِي إِسْرَائِيلَ. قَالَ: فَقُلْتُ لِعَمْرَةَ: أَنِسَاءُ بَنِي إِسْرَائِيلَ مُنِعْنَ الْمَسْجِدَ؟ قَالَتْ: نَعَمْ. (م)', 'അംറഃബിൻതു അബ്ദുർറഹ്മാൻ(റ): ആഇശ(റ) പറയുന്നത് ഞാൻ കേട്ടു: സ്ത്രീകൾ പുതുതായി ഉണ്ടാക്കുന്ന കാര്യങ്ങൾ നബി(സ) കണ്ടിരുന്നുവെങ്കിൽ ഇസ്രാഈല്യർ സ്ത്രീകളെ തടഞ്ഞതുപോലെ പള്ളിയിൽ പോകുന്നതിൽ നിന്നും അവരെ തടയുമായിരുന്നു. അംറയോട് ഞാൻ ചോദിച്ചു: ഇസ്രാഈല്യർ തങ്ങളുടെ സ്ത്രീകളെ പള്ളിയിൽ പോകുന്നതിൽ നിന്നും തടഞ്ഞിരുന്നുവോ? അവർ പറഞ്ഞു: അതെ. (മു)', 'عَمْرَةَ [بِنْتِ عَبْدِ الرَّحْمَنِ]', 'അംറഃബിൻതു അബ്ദുർറഹ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], 'بِنْتِ عَبْدِ الرَّحْمَنِ', null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَمْنَعُوا إِمَاءَ اللهِ مَسَاجِدَ اللهِ، وَلَكِنْ لِيَخْرُجْنَ وَهُنَّ تَفِلَاتٌ". (د)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: നിങ്ങൾ അല്ലാഹുവിന്റെ അടിയാത്തികളെ പള്ളിയിൽ നിന്നും വിലക്കരുത്. എന്നാൽ അവർ സുഗന്ധം പൂശാതെ (പള്ളിയിലേക്കു) പുറപ്പെട്ടുകൊള്ളട്ടെ. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَمْنَعُوا إِمَاءَ اللهِ مَسَاجِدَ اللهِ". (ق,د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: നിങ്ങൾ അല്ലാഹുവിന്റെ അടിയത്തികളെ പള്ളിയിൽ നിന്നും തടയരുത് (ബു,മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَمْنَعُوا نِسَاءَكُمُ الْمَسَاجِدَ، وَبُيُوتُهُنَّ خَيْرٌ لَهُنَّ". (د)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: നിങ്ങൾ നിങ്ങളിലെ സത്രീകളെ പള്ളിയിൽ നിന്നും തടയാൻ പാടില്ല. അവർക്ക് വീടാണ് ഉത്തമം (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ائْذَنُوا لِلنِّسَاءِ إِلَى الْمَسَاجِدِ بِاللَّيْلِ". فَقَالَ ابْنٌ لَهُ: وَاللهِ لَا نَأْذَنُ لَهُنَّ فَيَتَّخِذْنَهُ دَغَلًا، وَاللهِ لَا نَأْذَنُ لَهُنَّ. قَالَ: فَسَبَّهُ وَغَضِبَ، وَقَالَ: أَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ائْذَنُوا لَهُنَّ". وَتَقُولُ: لَا نَأْذَنُ لَهُنَّ؟!. (ق,د,ت)', 'അബ്ദുള്ളാഹിബ്നു ഉമർ(റ): പ്രവാചകൻ(സ) അരുളി: ''നിങ്ങൾ നിങ്ങളുടെ സ്ത്രീകളെ രാത്രിയിൽ പള്ളിയിൽ പോകുവാൻ അനുവദിക്കുക'' അപ്പോൾ അദ്ദേഹത്തിന്റെ മകൻ പറഞ്ഞു: അല്ലാഹുവാണെ, ഞങ്ങൾ അനുവാദം നൽകുകയില്ല അതവർ വഞ്ചനാമാർഗ്ഗമാക്കും. അല്ലാഹുവാണെ, ഞങ്ങൾ അനുവാദം നൽകുകയില്ല. ഇബ്നുഉമർ(റ) അദ്ദേഹത്തെ (മകനെ) ശകാരിക്കുകയും അദ്ദേഹത്തോട് ദേഷ്യപ്പെടുകയും ചെയ്തു. എന്നിട്ടു പറഞ്ഞു: ''അവർക്ക് അനുവാദം നൽകുക'' എന്ന് തിരുദൂതർ(സ) പറഞ്ഞിട്ടുണ്ടെന്ന് ഞാൻ പറയുന്നു. എന്നിട്ടും ''ഞങ്ങൾ അവരെ അനുവദിക്കുകയില്ല'' എന്ന് നീ പറയുകയോ!!. (ബു,മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുള്ളാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 269, 269, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "صَلَاةُ الْمَرْأَةِ فِي بَيْتِهَا أَفْضَلُ مِنْ صَلَاتِهَا فِي حُجْرَتِهَا، وَصَلَاتُهَا فِي مَخْدَعِهَا أَفْضَلُ مِنْ صَلَاتِهَا فِي بَيْتِهَا". (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ഒരു സ്ത്രീക്ക് അവളുടെ റൂമിൽ വെച്ചു നിസ്കരിക്കുന്നതിനേക്കാൾ ഉത്തമമായത് അവളുടെ വീട്ടിൽ വെച്ചു നിസ്കാരമാകുന്നു. അവളുടെ വീട്ടിൽ വെച്ചുള്ള നിസ്കാരത്തേക്കാൾ അവൾക്കുത്തമം അവളുടെ രഹസ്യമുറിയിൽ വെച്ചുള്ള നിസ്കാരമാണ്. (ദ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَرَكْنَا هَذَا الْبَابَ لِلنِّسَاءِ". قَالَ نَافِعٌ: فَلَمْ يَدْخُلْ مِنْهُ ابْنُ عُمَرَ حَتَّى مَاتَ. وَفِي رِوَايَةٍ: أَنَّ الْقَائِلَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ. قَالَ أَبُو دَاوُدَ وَهَذَا أَصَحُّ. (د)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ''ഈ വാതിൽ സ്ത്രീകൾക്കുവേണ്ടി നീക്കിവെക്കുകയാണെങ്കിൽ (നന്നായിരുന്നു)''. നാഫിഅ് പറയുന്നു: ഇബ്നുഉമർ(റ) പിന്നീടൊരിക്കലും ആ വാതിലിലൂടെ പ്രവേശിക്കുകയുണ്ടായിട്ടില്ല. മറ്റുരു റിപ്പോർട്ടിൽ വന്നതനുസരിച്ച് ഇതു പറഞ്ഞിട്ടുള്ളത് ഉമർ(റ) ആണ്. അബൂദാവൂദ് പറയുന്നു: ഇതാണ് കൂടുതൽ ശരിയായത്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=119), 1, 'وَفِي رِوَايَةٍ: أَنَّ الْقَائِلَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ. قَالَ أَبُو دَاوُدَ وَهَذَا أَصَحُّ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ:قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ تَرَكْنَا هَذَا الْبَابَ لِلنِّسَاءِ". قَالَ نَافِعٌ: فَلَمْ يَدْخُلْ مِنْهُ ابْنُ عُمَرَ حَتَّى مَاتَ. وَفِي رِوَايَةٍ قَالَ: قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: وَهُوَ أَصَحُّ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഈ വാതിൽ നാം സ്ത്രീകൾക്കായി ഒഴിച്ചിട്ടിരുന്നുവെങ്കിൽ (നന്നായിരുന്നു)." നാഫിഅ് പറയുന്നു: മരണം വരെ ഇബ്നുഉമർ ആ വാതിലിലൂടെ പ്രവേശിച്ചിട്ടില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: ഇത് ഏറ്റവും ശരിയായ നടപടിയാണെന്ന് ഉമറുബ്നു ഖത്വാബ്(റ) പറഞ്ഞു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=120), 1, 'وَفِي رِوَايَةٍ قَالَ: قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: وَهُوَ أَصَحُّ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഇത് ഏറ്റവും ശരിയായ നടപടിയാണെന്ന് ഉമറുബ്നു ഖത്വാബ്(റ) പറഞ്ഞു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ – قَالَ أَوَّلَ يَوْمٍ: الثُّومِ، ثُمَّ قَالَ – الثُّومِ وَالْبَصَلِ وَالْكُرَّاثِ، فَلَا يَقْرَبْنَا فِي مَسَاجِدِنَا، فَإِنَّ الْمَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ الْإِنْسُ". (ت,ن)', 'ജാബിർ(റ): ആദ്യ ദിവസം വെളുത്തുള്ളിയെക്കുറിച്ചും, പിന്നെ വെളുത്തുള്ളി, ഉള്ളി, ദുർഗ്ഗന്ധമുള്ള ഒരിനം പച്ചക്കറി (കുർറാസ്) എന്നിവയെയും സൂചിപ്പിച്ചുകൊണ്ട് നബി(സ) പറഞ്ഞു: "ഇവ തിന്നുകൊണ്ട് ആരും നമ്മുടെ പള്ളികളെ സമീപിക്കരുത്, കാരണം മനുഷ്യന് പ്രയാസമുണ്ടാക്കുന്ന കാര്യം മലക്കുകളെയും പ്രയാസത്തിലാക്കും." (തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي غَزْوَةِ خَيْبَرَ: "مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ – يَعْنِي الثُّومَ – فَلَا يَأْتِيَنَّ الْمَسَاجِدَ". (م)', 'ഇബ്നുഉമർ(റ): ഖൈബർ യുദ്ധവേളയിൽ നബി(സ) പറഞ്ഞു: "വെളുത്തുള്ളിയുടെ ചെടിയിൽ നിന്നും വല്ലതും ഭക്ഷിച്ചന്നവൻ ( അതിന്റെ ഗന്ധം മാറുന്നതുവരെ) പള്ളികളിൽ വരരുത്." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 270, 270, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ ثُومًا أَوْ بَصَلًا فَلْيَعْتَزِلْنَا، أَوْ: لِيَعْتَزِلْ مَسْجِدَنَا، وَلْيَقْعُدْ فِي بَيْتِهِ". وَإِنَّهُ أُتِيَ بِقِدْرٍ فِيهِ خَضِرَاتٌ مِنْ بُقُولٍ، فَوَجَدَ لَهَا رِيحًا، فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنَ الْبُقُولِ، فَقَالَ: قَرِّبُوهَا، إِلَى بَعْضِ أَصْحَابِهِ، فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا قَالَ: "كُلْ، فَإِنِّي أُنَاجِي مَنْ لَا تُنَاجِي". (ق)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "വെളുത്തുള്ളിയോ, ഉള്ളിയോ തിന്നവൻ നമ്മിൽ നിന്ന് വിട്ടുനിൽക്കട്ടെ. അല്ലെങ്കിൽ, നമ്മുടെ പള്ളികളിൽ നിന്ന് വിട്ടു നിൽക്കട്ടെ. അവൻ വീട്ടിൽ ഇരിക്കട്ടെ." നബി(സ)യുടെ അടുത്ത് ചീരവർഗ്ഗത്തിൽ പെട്ട പച്ചക്കറികളുള്ള ഒരു കലം കൊണ്ടുവന്നു. അതിനൊരു ഗന്ധമുണ്ടായിരുന്നു. പച്ചക്കറിയെപ്പറ്റി നബി(സ) ചോദിച്ചപ്പോൾ അത് ചീര വർഗ്ഗത്തിൽപ്പെട്ടവയാണെന്ന് (കൊണ്ടുവന്നയാൾ) അറിയിച്ചു. അപ്പോൾ അത് കൊണ്ടുവന്ന് ചില സ്വഹാബികൾക്ക് നൽകാൻ പറഞ്ഞു. നബി(സ) അതു തിന്നാൻ ഇഷ്ടപ്പെട്ടില്ല. നബി(സ) പറഞ്ഞു: "തിന്നുകൊള്ളുക. കാരണം, നിങ്ങൾ അഭിമുഖം നടത്താത്തവരോടാണ് ഞാൻ അഭിമുഖ സംസാരം നടത്തുന്നത്." (ബു,മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 271, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ – يُرِيدُ الثُّومَ – فَلَا يَغْشَانَا فِي مَسَاجِدِنَا". قُلْتُ: مَا يَعْنِي بِهِ؟ قَالَ: مَا أُرَاهُ يَعْنِي إِلَّا نِيئَهُ، وَقِيلَ: إِلَّا نَتْنَهُ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) വെളുത്തുള്ളിയെ ഉദ്ദേശിച്ചു ഇപ്രകാരം പറഞ്ഞു: "ആരെങ്കിലും ഈ ചെടിയിൽനിന്ന് തിന്നാൽ അവൻ നമ്മുടെ പള്ളികളിൽ വരരുത്." റിപ്പോർട്ടർ പറഞ്ഞു: നബി(സ) എന്താണിതു കൊണ്ടുദ്ദേശിച്ചതെന്നു ഞാൻ ജാബിറി(റ)നോട് ചോദിച്ചു: അദ്ദേഹം പറഞ്ഞു: പച്ച ഉള്ളി തിന്നുന്നതാണ് നബി(സ) ഇതു കൊണ്ടുദ്ദേശിച്ചത്. അതിന്റെ ദുർഗന്ധത്തെയാണ് നബി(സ) ഉദ്ദേശിച്ചതെന്നും അഭിപ്രായമുണ്ട്. (ബു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 271, 271, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ مَعْدَانَ ابْنِ أَبِي طَلْحَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ خَطَبَ يَوْمَ الْجُمُعَةِ فَذَكَرَ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَكَرَ أَبَا بَكْرٍ، قَالَ: إِنِّي رَأَيْتُ كَأَنَّ دِيكًا نَقَرَنِي ثَلَاثَ نَقَرَاتٍ، وَإِنِّي لَا أُرَاهُ إِلَّا حُضُورَ أَجَلِي، وَإِنَّ أَقْوَامًا يَأْمُرُونَنِي أَنْ أَسْتَخْلِفَ، وَإِنَّ اللَّهَ لَمْ يَكُنْ لِيُضَيِّعَ دِينَهُ وَلَا خِلَافَتَهُ، وَلَا الَّذِي بَعَثَ بِهِ نَبِيَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِنْ عَجِلَ بِي أَمْرٌ فَالْخِلَافَةُ شُورَى بَيْنَ هَؤُلَاءِ السِّتَّةِ الَّذِينَ تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَنْهُمْ رَاضٍ، وَإِنِّي قَدْ عَلِمْتُ أَنَّ أَقْوَامًا يَطْعَنُونَ فِي هَذَا الْأَمْرِ، أَنَا ضَرَبْتُهُمْ بِيَدِي هَذِهِ عَلَى الْإِسْلَامِ، فَإِنْ فَعَلُوا ذَلِكَ فَأُولَئِكَ أَعْدَاءُ اللَّهِ الْكَفَرَةُ الضُّلَّالُ، ثُمَّ إِنِّي لَا أَدَعُ بَعْدِي شَيْئًا أَهَمَّ عِنْدِي مِنَ الْكَلَالَةِ، مَا رَاجَعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي شَيْءٍ مَا رَاجَعْتُهُ فِي الْكَلَالَةِ، وَمَا أَغْلَظَ لِي فِي شَيْءٍ مَا أَغْلَظَ لِي فِيهِ، حَتَّى طَعَنَ بِإِصْبَعِهِ فِي صَدْرِي، فَقَالَ: "يَا عُمَرُ، أَلَا تَكْفِيكَ آيَةُ الصَّيْفِ الَّتِي فِي آخِرِ سُورَةِ النِّسَاءِ". وَإِنِّي إِنْ أَعِشْ أَقْضِ فِيهَا بِقَضِيَّةٍ يَقْضِي بِهَا مَنْ يَقْرَأُ الْقُرْآنَ وَمَنْ لَا يَقْرَأُ الْقُرْآنَ، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أُشْهِدُكَ عَلَى أُمَرَاءِ الْأَمْصَارِ، وَإِنِّي إِنَّمَا بَعَثْتُهُمْ عَلَيْهِمْ لِيَعْدِلُوا عَلَيْهِمْ، وَلِيُعَلِّمُوا النَّاسَ دِينَهُمْ،وَسُنَّةَ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَيَقْسِمُوا فِيهِمْ فَيْئَهُمْ، وَيَرْفَعُوا إِلَيَّ مَا أَشْكَلَ عَلَيْهِمْ مِنْ أَمْرِهِمْ، ثُمَّ إِنَّكُمْ أَيُّهَا النَّاسُ تَأْكُلُونَ شَجَرَتَيْنِ، لَا أَرَاهُمَا إِلَّا خَبِيثَتَيْنِ، هَذَا الْبَصَلَ وَالثُّومَ، لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا وَجَدَ رِيحَهُمَا مِنَ الرَّجُلِ فِي الْمَسْجِدِ أَمَرَ بِهِ فَأُخْرِجَ إِلَى الْبَقِيعِ، فَمَنْ أَكَلَهُمَا فَلْيُمِتْهُمَا طَبْخًا. (م,ن)', 'മഅ്ദാനുബ്നു അബീത്വൽഹ(റ): ഉമർ(റ) വെള്ളിയാഴ്ച ദിവസം പ്രസംഗിക്കുന്നതിനിടെ. നബി(സ)യെയും അബൂബക്കറി(റ)നെയും പരാമർശിച്ചുകൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: ഒരു പൂവൻകോഴി എന്നെ മൂന്നു പ്രാവശ്യം കൊത്തിയതായി ഞാൻ സ്വപ്നംകണ്ടു. എന്റെ (മരണ) സമയം ആസന്നമായെന്നാണ് ഇതിന്റെ വിവക്ഷ എന്നു ഞാൻ അഭിപ്രായപ്പെടുന്നു. ചില ആളുകൾ എന്നോട് ഖലീഫയെ നിയമിക്കാൻ ആവശ്യപ്പെടുന്നു. അല്ലാഹു അവന്റെ മതത്തെയും, ഖിലാഫത്തിനെയും ഒരിക്കലും നഷ്ടപ്പെടുത്തുകയില്ല. ഞാൻ പെട്ടെന്ന് മരിക്കുകയാണെങ്കിൽ, നബി(സ) വഫാത്താകുമ്പോൾ പ്രവാചകതൃപ്തി നേടിയ ഈ ആറു വ്യക്തികൾക്കിടയിൽ നിന്ന് ഖലീഫയെ ചർച്ചയിലൂടെ തെരഞ്ഞെടുക്കണം. ഇക്കാര്യത്തിൽ ചില വ്യക്തികൾ ആക്ഷേപിക്കുന്നുണ്ടെന്ന കാര്യം എനിക്കറിയാം. ഇസ്ലാമിന്റെ പേരിൽ അവരെ ഞാൻ ഈ കൈ കൊണ്ട് അടിക്കും. അങ്ങനെ അവർ ചെയ്താൽ അവർ വഴിപിഴച്ച നന്ദി കെട്ടവരും, അല്ലാഹുവിന്റെ ശത്രുക്കളുമാണ്. പിന്നെ കലാലഃ (മാതാപിതാക്കളോ സന്താനങ്ങളോ ഇല്ലാത്ത മയ്യിത്ത്)പോലെ പ്രാധാന്യമുള്ളതൊന്നും എനിക്കുശേഷം ഞാൻ ഒഴിവാക്കിയിട്ടില്ല. കലാലഃയുടെ കാര്യത്തിൽ ആവർത്തിച്ചു ചോദിച്ചപോലെ മറ്റൊരു കാര്യത്തിലും ഞാൻ പ്രവാചകനോട് ചോദിച്ചിട്ടില്ല. നബി(സ) അക്കാര്യത്തിൽ കർക്കശമാക്കിതുപോലെ മറ്റൊന്നിലും കർക്കശമാക്കിയിട്ടില്ല. അങ്ങനെ (ചോദിച്ചപ്പോൾ) തന്റെ വിരൽ കൊണ്ട് എന്റെ നെഞ്ചിൽ കുത്തിയിട്ട് റസൂൽ(സ) പറഞ്ഞു: "ഉമറേ, സൂറത്തുന്നിസാഇലെ അവസാന സൂക്തമായ ആയത്തുസ്സൈഫ്³ നിനക്ക് (ഇവ്വിഷയകമായി) വിധിതേടാൻ മതിയായതല്ലെ?" ഇനി ഞാൻ ജീവിക്കുകയാണെങ്കിൽ കലാലത്തിന്റെ വിഷയത്തിൽ ഖുർആൻ പാരായണം ചെയ്യുന്നവരും പാരായണം ചെയ്യാത്തവരും വിധിക്കുന്ന വിധി ഞാൻ നടപ്പാക്കും. പിന്നെ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവെ, പട്ടണങ്ങളുടെ ഭരണാധികാരികളുടെ കാര്യത്തിൽ നിന്നെ ഞാൻ സാക്ഷിയാക്കുന്നു. ഞാനവരെ ജനങ്ങൾക്കുവേണ്ടി നിയോഗിച്ചത് അവർക്ക് നീതി നടപ്പാക്കാനും, ജനങ്ങൾക്ക് മതം പഠിപ്പിക്കാനും, പ്രവാചകചര്യ പഠിപ്പിക്കാനും, (യുദ്ധം കൂടാതെ കിട്ടുന്ന) ശത്രുക്കളുടെ ധനം അവർക്ക് വീതിച്ചു കൊടുക്കാനും, അവർക്ക് സംശയുള്ള കാര്യങ്ങൾ എന്നെ അറിയിക്കാനുമാണ്. ജനങ്ങളേ, നിങ്ങൾ രണ്ടു സസ്യങ്ങൾ തിന്നുന്നു, അവരണ്ടും മോശമാണെന്നാണ് എന്റെ അഭിപ്രായം. ഉള്ളിയും വെളുത്തുള്ളിയുമാണവ. നബി(സ) ആരിലെങ്കിലും ഈ വാസനയുണ്ടെന്നറിഞ്ഞാൽ അവനെ പള്ളിയിൽനിന്ന് ബഖീഇലേക്ക് പറഞ്ഞയക്കാറുണ്ടായിരുന്നു. ആരെങ്കിലും തിന്നുകയാണെങ്കിൽ അതിനെ വേവിച്ച് കഴിക്കട്ടെ. (മു,ന)', 'مَعْدَانَ ابْنِ أَبِي طَلْحَةَ', 'മഅ്ദാനുബ്നു അബീത്വൽഹ(റ)', '³. ആയത്തുസ്സൈഫ് എന്നും ആയത്തുൽകലാല എന്നും ഈ സൂക്തം അറിയപ്പെടുന്നു. കലാലയെ സംബന്ധിച്ചു പ്രതിപാദിച്ച സൂറത്തുന്നിസാഇലെ അവസാന സൂക്തമാണിത്.', null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 271, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: بَيْنَا نَحْنُ جُلُوسٌ فِي الْمَسْجِدِ إِذْ خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَحْمِلُ أُمَامَةَ بِنْتَ أَبِي الْعَاصِ بْنِ الرَّبِيعِ،وَأُمُّهَا زَيْنَبُ بِنْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ،وَهِيَ صَبِيَّةٌ يَحْمِلُهَا، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ عَلَى عَاتِقِهِ، يَضَعُهَا إِذَا رَكَعَ وَيُعِيدُهَا إِذَا قَامَ، حَتَّى قَضَى صَلَاتَهُ يَفْعَلُ ذَلِكَ بِهَا.(د,ن)', 'അബൂഖതാദ(റ): ഞങ്ങൾ പള്ളിയിലിരിക്കുമ്പോൾ നബി(സ) തന്റെ പുത്രി സൈനബിന്റെ മകളായ ഉമാമയെയുമായി വന്നു. അവൾ കുട്ടിയായിരുന്നു. ഉമാമ തോളിലിരിക്കെ നബി(സ) നിസ്കരിച്ചു. റുകൂഅ് ചെയ്യുമ്പോൾ അവളെ താഴെ വെക്കുകയും, എഴുന്നേറ്റാൽ വീണ്ടും എടുത്തു വെക്കുകയും ചെയ്യും. ഇങ്ങനെ ചെയ്തു കൊണ്ട് നബി(സ) നിസ്കാരം പൂർത്തിയാക്കി. (ദ,ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 272, 272, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى قَبْرٍ مَنْبُوذٍ فَأَمَّهُمْ وَصَفُّوا عَلَيْهِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മറവുചെയ്യപ്പെട്ട ഒരു ഖബ്റിന്നടുത്തു നബി(സ) ചെന്നു. സ്വഹാബികൾക്ക് ഇമാമായി നിസ്കരിക്കുകയും അവർ അണിയായി നിൽക്കുകയും ചെയ്തു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 272, 273, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا وَقَدْ قَالَ لَهُ رَجُلٌ: شَهِدْتَ الْخُرُوجَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، وَلَوْلَا مَكَانِي مِنْهُ مَا شَهِدْتُهُ – يَعْنِي مِنْ صِغَرِهِ – أَتَى الْعَلَمَ الَّذِي عِنْدَ دَارِ كَثِيرِ بْنِ الصَّلْتِ، ثُمَّ خَطَبَ، ثُمَّ أَتَى النِّسَاءَ، فَوَعَظَهُنَّ وَذَكَّرَهُنَّ وَأَمَرَهُنَّ أَنْ يَتَصَدَّقْنَ، فَجَعَلَتِ الْمَرْأَةُ تَهْوِي بِيَدِهَا إِلَى حَلْقِهَا تُلْقِي فِي ثَوْبِ بِلَالٍ، ثُمَّ أَتَى هُوَ وَبِلَالٌ الْبَيْتَ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ അദ്ദേഹത്തോടു ചോദിച്ചു: താങ്കൾ നബി(സ)യോടൊപ്പം ഏതെങ്കിലും യുദ്ധത്തിൽ പങ്കെടുത്തിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതെ, നബി (സ)യുടെ അടുക്കൽ എനിക്കു സ്ഥാനമില്ലായിരുന്നുവെങ്കിൽ എന്റെ ചെറുപ്പംകാരണം എനിക്ക് യുദ്ധത്തിൽ പങ്കെടുക്കാൻ കഴിയുമായിരുന്നില്ല. കഥീറുബ്നു സ്വൽതിന്റെ വീടിനടുത്തുള്ള പതാകയുടെ അടുത്തുചെന്ന് നബി(സ) പ്രസംഗിക്കുകയും, ശേഷം സ്ത്രീകളുടെ അടുത്തുചെന്ന് ഉപദേശിക്കുകയും അവരെ ഓർമ്മപ്പെടുത്തുകയും, ദാനധർമ്മങ്ങൾ ചെയ്യാൻ അവരോട് കൽപിക്കുകയും ചെയ്തു. അപ്പോൾ സ്ത്രീകൾ തങ്ങളുടെ കഴുത്തിലെ ആഭരണങ്ങൾ ബിലാലിന്റെ വസ്ത്രത്തിൽ വെക്കാൻതുടങ്ങി. പിന്നീട് നബി(സ)യും ബിലാലും കഅ്ബയിൽ വന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 273, 273, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ الْأَسْوَدِ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ أَنَا وَعَلْقَمَةُ عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، فَقَالَ لَنَا: أَصَلَّى هَؤُلَاءِ؟ قُلْنَا: لَا، قَالَ: قُومُوا فَصَلُّوا. فَذَهَبْنَا لِنَقُومَ خَلْفَهُ،فَجَعَلَ أَحَدَنَا عَنْ يَمِينِهِ، وَالْآخَرَ عَنْ شِمَالِهِ، فَصَلَّى بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ، فَجَعَلَ إِذَا رَكَعَ شَبَّكَ بَيْنَ أَصَابِعِهِ وَجَعَلَهَا بَيْنَ رُكْبَتَيْهِ، وَقَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ. (م,ن)', 'അസ്വദ്(റ): ഞാനും, അൽഖമ(റ)യും അബ്ദുല്ലാഹിബ്നു മസ്ഊദി(റ)ന്റടുക്കൽ കടന്നുചെന്നു. അദ്ദേഹം ഞങ്ങളോട് ചോദിച്ചു: അവർ നിസ്കരിച്ചോ? ഞങ്ങൾ പറഞ്ഞു: ഇല്ല, അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ എഴുന്നേറ്റ് നിസ്കരിക്കുക. ഞങ്ങൾ എഴുന്നേറ്റ് അദ്ദേഹത്തിന്റെ പിന്നിൽ നിന്നു. അദ്ദേഹം ഞങ്ങളിലൊരാളെ തന്റെ വലത്തും, ഒരാളെ ഇടത്തും നിർത്തി. ഞങ്ങൾ ബാങ്കും ഇഖാമത്തും കൂടാതെ നിസ്കരിച്ചു. റുകൂഅ് ചെയ്തപ്പോൾ കൈവിരൽ കോർത്തു പിടിക്കുകയും അവ തന്റെ മുട്ടിന്നിടയിൽ വെക്കുകയും ചെയ്തു. ശേഷം ഇങ്ങനെ പറഞ്ഞു: പ്രവാചകൻ(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (മു,ന)', 'الْأَسْوَدِ', 'അസ്വദ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 273, 273, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمُؤْمِنَ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا". وَشَبَّكَ أَصَابِعَهُ. (خ)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "ഒരു സത്യ വിശ്വാസിക്ക് മറ്റൊരു സത്യവിശ്വാസിയുമായുള്ള ബന്ധത്തിന്റെ കാര്യം ഒരു കെട്ടിടം പോലെയാണ്. അതിൽ ചിലത് മറ്റു ചിലതിനെ ശക്തിപ്പെടുത്തുന്നു." ശേഷം (ഉദാഹരിക്കാൻ വേണ്ടി) നബി(സ) തന്റെ വിരലുകൾ തമ്മിൽ കോർക്കുകയും ചെയ്തു. (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 273, 273, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِحْدَى صَلَاتَيِ الْعَشِيِّ، فَصَلَّى بِنَا رَكْعَتَيْنِ، ثُمَّ سَلَّمَ، فَقَامَ إِلَى خَشَبَةٍ مَعْرُوضَةٍ فِي الْمَسْجِدِ، فَاتَّكَأَ عَلَيْهَا، كَأَنَّهُ غَضْبَانُ وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى، وَشَبَّكَ بَيْنَ أَصَابِعِهِ، وَوَضَعَ خَدَّهُ الْأَيْمَنَ عَلَى ظَهْرِ كَفِّهِ الْيُسْرَى، وَخَرَجَتِ السَّرَعَانُ مِنْ أَبْوَابِ الْمَسْجِدِ، فَقَالُوا: قَصُرَتِ الصَّلَاةُ، وَفِي الْقَوْمِ أَبُو بَكْرٍ وَعُمَرُ فَهَابَا أَنْ يُكَلِّمَاهُ، وَفِي الْقَوْمِ رَجُلٌ فِي يَدَيْهِ طُولٌ يُقَالُ لَهُ –ذُو الْيَدَيْنِ– قَالَ: يَا رَسُولَ اللَّهِ، أَنَسِيتَ، أَمْ قَصُرَتِ الصَّلَاةُ؟ قَالَ: "لَمْ أَنْسَ، وَلَمْ تُقْصَرْ". فَقَالَ: "أَكَمَا يَقُولُ ذُو الْيَدَيْنِ؟". فَقَالُوا: نَعَمْ، فَتَقَدَّمَ فَصَلَّى مَا تَرَكَ، ثُمَّ سَلَّمَ، ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ، ثُمَّ كَبَّرَ وَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ، ثُمَّ سَلَّمَ. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ഞങ്ങളുമായി രാത്രിയിലെ ഒരു നിസ്കാരം രണ്ട് റക്അത്ത് നിർവ്വഹിച്ചു. എന്നിട്ട് സലാംവീട്ടി. ശേഷം ദേഷ്യപ്പെട്ടവനെപ്പോലെ പള്ളിയിലെ മരത്തൂണിലേക്ക്പോയി അതിന്മേൽ ചാരിനിൽക്കുകയും ചെയ്തു. വലതുകൈ ഇടതു കയ്യിന്മേൽ വെച്ച് വിരലുകൾക്കിടയിൽ കോർത്തു. ധൃതിയുള്ളവർ പള്ളി വാതിലിലൂടെ പുറത്തേക്ക്പോയി. അവർ ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു: നിസ്കാരം ചുരുക്കപ്പെട്ടിട്ടുണ്ട്. അവരിൽ അബൂബക്കറും ഉമറും(റ) ഉണ്ടായിരുന്നു. അവർ നബി(സ)യോട് എന്തെങ്കിലും പറയാൻ ഭയന്നു. അക്കൂട്ടത്തിൽ കൈകൾ നീളമുള്ള ''ദുൽയദൈനി'' എന്ന് വിളിക്കപ്പെടുന്ന ഒരാളുണ്ടായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, താങ്കൾ ചുരുക്കിയതാണോ, അതോ മറന്നതാണോ? നബി(സ) പറഞ്ഞു: "ഞാൻ ചുരുക്കിയിട്ടുമില്ല, മറന്നിട്ടുമില്ല." നബി(സ) ചോദിച്ചു: "ദുൽയദൈനി പറഞ്ഞതു പോലെയാണോ?" അവർ പറഞ്ഞു: അതെ, അപ്പോൾ നബി(സ) മുന്നോട്ട്‌വന്ന് ഉപേക്ഷിച്ചത് നിസ്കരിക്കുകയും സലാം വീട്ടുകയും ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലി ആദ്യത്തെ സുജൂദ്പോലെ അല്ലെങ്കിൽ അതിലും ദീർഘമായ സുജൂദ് ചെയ്യുകയും തല ഉയർത്തി തക്ബീർ ചൊല്ലി. വീണ്ടും തക്ബീർ ചൊല്ലി ആദ്യ സുജൂദ് പോലെ അല്ലെങ്കിൽ അതിലും ദീർഘമായ സുജൂദ് ചെയ്യുകയും, തക്ബീറോടെ തല ഉയർത്തുകയും ശേഷം സലാം വീട്ടുകയും ചെയ്തു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 273, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَخْرَجَ أَذًى مِنَ الْمَسْجِدِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ". (جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "പള്ളിയിൽ നിന്നും ഉപദ്രവം (മാലിന്യം) നീക്കിക്കളയുന്നവന് സ്വർഗ്ഗത്തിൽ ഒരു ഭവനം നിർമ്മിച്ചുകൊടുക്കുന്നതാണ്." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 274, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِالْمَسَاجِدِ أَنْ تُبْنَى فِي الدُّورِ، وَأَنْ تُطَهَّرَ وَتُطَيَّبَ. وَفِي رِوَايَةٍ قَالَتْ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُتَّخَذَ الْمَسَاجِدُ فِي الدُّورِ، وَأَنْ تُطَهَّرَ وَتُطَيَّبَ. (جه)', 'ആഇശ(റ): നബി(സ) വീടുകളിൽ പള്ളികളുണ്ടാക്കുവാനും അവ ശുചീകരിക്കപ്പെടണമെന്നും സുഗന്ധം പൂശപ്പെടണമെന്നും കൽപിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ അവർ പറയുന്നു: നബി(സ) വീടുകളിൽ പള്ളികളുണ്ടാക്കുവാനും അവ ശുചീകരിക്കപ്പെടണമെന്നും സുഗന്ധം പൂശപ്പെടണമെന്നും കൽപിച്ചു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 274, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=133), 1, 'وَفِي رِوَايَةٍ قَالَتْ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُتَّخَذَ الْمَسَاجِدُ فِي الدُّورِ، وَأَنْ تُطَهَّرَ وَتُطَيَّبَ. (جه)', 'മറ്റൊരു നിവേദനിൽ അവർ പറയുന്നു: നബി(സ) വീടുകളിൽ പള്ളികളുണ്ടാക്കുവാനും അവ ശുചീകരിക്കപ്പെടണമെന്നും സുഗന്ധം പൂശപ്പെടണമെന്നും കൽപിച്ചു. (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَوَّلُ مَنْ أَسْرَجَ فِي الْمَسَاجِدِ تَمِيمٌ الدَّارِيُّ. (جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ആദ്യമായി പള്ളിയിൽ വിളക്കു കത്തിച്ചത് തമീമുദ്ദാരി(റ) ആയിരുന്നു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 274, 274, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَيْنَمَا نَحْنُ فِي الْمَسْجِدِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ أَعْرَابِيٌّ، فَقَامَ يَبُولُ فِي الْمَسْجِدِ، فَقَالَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَهْ مَهْ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُزْرِمُوهُ، دَعُوهُ". فَتَرَكُوهُ حَتَّى بَالَ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَعَاهُ فَقَالَ لَهُ: "إِنَّ هَذِهِ الْمَسَاجِدَ لَا تَصْلُحُ لِشَيْءٍ مِنْ هَذَا الْبَوْلِ وَلَا الْقَذَرِ، إِنَّمَا هِيَ لِذِكْرِ اللَّهِ عَزَّ وَجَلَّ، وَالصَّلَاةِ، وَقِرَاءَةِ الْقُرْآنِ". أَوْ كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَأَمَرَ رَجُلًا مِنَ الْقَوْمِ فَجَاءَ بِدَلْوٍ مِنْ مَاءٍ فَشَنَّهُ عَلَيْهِ.(م)', 'അനസുബ്നുമാലിക്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം പള്ളിയിലായിരിക്കെ ഒരു ഗ്രാമീണൻ വന്ന് പള്ളിയിൽ മൂത്രമൊഴിക്കാൻ തുടങ്ങി. അപ്പോൾ പ്രവാചക അനുചരർ ''നിർത്തൂ, നിർത്തൂ'' എന്ന് പറഞ്ഞു. നബി(സ)പറഞ്ഞു: "നിങ്ങൾ അയാളെ ബുദ്ധിമുട്ടിക്കരുത്, അയാളെ വിട്ടേക്കൂ." അപ്പോൾ അവർ അയാളെ മൂത്രമൊഴിക്കാൻ അനുവദിച്ചു. ശേഷം, പ്രവാചകൻ അയാളെ വിളിച്ച് പറഞ്ഞു: "ഈ പള്ളികൾ ഇതുപോലുള്ള മൂത്രം, മറ്റു മ്ലേഛ വസ്തുക്കൾക്കൊന്നും യോജിച്ചതല്ല. ഇത് പ്രപഞ്ചനാഥനായ അല്ലാഹുവിനെ സ്മരിക്കാനും, നിസ്കരിക്കാനും, ഖുർആൻ പാരായണം ചെയ്യാനുമുള്ളതാണ്." നിവേദകൻ പറയുന്നു: നബി(സ) അവരിലൊരാളോട് ഒരു ബക്കറ്റ് വെള്ളം കൊണ്ടുവരാൻ പറയുകയും ആ വെള്ളം അതിന്മേൽ (മൂത്രമൊഴിച്ചിടത്ത്) ഒഴിക്കുകയും ചെയ്തു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 275, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَسْوَدَ أَوْ امْرَأَةً سَوْدَاءَ كَانَ يَقُمُّ الْمَسْجِدَ، فَمَاتَ فَسَأَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْهُ، فَقَالُوا: مَاتَ، قَالَ: "أَفَلَا كُنْتُمْ آذَنْتُمُونِي بِهِ دُلُّونِي عَلَى قَبْرِهِ". أَوْ قَالَ: "قَبْرِهَا" فَأَتَى قَبْرَهَا، فَصَلَّى عَلَيْهَا. (خ)', 'അബൂഹുറൈറ(റ): ഒരു കറുത്ത സ്ത്രീ അല്ലെങ്കിൽ ഒരു പുരുഷൻ മസ്ജിദുന്നബവി അടിച്ചുവാരാറുണ്ടായിരുന്നു. അദ്ദേഹം മരണപ്പെട്ടപ്പോൾ നബി(സ) അയാളെക്കുറിച്ചന്വേഷിച്ചപ്പോൾ അദ്ദേഹം മരണപ്പെട്ടു എന്ന് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കെന്നെ ആ വിവരം അറിയിക്കാമായിരുന്നില്ലേ? ആ (അവളുടെ അല്ലെങ്കിൽ അയാളുടെ) ഖബർ എനിക്ക് കാണിച്ചുതരൂ." അനന്തരം നബി(സ) ആ ഖബറിന്റെ അടുത്ത് ചെന്ന് അവിടെവെച്ച് നിസ്കരിച്ചു. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 275, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عُرِضَتْ عَلَيَّ أُجُورُ أُمَّتِي حَتَّى الْقَذَاةُ، يُخْرِجُهَا الرَّجُلُ مِنَ الْمَسْجِدِ. وَعُرِضَتْ عَلَيَّ ذُنُوبُ أُمَّتِي، فَلَمْ أَرَ ذَنْبًا أَعْظَمَ مِنْ سُورَةٍ مِنَ الْقُرْآنِ – أَوْ آيَةٍ – أُوتِيهَا رَجُلٌ ثُمَّ نَسِيَهَا". (د,ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു:"എന്റെ സമുദായത്തിന്റെ പ്രതിഫലങ്ങൾ എനിക്ക് കാണിക്കപ്പെട്ടു. ഒരാൾ പള്ളിയിൽ നിന്നെടുത്ത് പുറത്തു കളയുന്ന ചെളിവരെ. എന്റെ സമുദായത്തിന്റെ തെറ്റുകൾ എനിക്ക് കാണിക്കപ്പെട്ടു. ഞാൻ അതിൽ വലിയ തെറ്റായിക്കണ്ടത്, ഖുർആൻ -അല്ലെങ്കിൽ അതിലെ ഒരു സൂക്തം - പഠിച്ച ഒരാൾ അത് മറന്നുപോയി എന്നതാണ്." (ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 275, 275, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ، فَحَكَّهَا بِحَصَاةٍ، وَنَهَى أَنْ يَبْصُقَ الرَّجُلُ بَيْنَ يَدَيْهِ أَوْ عَنْ يَمِينِهِ وَقَالَ: "يَبْصُقُ عَنْ يَسَارِهِ، أَوْ تَحْتَ قَدَمِهِ الْيُسْرَى". (ق,ن,جه)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) പള്ളിയുടെ ഖിബ്ലയുടെ ഭാഗത്ത് കഫം കണ്ടു. അപ്പോഴവർ അത് ചരൽകല്ലു കൊണ്ട് ചുരണ്ടിക്കളഞ്ഞു. തുടർന്ന്, ഒരാൾ തന്റെ മുൻവശത്തേക്കോ വലതു വശത്തേക്കോ തുപ്പുന്നത് വിലക്കിക്കൊണ്ട് നബി(സ) പറഞ്ഞു: "ഇടത്തോട്ടോ, ഇടത്തേ കാൽചുവട്ടിലേക്കോ തുപ്പുക." (ബു,മു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 275, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ طَارِقِ بْنِ عَبْدِ اللَّهِ الْمُحَارِبِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا كُنْتَ تُصَلِّي فَلَا تَبْزُقَنَّ بَيْنَ يَدَيْكَ، وَلَا عَنْ يَمِينِكَ، وَابْصُقْ خَلْفَكَ أَوْ تِلْقَاءَ شِمَالِكَ إِنْ كَانَ فَارِغًا، وَإِلَّا فَهَكَذَا". وَبَزَقَ تَحْتَ رِجْلِهِ وَدَلَكَهُ. (د,ن)', 'ത്വാരിഖുബ്നു അബ്ദുല്ല(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ മുന്നോട്ടോ, വലത്തോട്ടോ തുപ്പരുത്. ആരുമില്ലെങ്കിൽ പിന്നോട്ടോ, ഇടത്തോട്ടോ തുപ്പുക. അല്ലെങ്കിൽ ഇപ്രകാരം ചെയ്യുക." ശേഷം നബി(സ) തന്റെ കാൽ ചുവട്ടിലേക്ക് തുപ്പുകയും അത് നിലത്തു വെച്ച് ഉരസുകയും ചെയ്തു. (ദ,ന)', 'طَارِقِ بْنِ عَبْدِ اللَّهِ الْمُحَارِبِيِّ', 'ത്വാരിഖുബ്നു അബ്ദുല്ല(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَنَخَّعَ، فَدَلَكَهُ بِرِجْلِهِ الْيُسْرَى. (م,ن)', 'അബ്ദുല്ലാഹിബ്നു ശ്ശഹീർ(റ): നബി(സ) തുപ്പുകയും, അത് തന്റെ ഇടതുകാൽ കൊണ്ട് ഉരക്കുകയും ചെയ്യുന്നത് ഞാൻ കണ്ടു. (മു,ന)', 'عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നു ശ്ശഹീർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ، فَغَضِبَ حَتَّى احْمَرَّ وَجْهُهُ، فَقَامَتِ امْرَأَةٌ مِنَ الْأَنْصَارِ فَحَكَّتْهَا وَجَعَلَتْ مَكَانَهَا خَلُوقًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَحْسَنَ هَذَا". (ن,جه)', 'അനസുബ്നു മാലിക്(റ): പള്ളിയിൽ ഖിബ്ലയുടെ ഭാഗത്ത് കാർക്കിച്ചു തുപ്പിയതായി നബി(സ) കണ്ടു. നബി(സ)ക്ക് ദേഷ്യം വരികയും, മുഖം ചുവക്കുകയും ചെയ്തു. ഒരു അൻസ്വാരി സ്ത്രീ വന്ന് അത് ചുരണ്ടിക്കളഞ്ഞ് അവിടെ സുഗന്ധം പൂശുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്തുനല്ല കാര്യമാണിത്!." (ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى نُخَامَةً فِي الْقِبْلَةِ، فَشَقَّ ذَلِكَ عَلَيْهِ، حَتَّى رُئِيَ فِي وَجْهِهِ، فَقَامَ فَحَكَّهُ بِيَدِهِ، فَقَالَ: "إِنَّ أَحَدَكُمْ إِذَا قَامَ فِي صَلَاتِهِ، فَإِنَّهُ يُنَاجِي رَبَّهُ، أَوْ إِنَّ رَبَّهُ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ، فَلَا يَبْزُقَنَّ أَحَدُكُمْ قِبَلَ قِبْلَتِهِ، وَلَكِنْ عَنْ يَسَارِهِ، أَوْ تَحْتَ قَدَمَيْهِ". ثُمَّ أَخَذَ طَرَفَ رِدَائِهِ، فَبَصَقَ فِيهِ، ثُمَّ رَدَّ بَعْضَهُ عَلَى بَعْضٍ. فَقَالَ: "أَوْ يَفْعَلُ هَكَذَا". (خ)', 'അനസ്(റ): നബി(സ) പള്ളിയുടെ ഖിബ്ലയിൽ കഫം കണ്ടു. അത് നബി(സ)യെ അസ്വസ്ഥനാക്കുകയും തിരുമേനിയുടെ മുഖത്ത് അത് പ്രകടമാവുകയും ചെയ്തു. തുടർന്ന് അവിടുന്ന് തന്റെ കൈകൊണ്ട് അത് ചുരണ്ടിക്കളഞ്ഞശേഷം പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നിസ്കാരം ആരംഭിച്ചാൽ അവൻ തന്റെ രക്ഷിതാവിനോട് സംഭാഷണം നടത്തുകയാണ്. നിശ്ചയം, അവന്റെ രക്ഷിതാവ് അവന്നും ഖിബ്ലക്കും ഇടയിലാണ്. അതിനാൽ നിങ്ങൾ ഖിബ്ലക്കുനേരെ തുപ്പരുത്, അവൻ തന്റെ ഇടത്തോട്ടോ, കാൽചുവട്ടിലേക്കോ തുപ്പട്ടെ." തുടർന്ന് നബി(സ) തന്റെ തട്ടത്തിന്റെ ഒരുഭാഗം പിടിക്കുകയും, അതിൽ തുപ്പുകയും പിന്നീടത് മടക്കുകയും ചെയ്തശേഷം പറഞ്ഞു: "അല്ലെങ്കിൽ അവൻ ഇപ്രകാരം ചെയ്തുകൊള്ളട്ടെ." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 276, 276, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دَخَلَ هَذَا الْمَسْجِدَ فَبَزَقَ فِيهِ أَوْ تَنَخَّمَ، فَلْيَحْفِرْ فَلْيَدْفِنْهُ، فَإِنْ لَمْ يَفْعَلْ فَلْيَبْزُقْ فِي ثَوْبِهِ، ثُمَّ لِيَخْرُجْ بِهِ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ പള്ളിയിൽ പ്രവേശിക്കുകയും, തുപ്പാനോ കാർക്കിച്ച് തുപ്പാനോ ഉദ്ദേശിക്കുകയും ചെയ്താൽ അവൻ ഒരു കുഴിയെടുക്കുകയും അതിൽ തുപ്പുകയം അത് മൂടുകയും ചെയ്യട്ടെ. അല്ലെങ്കിൽ അവൻ തന്റെ വസ്ത്രത്തിൽ തുപ്പുകയും അതുമായി പുറത്തു പോവുകയും ചെയ്യട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 276, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ جَابِرِ ابْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِنَا هَذَا وَفِي يَدِهِ عُرْجُونُ ابْنِ طَابٍ، فَنَظَرَ فَرَأَى فِي قِبْلَةِ الْمَسْجِدِ نُخَامَةً، فَأَقْبَلَ عَلَيْهَا فَحَتَّهَا بِالْعُرْجُونِ، ثُمَّ قَالَ: "أَيُّكُمْ يُحِبُّ أَنْ يُعْرِضَ اللَّهُ عَنْهُ بِوَجْهِهِ". ثُمَّ قَالَ: "إِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي فَإِنَّ اللَّهَ قِبَلَ وَجْهِهِ، فَلَا يَبْصُقَنَّ قِبَلَ وَجْهِهِ، وَلَا عَنْ يَمِينِهِ، وَلْيَبْزُقْ عَنْ يَسَارِهِ تَحْتَ رِجْلِهِ الْيُسْرَى، فَإِنْ عَجِلَتْ بِهِ بَادِرَةٌ فَلْيَقُلْ بِثَوْبِهِ هَكَذَا". وَوَضَعَهُ عَلَى فِيهِ ثُمَّ دَلَكَهُ، ثُمَّ قَالَ: "أَرُونِي عَبِيرًا". فَقَامَ فَتًى مِنَ الْحَيِّ يَشْتَدُّ إِلَى أَهْلِهِ فَجَاءَ بِخَلُوقٍ فِي رَاحَتِهِ، فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَهُ عَلَى رَأْسِ الْعُرْجُونِ، ثُمَّ لَطَخَ بِهِ عَلَى أَثَرِ النُّخَامَةِ، قَالَ جَابِرٌ: فَمِنْ هُنَاكَ جَعَلْتُمُ الْخَلُوقَ فِي مَسَاجِدِكُمْ. (د)', 'ജാബിർ(റ): ''ഇബ്നുത്വാബി''(ഒരുതരം ഈത്തപ്പന)ന്റെ തണ്ട് കയ്യിൽ പിടിച്ച് നബി(സ) ഞങ്ങളുടെ ഈ പള്ളിയിൽ വരികയും അവിടെ മുഴുവൻ നോക്കുകയും ചെയ്തു. അപ്പോൾ പള്ളിയിൽ കഫം കാണുകയും അത് ആ തണ്ടുപയോഗിച്ച് ചുരണ്ടിക്കളയുകയും ചെയ്തു. തുടർന്ന് പറഞ്ഞു: "അല്ലാഹു തന്റെ മുഖം നിങ്ങളിൽ നിന്ന് തിരിച്ചുകളയുന്നത് ആരാണ് ഇഷ്ടപ്പെടുക?" ശേഷം പറഞ്ഞു: "ഒരാൾ നിസ്കരിക്കുമ്പോൾ അല്ലാഹു അവന്ന് അഭിമുഖമായിട്ടാണുള്ളത്. അതിനാൽ ആരും മുഖത്തിന്റെ ഭാഗത്തേക്കോ വലത്തോട്ടോ തുപ്പരുത്. ഇടത്തേകാൽക്കീഴിൽ ഇടത് ഭാഗത്തേക്ക് തുപ്പുക. ഇനി ധൃതിയുണ്ടെങ്കിൽ അവൻ തന്റെ വസ്ത്രംകൊണ്ട് ഇപ്രകാരം ചെയ്യട്ടെ." നബി(സ) തന്റെ വസ്ത്രം വായിൽ വെക്കുകയും അത് തുടക്കുകയും ചെയ്തു. തുടർന്ന് പറഞ്ഞു: "അബീർ (ഒരു സുഗന്ധം) കൊണ്ടു വരിക." അപ്പോൾ ഹയ്യ് ഗോത്രത്തിൽപ്പെട്ട ഒരു യുവാവ് ധൃതിയിൽ തന്റെ വീട്ടിലേക്കുപോയി ഉള്ളം കയ്യിൽ ''ഹലൂഖ്'' (സുഗന്ധം) പുരട്ടിക്കൊണ്ട് വരികയും നബി(സ) അതുവാങ്ങി തന്റെ കയ്യിലുണ്ടായിരുന്ന തണ്ടിന്റെ അഗ്രത്തിൽ പുരട്ടുകയും കഫത്തിന്റെ അടയാളമുള്ള സ്ഥലത്ത് പുരട്ടുകയും ചെയ്തു. ജാബിർ(റ) പറയുന്നു: അന്നുമുതലാണ് നിങ്ങൾ പള്ളിയിൽ ''ഹലൂഖ്'' ഉപയോഗിക്കാൻ തുടങ്ങിയത്. (ദ)', 'جَابِرِ ابْنِ عَبْدِ اللَّهِ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ عَبْدِاللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَابَقَ بَيْنَ الْخَيْلِ الَّتِي أُضْمِرَتْ مِنَ الْحَفْيَاءِ وَأَمَدُهَا ثَنِيَّةُ الْوَدَاعِ، وَسَابَقَ بَيْنَ الْخَيْلِ الَّتِي لَمْ تُضَمَّرْ مِنَ الثَّنِيَّةِ إِلَى مَسْجِدِ بَنِي زُرَيْقٍ، وَأَنَّ عَبْدَاللَّهِ بْنَ عُمَرَ كَانَ فِيمَنْ سَابَقَ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) ഹഫയാഅ് (ഒരുസ്ഥലം) മുതൽ സനിയ്യതുൽ വദാഅ് വരെ മെലിഞ്ഞ കുതിരകൾക്കിടയിലും സനിയ്യഃ മുതൽ ബനൂസുറൈഖിന്റെ പള്ളി വരെ മെലിയാത്ത കുതിരകൾക്കിടയിൽ പന്തയം നടത്തി. ഇബ്നുഉമർ (റിപ്പോർട്ടർ) മത്സരത്തിൽ പങ്കെടുത്തവരിൽ ഒരാളായിരുന്നു. (ബു)', 'عَبْدِاللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 277, 277, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَالٍ مِنَ الْبَحْرَيْنِ، فَقَالَ: "انْثُرُوهُ فِي الْمَسْجِدِ". وَكَانَ أَكْثَرَ مَالٍ أُتِيَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الصَّلَاةِ، وَلَمْ يَلْتَفِتْ إِلَيْهِ، فَلَمَّا قَضَى الصَّلَاةَ جَاءَ فَجَلَسَ إِلَيْهِ. فَمَا كَانَ يَرَى أَحَدًا إِلَّا أَعْطَاهُ. إِذْ جَاءَهُ الْعَبَّاسُ فَقَالَ: يَا رَسُولَ اللَّهِ،أَعْطِنِي، فَإِنِّي فَادَيْتُ نَفْسِي وَفَادَيْتُ عَقِيلًا، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "خُذْ". فَحَثَا فِي ثَوْبِهِ، ثُمَّ ذَهَبَ يُقِلُّهُ فَلَمْ يَسْتَطِعْ، فَقَالَ: يَا رَسُولَ اللَّهِ، اؤْمُرْ بَعْضَهُمْ يَرْفَعْهُ إِلَيَّ، قَالَ: "لَا" قَالَ: فَارْفَعْهُ أَنْتَ عَلَيَّ، قَالَ: لَا فَنَثَرَ مِنْهُ ثُمَّ ذَهَبَ يُقِلُّهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، اؤْمُرْ بَعْضَهُمْ يَرْفَعْهُ عَلَيَّ، قَالَ: "لَا" قَالَ: فَارْفَعْهُ أَنْتَ عَلَيَّ، قَالَ: لَا فَنَثَرَ مِنْهُ ثُمَّ احْتَمَلَهُ فَأَلْقَاهُ عَلَى كَاهِلِهِ، ثُمَّ انْطَلَقَ، فَمَا زَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُتْبِعُهُ بَصَرَهُ، حَتَّى خَفِيَ عَلَيْنَا عَجَبًا مِنْ حِرْصِهِ، فَمَا قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَثَمَّ مِنْهَا دِرْهَمٌ. (خ)', 'അനസുബ്നു മാലിക്(റ): ബഹ്റൈനിൽ നിന്നുള്ള സമ്പത്ത് നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവരപ്പെട്ടു. നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്ന ഏറ്റവും വലിയ സ്വത്തായിരുന്നു അത്. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അത് പള്ളിയിൽ ചൊരിയുക." അതിലേക്ക് തിരിഞ്ഞു നോക്കുകപോലും ചെയ്യാതെ നബി നിസ്കാരത്തിലേക്ക് പുറപ്പെട്ടു. നിസ്കാരശേഷം വന്ന് അതിന്റെ അടുത്ത് ഇരിക്കുകയും കണ്ടവർക്കൊക്കെ കൊടുക്കുകയും ചെയ്തു. അപ്പോൾ അബ്ബാസ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, താങ്കൾ എനിക്ക് നൽകിയാലും! ഞാൻ എന്നെയും അഖീലിനെയും (അങ്ങയുടെ) യുദ്ധത്തടവിൽ നിന്ന് മോചനദ്രവ്യം നൽകി മോചിപ്പിച്ചിട്ടുണ്ടല്ലേ! നബി(സ) പറഞ്ഞു: "നീ എടുത്തുകൊള്ളുക." അദ്ദേഹം തന്റെ വസ്ത്രത്തിൽ വാരിയിട്ട് പൊക്കിയെടുക്കാൻ ശ്രമിച്ചെങ്കിലും ഭാരംകാരണം പൊക്കിയെടുത്ത് കൊണ്ടുപോവാൻ സാധിച്ചില്ല. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇത് ഉയർത്തിത്തരാൻ വേണ്ടി ആരോടെങ്കിലും കൽപ്പിച്ചാലും! നബി(സ) പറഞ്ഞു: ''സാധ്യമല്ല.'' അദ്ദേഹം പറഞ്ഞു: എങ്കിൽ ഇത് ഉയർത്താൻ അവിടുന്ന് എന്നെ സഹായിച്ചാലും! തിരുമേനി(സ) പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്യുകയില്ല. അദ്ദേഹം അതിൽനിന്നും അല്പം എടുത്തൊഴിവാക്കി അത് ചുമന്ന് കൊണ്ടുപോകാൻ ഒരുമ്പൊട്ടു. ശേഷം അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ! ഇത് ഉയർത്തിതരാൻ വേണ്ടി അങ്ങ് ആരോടെങ്കിലും നിർദ്ദേശിച്ചാലും! തിരുമേനി(സ) പറഞ്ഞു: എനിക്ക് അതിന് പറ്റുകയില്ല. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്നാൽ അങ്ങ് ഇത് ഉയർത്തിത്തരാൻ സഹായിച്ചാലും തിരുമേനി(സ) പറഞ്ഞു: സാധ്യമല്ല. അപ്പോഴദ്ദേഹം അതിൽ നിന്നല്പം കുടയുകയും അതു തന്റെ ചുമലിൽവെച്ച് കൊണ്ടുപോവുകയും ചെയ്തു. ഞങ്ങളിൽ നിന്ന് മറയുന്നതുവരെ അദ്ദേഹത്തിന്റെ അത്യാഗ്രഹത്തിൽ പ്രവാചകൻ അത്ഭുതപ്പെട്ടു കൊണ്ടിരുന്നു. നബി(സ) എഴുന്നേൽക്കുമ്പോൾ ഒരു ദിർഹം പോലും അവിടെ ബാക്കിയുണ്ടായിരുന്നില്ല. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 277, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: مَرَّ رَجُلٌ فِي الْمَسْجِدِ، وَمَعَهُ سِهَامٌ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمْسِكْ بِنِصَالِهَا". (خ,ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): അമ്പുമായി പള്ളിയിലൂടെ നടന്നുനീങ്ങിയ ഒരാളോട് നബി(സ) പറഞ്ഞു: "നീ അതിന്റെ മുന മുറുകെപിടിക്കുക.(സൂക്ഷിക്കുക)" (ബു,ന)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 278, 278, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ مَرَّ فِي شَيْءٍ مِنْ مَسَاجِدِنَا، أَوْ أَسْوَاقِنَا بِنَبْلٍ فَلْيَأْخُذْ عَلَى نِصَالِهَا، لَا يَعْقِرْ بِكَفِّهِ مُسْلِمًا". (خ)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "നമ്മുടെ പള്ളിയിലൂടെയോ, മാർക്കറ്റിലൂടെയോ നടന്നുനീങ്ങുന്നവൻ അതിന്റെ മുനകൾ മുറുകെപ്പിടിച്ചു കൊള്ളട്ടെ. അവന്റെ കൈ കൊണ്ട് ഒരു മുസ്ലിമിനും മുറിവേൽക്കരുത്." (ബു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 278, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا عَلَى بَابِ حُجْرَتِي، وَالْحَبَشَةُ يَلْعَبُونَ فِي الْمَسْجِدِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتُرُنِي بِرِدَائِهِ، أَنْظُرُ إِلَى لَعِبِهِمْ. وَفِي رِوَايَةٍ: يَلْعَبُونَ بِحِرَابِهِمْ. (خ)', 'ആഇശ(റ): ഒരു ദിവസം നബി(സ) എന്റെ മുറിയുടെ വാതിൽക്കൽ നിൽക്കുന്നതു ഞാൻ കണ്ടു. ആ സമയം എത്യോപ്യക്കാർ പള്ളിയിലുണ്ടായിരുന്നു. ഞാൻ അവരുടെ കളി കണ്ടുനിൽക്കുമ്പോൾ നബി(സ) തന്റെ വസ്ത്രം കൊണ്ട് എന്നെ മറക്കുന്നുണ്ടായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: അവർ അവരുടെ ശൂല(ചാട്ടുളി)മേന്തി കൊണ്ട് കളിക്കുകയായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=14 and h.hadith_no=149), 1, 'وَفِي رِوَايَةٍ: يَلْعَبُونَ بِحِرَابِهِمْ. (خ)', 'മറ്റൊരു നിവേദനിൽ: അവർ അവരുടെ ശൂല(ചാട്ടുളി)മേന്തി കൊണ്ട് കളിക്കുകയായിരുന്നു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ تَقَاضَى ابْنَ أَبِي حَدْرَدٍ دَيْنًا كَانَ لَهُ عَلَيْهِ فِي الْمَسْجِدِ، فَارْتَفَعَتْ أَصْوَاتُهُمَا حَتَّى سَمِعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي بَيْتِهِ، فَخَرَجَ إِلَيْهِمَا حَتَّى كَشَفَ سَجْفَ حُجْرَتِهِ، فَنَادَى: "يَا كَعْبُ". قَالَ: لَبَّيْكَ يَا رَسُولَ اللَّهِ، قَالَ: "ضَعْ مِنْ دَيْنِكَ هَذَا". وَأَوْمَأَ إِلَيْهِ أَيِ الشَّطْرَ قَالَ: لَقَدْ فَعَلْتُ يَا رَسُولَ اللَّهِ، قَالَ: "قُمْ فَاقْضِ". (خ)', 'കഅ്ബുബ്നു മാലിക്(റ): അദ്ദേഹം പള്ളിയിൽവെച്ച് അബൂഹദ്റദിനോട് തനിക്ക് കിട്ടാനുള്ള കടം വീട്ടാനാവശ്യപ്പെട്ടു. ഇരുവരുടെയും ശബ്ദമുയർന്നു. വീട്ടിലായിരുന്ന നബി(സ) ഇവരുടെ ശബ്ദംകേട്ടു. റൂമിന്റെ വിരി നീക്കി അവരുടെ അടുത്തേക്കുപോയി. നബി(സ) "കഅ്ബ്!" എന്നു വിളിച്ചു. അദ്ദേഹം വിളികേട്ടു. നബി(സ) കടത്തിൽ നിന്ന് പകുതി പിൻവലിക്കാൻ ആംഗ്യം കാണിച്ചു. അദ്ദേഹം പറഞ്ഞു: നബിയേ, ഞാനങ്ങനെ പിൻവലിച്ചിരിക്കുന്നു. ആ വ്യക്തിയോട് ബാക്കി കടം വീട്ടാൻ നബി(സ) പറഞ്ഞു. (ബു)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ عِفْرِيتًا مِنَ الْجِنِّ تَفَلَّتَ عَلَيَّ الْبَارِحَةَ، أَوْ كَلِمَةً نَحْوَهَا، لِيَقْطَعَ عَلَيَّ الصَّلَاةَ، فَأَمْكَنَنِي اللَّهُ مِنْهُ، فَأَرَدْتُ أَنْ أَرْبِطَهُ إِلَى سَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، حَتَّى تُصْبِحُوا وَتَنْظُرُوا إِلَيْهِ كُلُّكُمْ، فَذَكَرْتُ قَوْلَ أَخِي سُلَيْمَانَ:{رَبِّ هَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي}. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: " ജിന്നുകളിൽപ്പെട്ട ഇഫ്രീത്ത് ഇന്നലെ രാത്രി എന്റെ നിസ്കാരം നഷ്ടപ്പെടുത്താൻ എന്റെമേൽ ചാടിവീണു -അല്ലെങ്കിൽ ഇതുപോലൊരു വചനമാണ് പ്രവാചകൻ പറഞ്ഞത്-. അവനെ അധീനപ്പെടുത്താൻ അല്ലാഹു എനിക്ക് സൗകര്യം ചെയ്തു തന്നു. നേരം പുലർന്ന് നിങ്ങളെല്ലാവരും അവനെ കാണുന്നതുവരെ അവനെ പള്ളിയുടെ ഒരു തൂണിൽ ബന്ധിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ എന്റെ സഹോദരൻ സുലൈമാൻ നബിയുടെ "എന്റെ രക്ഷിതാവേ, എനിക്കു ശേഷം മറ്റാർക്കും ലഭിക്കാത്ത ആധിപത്യം നീ എനിക്ക് നൽകേണമേ." എന്ന പ്രാർത്ഥന ഞാൻ ഓർത്തുപോയി" (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 279, 279, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْلًا قِبَلَ نَجْدٍ، فَجَاءَتْ بِرَجُلٍ مِنْ بَنِي حَنِيفَةَ يُقَالُ لَهُ ثُمَامَةُ بْنُ أُثَالٍ، سَيِّدُ أَهْلِ الْيَمَامَةِ، فَرُبِطَ بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ. (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) നജ്ദിലേക്ക് ഒരു കുതിരപ്പടയെ അയച്ചു. അവിടെ നിന്നവർ യമാമ നിവാസികളുടെ നായകനും ബനൂഹനീഫ് വംശജനുമായ സുമാമത്തുബ്നു ഉസാലുമായി വന്നു. പള്ളിയുടെ ഒരു മൂലയിൽ അയാൾ ബന്ധിക്കപ്പെട്ടു. (ബു;മു,ദ,ന)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], '{}'::text[], null, null, 280, 280, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَائِشَةَ قَالَتْ: أُصِيبَ سَعْدٌ يَوْمَ الْخَنْدَقِ فِي الْأَكْحَلِ، فَضَرَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْمَةً فِي الْمَسْجِدِ، لِيَعُودَهُ مِنْ قَرِيبٍ، فَلَمْ يَرُعْهُمْ، وَفِي الْمَسْجِدِ خَيْمَةٌ مِنْ بَنِي غِفَارٍ، إِلَّا الدَّمُ يَسِيلُ إِلَيْهِمْ ،فَقَالُوا: يَا أَهْلَ الْخَيْمَةِ مَا هَذَا الَّذِي يَأْتِينَا مِنْ قِبَلِكُمْ؟ فَإِذَا سَعْدٌ يَغْذُو جُرْحُهُ دَمًا، فَمَاتَ فِيهَا. (خ,ن)', 'ആഇശ(റ): സഅ്ദി(റ)ന് ഖൻദഖ് യുദ്ധദിവസം മുഴംകയ്യിലെ മധ്യത്തിലുള്ള ഞരമ്പിന് പരിക്കുപറ്റി. എളുപ്പത്തിൽ സന്ദർശിക്കാൻ വേണ്ടി നബി(സ) പള്ളിയിൽ ഒരു കൂടാരം കെട്ടിക്കൊടുത്തു. ജനങ്ങളെ അദ്ദേഹം ഭയന്നില്ല. ബനൂഗഫ്ഫാർ ഗോത്രക്കാരുടെ ഒരു കൂടാരം പള്ളിയിലുണ്ടായിരുന്നു. അവരുടെ അടുത്തേക്ക് രക്തമൊലിക്കുന്നുണ്ടായിരുന്നു. അവർ ചോദിച്ചു: ഓ ടെന്റു നിവാസികളേ! നിങ്ങളുടെ അടുത്തു നിന്നും ഒലിച്ചു വരുന്നതെന്താണ്? അത് സഅ്ദി(റ)ന്റെ മുറിവിൽ നിന്നുള്ള രക്തമായിരുന്നു. അക്കാരണത്താൽ അദ്ദേഹം മരണപ്പെട്ടു. (ബു,ന)', 'عَائِشَةَ قَالَتْ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 280, 280, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ:كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ أَنْ يَعْتَكِفَ صَلَّى الصُّبْحَ، ثُمَّ دَخَلَ فِي الْمَكَانِ الَّذِي يُرِيدُ أَنْ يَعْتَكِفَ فِيهِ، فَأَرَادَ أَنْ يَعْتَكِفَ الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ، فَأَمَرَ فَضُرِبَ لَهُ خِبَاءٌ، وَأَمَرَتْ حَفْصَةُ فَضُرِبَ لَهَا خِبَاءٌ، فَلَمَّا رَأَتْ زَيْنَبُ خِبَاءَهَا، أَمَرَتْ فَضُرِبَ لَهَا خِبَاءٌ، فَلَمَّا رَأَى ذَلِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ''الْبِرَّ تُرِدْنَ''. فَلَمْ يَعْتَكِفْ فِي رَمَضَانَ، وَاعْتَكَفَ عَشْرًا مِنْ شَوَّالٍ. (ن,جه)', 'ആഇശ(റ): നബി(സ) ഇഅ്തികാഫ് ഇരിക്കാനുദ്ദേശിച്ചാൽ സുബ്ഹി നിസ്കരിക്കുകയും പിന്നെ ഇഅ്തികാഫ് ഇരിക്കാനുദ്ദേശിച്ച സ്ഥലത്തേക്ക് പ്രവേശിക്കുകയും ചെയ്യും. റമദാനിലെ അവസാത്തെ പത്തിൽ ഇഅ്തികാഫ് ഇരിക്കാൻ നബി(സ) ഉദ്ദേശിച്ചു. അങ്ങനെ നബിക്ക് പള്ളിയിൽ ഒരു കൂടാരമുണ്ടാക്കി. ഹഫ്സ്വ(റ)ക്കും ഒരു കൂടാരമുണ്ടാക്കപ്പെട്ടു. സൈനബ്(റ) ഇതു കണ്ടപ്പോൾ അവർക്കും ഒരു കൂടാരമുണ്ടാക്കാൻ ആവശ്യപ്പെട്ടു. ഇത് കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അവർ നന്മയാണ് ഉദ്ദേശിച്ചത്." പിന്നെ റമദാനിൽ നബി(സ) ഇഅ്തികാഫ് ഇരുന്നില്ല. ശവ്വാലിൽ നിന്ന് പത്ത് ദിവസം നബി(സ) ഇഅ്താകാഫ് ഇരിക്കാറുണ്ടായിരുന്നു. (ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 280, 280, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: شَكَوْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنِّي أَشْتَكِي، قَالَ: "طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ". فَطُفْتُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِلَى جَنْبِ الْبَيْتِ يَقْرَأُ بِ{الطُّورِ وَكِتَابٍ مَسْطُورٍ}. (خ)', 'ഉമ്മുസലമ(റ): ഞാൻ രോഗിയാണെന്ന് നബി(സ)യോട് ആവലാതിപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ വാഹനത്തിൽ ജനങ്ങളുടെ പിറകിലായി ചുറ്റുക." ഞാനങ്ങനെ ചുറ്റുമ്പോൾ നബി(സ) വീടിന്റെ ഒരു ഭാഗത്ത് വെച്ച് നിസ്കരിക്കുകയും ''തൂർ വകിതാബിൻ.......'' എന്ന സൂക്തങ്ങൾ പാരായണം ചെയ്യുകയും ചെയ്തു. (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 280, 281, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ عَبْدِ اللَّهِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَافَ فِي حَجَّةِ الْوَدَاعِ عَلَى بَعِيرٍ، يَسْتَلِمُ الرُّكْنَ بِمِحْجَنٍ. (م,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): നബി(സ) വിടവാങ്ങൽ ഹജ്ജ് വേളയിൽ ഒരു ഒട്ടകപ്പുറത്ത് ചുറ്റുകയും വളഞ്ഞ വടി കൊണ്ട് ''റുക്ന്'' സ്പർശിക്കുകയും ചെയ്തു. (മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ ابْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 281, 281, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَنَّ رَجُلَيْنِ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، خَرَجَا مِنْ عِنْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي لَيْلَةٍ مُظْلِمَةٍ، وَمَعَهُمَا مِثْلُ الْمِصْبَاحَيْنِ يُضِيئَانِ بَيْنَ أَيْدِيهِمَا، فَلَمَّا افْتَرَقَا صَارَ مَعَ كُلِّ وَاحِدٍ مِنْهُمَا وَاحِدٌ حَتَّى أَتَى أَهْلَهُ. (خ)', 'അനസ്(റ): നബി(സ)യുടെ സ്വഹാബികളിൽപ്പെട്ട രണ്ടുപേർ ഇരുട്ടുള്ള രാത്രിയിൽ (ഇശാ നിസ്കാരം കഴിഞ്ഞ്) നബി(സ)യുടെ അടുത്തു നിന്നിറങ്ങി. വെളിച്ചം കാണിക്കാനുതകുന്ന രണ്ട് വിളക്കുകൾ പോലുള്ള എന്തോ അവരുടെ കൂടെ ഉണ്ടായിരുന്നു. അങ്ങനെ അവർ വഴിപിരിഞ്ഞപ്പോൾ കുടുംബത്തിൽ എത്തുന്നതുവരെ ഒരോരുത്തരുടെ കൂടെയും ഓരോവിളക്കുകൾ ഉണ്ടായിരുന്നു. (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 281, 281, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَطَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ اللَّهَ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ، فَاخْتَارَ مَا عِنْدَ اللَّهِ". فَبَكَى أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ، فَقُلْتُ فِي نَفْسِي: مَا يُبْكِي هَذَا الشَّيْخَ! إِنْ يَكُنِ اللَّهُ خَيَّرَ عَبْدًا بَيْنَ الدُّنْيَا وَبَيْنَ مَا عِنْدَهُ فَاخْتَارَ مَا عِنْدَ اللَّهِ؟ فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هُوَ الْعَبْدَ، وَكَانَ أَبُو بَكْرٍ أَعْلَمَنَا، قَالَ: "يَا أَبَا بَكْرٍ، لَا تَبْكِ إِنَّ أَمَنَّ النَّاسِ عَلَيَّ فِي صُحْبَتِهِ وَمَالِهِ أَبُو بَكْرٍ، وَلَوْ كُنْتُ مُتَّخِذًا خَلِيلًا مِنْ أُمَّتِي لَاتَّخَذْتُ أَبَا بَكْرٍ، وَلَكِنْ أُخُوَّةُ الْإِسْلَامِ وَمَوَدَّتُهُ لَا يَبْقَيَنَّ فِي الْمَسْجِدِ بَابٌ، إِلَّا سُدَّ إِلَّا بَابُ أَبِي بَكْرٍ". (خ)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ഒരു പ്രസംഗവേളയിൽ നബി(സ) ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹു ഒരു അടിമക്ക് ഇഹലോകത്തിന്റെയും തന്റെ അടുത്തുള്ള അനുഗ്രഹങ്ങളുടെയും ഇടയിൽ നിന്ന് തിരഞ്ഞെടുക്കാനുള്ള സ്വാതന്ത്ര്യം നൽകി. അവൻ അല്ലാഹുവിന്റെ അടുത്തുള്ളതിനെ സ്വീകരിച്ചു." ഇതുകേട്ട് അബൂബക്കർ(റ) കരയാൻ തുടങ്ങി. അപ്പോൾ ഞാൻ മനസ്സിൽ പറഞ്ഞു: ഈ മഹാൻ എന്തിന് കരയുന്നു? അല്ലാഹു ഒരു അടിമക്ക് ഇഹലോകത്തിന്റെയും തന്റെ അടുത്തുള്ള അനുഗ്രഹങ്ങളുടെയും ഇടയിൽ നിന്ന് തിരഞ്ഞെടുക്കാനുള്ള സ്വാതന്ത്ര്യം നൽകിയപ്പോൾ ആ അടിമ അല്ലാഹുവിന്റെ അടുത്തുള്ളതിനെ തിരഞ്ഞെയുത്തു. ആ അടിമ നബി(സ) ആയിരുന്നുവെന്ന് അബൂബക്കർ(റ) ഞങ്ങളോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "ഓ അബൂബക്കർ, നീ കരയരുത്. സൗഹൃദത്തിലും സമ്പത്തിലും ജനങ്ങളിൽവെച്ച് എന്നോടേറ്റവും അനുഗുണൻ അബൂബക്കറാണ്. എന്റെ സമുദായത്തിൽ നിന്നും ഒരാളെ ഞാൻ സുഹൃത്തായി സ്വീകരിച്ചിരുന്നുവെങ്കിൽ അത് അബൂബക്കർ തന്നെയാകുമായിരുന്നു. എന്നാൽ ഇസ്ലാമിക സാഹോദര്യവും സ്നേഹവും ഉത്തമമാണ്. പള്ളിയിൽ അടക്കാത്ത വാതിലായി അവശേഷിക്കുന്നത് അബൂബക്കറിന്റെ വാതിൽ മാത്രമാണ്." (ബു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 281, 281, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ، عَاصِبٌ رَأْسَهُ بِخِرْقَةٍ، فَقَعَدَ عَلَى الْمِنْبَرِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: "إِنَّهُ لَيْسَ مِنَ النَّاسِ أَحَدٌ أَمَنَّ عَلَيَّ فِي نَفْسِهِ وَمَالِهِ مِنْ أَبِي بَكْرِ بْنِ أَبِي قُحَافَةَ، وَلَوْ كُنْتُ مُتَّخِذًا مِنَ النَّاسِ خَلِيلًا، لَاتَّخَذْتُ أَبَا بَكْرٍ خَلِيلًا، وَلَكِنْ خُلَّةُ الْإِسْلَامِ أَفْضَلُ سُدُّوا عَنِّي كُلَّ خَوْخَةٍ فِي هَذَا الْمَسْجِدِ، غَيْرَ خَوْخَةِ أَبِي بَكْرٍ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): മരണരോഗ സമയത്ത് നബി(സ) ഒരു തുണിക്കഷ്ണം തലയിൽ കെട്ടി കൊണ്ട് പള്ളിയിൽ വരികയും, മിമ്പറിൽ ഇരിക്കുകയും അല്ലാഹുവിനെ പുകഴ്ത്തുകയും പ്രകീർത്തിക്കുകയും ചെയ്തശേഷം ഇപ്രകാരം പറഞ്ഞു: "ജനങ്ങളിൽ വെച്ച് ശരീരത്തിലും സമ്പത്തിലും എന്നോടേറ്റവും ഗുണം ചെയ്തവൻ അബൂബക്കറിനേക്കാൾ മറ്റാരുമില്ല. ജനങ്ങളിൽ നിന്നും ഒരാളെ ഞാൻ സുഹൃത്തായി സ്വീകരിച്ചിരുന്നു എങ്കിൽ അതും അബൂബക്കറാകുമായിരുന്നു. പക്ഷേ, ഇസ്ലാമിക സാഹോദര്യം ഏറ്റവും ഉത്തമമാണ്. ഈ പള്ളിയിലെ അബൂബക്കറിന്റെ വാതിൽ (കൂരജനൽ) ഒഴികെയുള്ള എല്ലാ വാതിലുകളും നിങ്ങൾ അടക്കുക." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 281, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ أَبِي سَعِيدِ بْنِ الْمُعَلَّى رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا نَغْدُو إِلَى السُّوقِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَمُرُّ عَلَى الْمَسْجِدِ فَنُصَلِّي فِيهِ. (ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): രാവിലെ ഞങ്ങൾ അങ്ങാടിയിലേക്ക് പള്ളിക്കരികിലൂടെ പോവുകയും, പള്ളിയിൽ നിന്ന് നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'أَبِي سَعِيدِ بْنِ الْمُعَلَّى', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 282, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "هَلْ تَرَوْنَ قِبْلَتِي هَا هُنَا، فَوَاللَّهِ، مَا يَخْفَى عَلَيَّ خُشُوعُكُمْ وَلَا رُكُوعُكُمْ، إِنِّي لَأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഇവിടെയുള്ള എന്റെ ഖിബ്ല കാണുന്നുണ്ടോ? അല്ലാഹുവാണെ, നിങ്ങളുടെ ഭയഭക്തിയും റുകൂഉം എനിക്ക് അവ്യക്തമാകുന്നില്ല. തീർച്ചയായും എന്റെ പിന്നിലൂടെ ഞാൻ നിങ്ങളെ കാണുന്നുണ്ട്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 282, 282, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ وَلِيدَةً كَانَتْ سَوْدَاءَ لِحَيٍّ مِنَ الْعَرَبِ، فَأَعْتَقُوهَا فَكَانَتْ مَعَهُمْ قَالَتْ: فَخَرَجَتْ صَبِيَّةٌ لَهُمْ عَلَيْهَا وِشَاحٌ أَحْمَرُ مِنْ سُيُورٍ، قَالَتْ: فَوَضَعَتْهُ أَوْ وَقَعَ مِنْهَا فَمَرَّتْ بِهِ حُدَيَّاةٌ وَهُوَ مُلْقًى فَحَسِبَتْهُ لَحْمًا فَخَطِفَتْهُ، قَالَتْ: فَالْتَمَسُوهُ فَلَمْ يَجِدُوهُ قَالَتْ: فَاتَّهَمُونِي بِهِ قَالَتْ: فَطَفِقُوا يُفَتِّشُونَ حَتَّى فَتَّشُوا قُبُلَهَا قَالَتْ: وَاللَّهِ إِنِّي لَقَائِمَةٌ مَعَهُمْ إِذْ مَرَّتِ الْحُدَيَّاةُ فَأَلْقَتْهُ قَالَتْ: فَوَقَعَ بَيْنَهُمْ قَالَتْ: فَقُلْتُ هَذَا الَّذِي اتَّهَمْتُمُونِي بِهِ زَعَمْتُمْ وَأَنَا مِنْهُ بَرِيئَةٌ وَهُوَ ذَا هُوَ، قَالَتْ: فَجَاءَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمَتْ، قَالَتْ عَائِشَةُ: فَكَانَ لَهَا خِبَاءٌ فِي الْمَسْجِدِ أَوْ حِفْشٌ قَالَتْ: فَكَانَتْ تَأْتِينِي فَتَحَدَّثُ عِنْدِي، قَالَتْ: فَلَا تَجْلِسُ عِنْدِي مَجْلِسًا إِلَّا قَالَتْ: وَيَوْمَ الْوِشَاحِ مِنْ أَعَاجِيبِ رَبِّنَا أَلَا إِنَّهُ مِنْ بَلْدَةِ الْكُفْرِ أَنْجَانِي قَالَتْ عَائِشَةُ: فَقُلْتُ لَهَا: مَا شَأْنُكِ لَا تَقْعُدِينَ مَعِي مَقْعَدًا إِلَّا قُلْتِ هَذَا؟ قَالَتْ: فَحَدَّثَتْنِي بِهَذَا الْحَدِيثِ. (خ)', 'ആഇശ(റ): ഒരു അറബ് ഗോത്രത്തിൽ കറുത്ത ഒരു അടിമ സ്ത്രീയുണ്ടായിരുന്നു. അവർ അവളെ സ്വതന്ത്രയാക്കി. അവൾ അവരോടൊപ്പം ജീവിച്ചു. അവൾ പറഞ്ഞു: അവരിൽപ്പെട്ട ഒരു പെൺകുട്ടി തോലിന്റെ ഒരു ചുവന്ന അരപ്പട്ട ധരിച്ച് പുറത്തിറങ്ങി. അവളിൽ നിന്ന് അരപ്പട്ട വീണു പോവുകയോ, അവളത് എവിടെയോ വെക്കുകയോ ചെയ്തു. ആ വഴി സഞ്ചരിച്ച പരുന്തുകൾ ഇറച്ചിക്കഷ്ണമാണെന്നു കരുതി അത് കൊത്തിയെടുത്തു. അവരത് അന്വേഷിച്ചെങ്കിലും കിട്ടിയില്ല. അവർ എന്നെ തെറ്റിദ്ധരിക്കുകയും, എന്റെ ഗുഹ്യസ്ഥാനംപോലും പരിശോധിക്കുകയും ചെയ്തു. അല്ലാഹുവാണെ, ഞാനവരുടെ കൂട്ടത്തിൽ നിൽക്കുമ്പോൾ ഒരു പരുന്ത് പാറിവന്ന് ആ അരപ്പട്ട താഴേക്കിട്ടു. അവരുടെ ഇടയിൽ അത് വീണു. അവൾ പറഞ്ഞു: ഈ സാധനത്തെക്കുറിച്ചാണ് നിങ്ങൾ എന്നെ തെറ്റിദ്ധരിച്ചത്. ഞാൻ നിരപരാധിയാണ്. ആ സാധനമിതാ. അങ്ങനെ അവൾ പ്രവാചകന്റെ അടുക്കൽ ചെന്ന് മുസ്ലിമായി. ആഇശ(റ) പറഞ്ഞു: അവൾക്ക് പള്ളിയിൽ ഒരു കൂടാരമുണ്ടായിരുന്നു. അവൾ എന്റെ അടുത്ത് വരികയും എന്നോട് സംസാരിക്കുകയും ചെയ്യും. അപ്പോഴെല്ലാം അവൾ ഇപ്രകാരം പാടും:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَبِي الْوَلِيدِ رَضِيَ اللَّهُ عَنْهُ: سَأَلْتُ ابْنَ عُمَرَ عَنِ الْحَصَى الَّذِي فِي الْمَسْجِدِ فَقَالَ: مُطِرْنَا ذَاتَ لَيْلَةٍ، فَأَصْبَحَتِ الْأَرْضُ مُبْتَلَّةً، فَجَعَلَ الرَّجُلُ يَأْتِي بِالْحَصَى فِي ثَوْبِهِ فَيَبْسُطُهُ تَحْتَهُ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ قَالَ: "مَا أَحْسَنَ هَذَا". (د)', 'അബുൽവലീദ്(റ): പള്ളിയിലെ ചരൽകല്ലിനെക്കുറിച്ച് ഇബ്നുഉമറി(റ)നോട് ഞാൻ ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഒരു രാത്രി ഞങ്ങൾക്ക് നല്ല മഴ കിട്ടി, ഭൂമി നനഞ്ഞു. അങ്ങനെ ഓരോരുത്തരും വസ്ത്രത്തിൽ ചരൽകല്ലുകൾ കൊണ്ടുവന്ന് നിലത്ത് പരത്തി. നിസ്കാരം കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് വളരെ നന്നായിട്ടുണ്ട്." (ദ)', 'أَبِي الْوَلِيدِ', 'അബുൽവലീദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَدْ رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إِنَّ الْحَصَاةَ لَتُنَاشِدُ الَّذِي يُخْرِجُهَا مِنَ الْمَسْجِدِ".(د)', 'അബൂഹുറൈറ(റ): (ഈ ഹദീസ് നബി(സ)യിലേക്ക് ഉയർത്തിയിട്ടുണ്ട്) അദ്ദേഹം പറഞ്ഞു: "ചരൽകല്ലിനെ പള്ളിയിൽ നിന്ന് നീക്കുന്നവനെക്കുറിച്ച് അത് അല്ലാഹുവോട് സാക്ഷി പറയും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 283, 283, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: دَخَلَ رَجُلٌ عَلَى جَمَلٍ، فَأَنَاخَهُ فِي الْمَسْجِدِ ثُمَّ عَقَلَهُ، ثُمَّ قَالَ: أَيُّكُمْ مُحَمَّدٌ؟ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُتَّكِئٌ بَيْنَ ظَهْرَانَيْهِمْ، فَقُلْنَا لَهُ: هَذَا الْأَبْيَضُ الْمُتَّكِئُ، فَقَالَ لَهُ الرَّجُلُ: يَا ابْنَ عَبْدِ الْمُطَّلِبِ، فَقَالَ لَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدْ أَجَبْتُكَ". فَقَالَ لَهُ الرَّجُلُ: يَا مُحَمَّدُ، إِنِّي سَائِلُكَ........ وَسَاقَ الْحَدِيثَ. (خ,د,ن,جه)', 'അനസുബ്നു മാലിക്(റ): ഒട്ടകപ്പുറത്ത് ഒരാൾ വന്നു. അതിനെ പള്ളിയുടെ അടുത്ത് മുട്ടുകുത്തിക്കുകയും, അതിനെ ബന്ധിക്കുകയും ചെയ്തശേഷം ചോദിച്ചു: നിങ്ങളിൽ ആരാണ് മുഹമ്മദ്? നബി(സ) അവരുടെ ഇടയിൽ ചാരിയിരിക്കുന്നുണ്ടായിരുന്നു. ഞങ്ങൾ അദ്ദേഹത്തോട് പറഞ്ഞു: ഈ ചാരിയിരിക്കുന്ന വെളുത്ത വ്യക്തിയാണ്. അയാൾ പറഞ്ഞു: അബ്ദുൽ മുത്വലിബ് സന്തതിയെ, നബി(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് ഉത്തരം ചെയ്തിരിക്കുന്നു." അയാൾ പറഞ്ഞു: മുഹമ്മദെ, ഞാൻ നിന്നോട് ചോദിക്കുന്നു........... റാവി ഹദീസ് തുടർന്ന് പറഞ്ഞു. (ബു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 283, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَ بَنُو سَعْدِ بْنِ بَكْرٍ ضِمَامَ بْنَ ثَعْلَبَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَدِمَ عَلَيْهِ، فَأَنَاخَ بَعِيرَهُ عَلَى بَابِ الْمَسْجِدِ، ثُمَّ عَقَلَهُ، ثُمَّ دَخَلَ الْمَسْجِدَ... فَذَكَرَ نَحْوَهُ ....قَالَ: فَقَالَ: أَيُّكُمُ ابْنُ عَبْدِ الْمُطَّلِبِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَنَا ابْنُ عَبْدِ الْمُطَّلِبِ". قَالَ: يَا ابْنَ عَبْدِ الْمُطَّلِبِ.... وَسَاقَ الْحَدِيثَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ബനൂസഅ്ദുബ്നു ബക്ർ ദിമാമുബ്നു സഅ്ലബയെ റസൂലിന്റെ അടുക്കലേക്കയച്ചു. അദ്ദേഹം വന്ന് പള്ളിയുടെ വാതിൽക്കൽ ഒട്ടകത്തെ മുട്ടുകുത്തിക്കുകയും, അതിനെ ബന്ധിക്കുകയും ചെയ്തശേഷം പള്ളിയിൽ പ്രവേശിച്ചു. എന്നിട്ട് ചോദിച്ചു: ആരാണ് അബ്ദുൽ മുത്വലിബിന്റെ മകൻ? നബി(സ) പറഞ്ഞു: "ഞാനാണ് മുത്വലിബിന്റെ മകൻ." അദ്ദേഹം പറഞ്ഞു: മുത്വലിബിന്റെ മകനേ,........... ഹദീസ് തുടരുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 284, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: الْيَهُودُ أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ جَالِسٌ فِي الْمَسْجِدِ فِي أَصْحَابِهِ، فَقَالُوا: يَا أَبَا الْقَاسِمِ...... فِي رَجُلٍ وَامْرَأَةٍ زَنَيَا مِنْهُمْ. (د)', 'അബൂഹുറൈറ(റ): നബി(സ) സ്വഹാബികൾക്കിടയിൽ പള്ളിയിൽ ഇരിക്കവെ ജൂതന്മാർ തിരുമേനിയുടെ അടുക്കൽ വന്നു. അവർ ചോദിച്ചു: അബുൽ ഖാസിമേ......... അവരിൽപെട്ട വ്യഭിചരിച്ച സ്ത്രീയെയും പുരുഷനെയും എന്തു ചെയ്യണം? (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 284, 284, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=14 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
